/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240122-6","meetingId":"r06-cm01","date":"2024年1月22日","dateIso":"2024-01-22","committee":"区民委員会","time":"午後 １時００分～午後 ４時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区再犯防止推進計画（素案）に係るパブリックコメントの結果","agenda":"品川区再犯防止推進計画（素案）に係るパブリックコメントの結果","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"件数としては、１０件ですね。パブリックコメントとしては、少し少ないかなと私は感じているのですけれども、そこで寄せられた意見、私も見せていただきましたが、文言等の整理等が多いかなというところで、この計画自体、まだ素案ですけれども、仕上げていくに当たっての意見や、課題というか、何かもう少しこうしたほうがいいのではないかなど、今の時点であればお伺いできればと思います。","respondent":"宮澤地域活動課長","answer":"こういったご意見を踏まえて、また５年後には改定をする予定でもありますので、今後計画が動き出してから、状況等を踏まえながら検討していきたいなというところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"区として再犯防止推進をしていくということで、要は犯罪をしてしまった方々に対して、また、少し若い層の、素案の中にも、薬物事犯の割合が大きいということもあったりするので、こうしたことを区は、この計画をつくっているのは地域振興部ですけれども、そうすると、そのような若い人たちの犯罪というところでいうと、児童相談所などと、計画との関わりで何か連携していく部分というのはあるのですか。","respondent":"宮澤地域活動課長","answer":"この再犯防止推進計画を策定して、庁内の関係課から再犯防止推進委員会にも入っていただいて、そこで全庁的に、横断的に検討していくという中で、この計画になっております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"えのした委員","kind":"質問・要望","question":"私も議員になる前から保護司として活動しておりまして、昨年、同じ会派のせお議員から、山本譲司さんの『獄窓記』の話がありまして、私も『累犯障害者』を読ませていただきましたが、昨年刑務所にも視察に行ってお話を伺ったところ、やはり高齢者が多い、障害者も多いと。これから５年間を経て見直しになると思いますが、丁寧に進めていただければと思います。こちらは一つ要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"そもそも論なのですけれども、なぜこの再犯防止推進計画を地域活動課でやることになったのですかということが１点と、この再犯防止推進委員会には、例えば民生委員などが入っていらっしゃるのでしたか。民生委員だと、福祉部ですよね。保護司の課だと、地域活動課ではないですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"地域活動課ですか。では、先ほど全庁的とおっしゃっていたけれども、具体的にどのような形になっているのかということが２点目です。それと、実際に現場に接していると思う生活安全担当課長、この素案がこのような形で上がってきているのですが、これ、現場を知っている方が見てどのように感じられるか、教えていただけますか。","respondent":"宮澤地域活動課長、河合生活安全担当課長","answer":"ただ、犯罪を犯してしまった方への支援は様々な部署で行っておりますので、再犯防止推進委員会という形で関係各課にも携わっていただき、計画を策定、素案の検討をしてきたです。私のほうから現場サイド、警察の立ち位置ということだとは思うのですけれども、再犯防止というところで、犯罪を犯してしまった方は、孤立しがちになりますとやはり再犯率が高くなりますので、区。","voiceIndex":12,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問・要望","question":"今日のこれは素案ですから、ここまで踏み込んではいけないと思うのですけれども、確かに再犯防止するということは大事だと思うのですが、犯罪ということにおいていうならば、その犯罪が起きたときに、加害者、被害者ということで分けるならば、被害者もいるわけです。再犯防止は大事なのです。そのような流れというものは、今答えられる範囲でどのような形になっているのでしょうか。","respondent":"宮澤地域活動課長、河合生活安全担当課長","answer":"例えば別紙２の９のご意見を見ていただきますと、犯罪被害者支援というところで、区民相談室で情報提供や助言、また、区内の４警察署と合同でのキャンペーンを実施しているというところです。地域活動課長から話がありましたとおり、関係部署が連携してということで、区のほうですと生活安全担当と人権啓発課、広報広聴課で、相談者の、被害者の窓口を広くつくりまして、それに基づいて、ニーズへの対応等はそれぞれが担当して。","voiceIndex":15,"id":"exchange-006"},{"speaker":"横山委員","kind":"確認","question":"１点確認なのです。パブリックコメントは今回５名の方から１０件いただいたということで、こちらの計画に関することなのですが、ほかの部署にも関わるような、いろいろなご意見があるかと思うのですけれども、そうした部分は連携いただいたり、情報共有いただいてという形で、計画に反映するとともに、ご意見としてどのように伝わっているのかなというところを確認させてください。","respondent":"宮澤地域活動課長","answer":"パブリックコメントでいただきましたご意見の中には、地域活動課の所管を超えたものもございました。それらに踏まえましては、該当する担当部署に、ご意見の内容とともに区の考え方という部分に関しても、作成に協力いただきながらやっているところです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"横山委員","kind":"意見","question":"ぜひ今回はこういった形で、いろいろ情報共有等をしていただきながら、例えば人権とは何かというところ、人権の対象者は誰なのかというところであったり、あとは地域活動課の所管からは少し外れてしまいますが、いじめの課題に対して、被害者、加害者双方へのメンタルサポートの強化というようなご意見であったり、あと再犯防止の観点からは、やはりその方々の生まれ育った家庭環境や病気、障害など。","respondent":"宮澤地域活動課長","answer":"委員ご指摘のとおり、今回こういった形で事業の体系化、また見える化ということで、これまで取り組んでいる支援を一つ総合的に、計画に載せました。今後、それぞれの部署との横の連携は引き続き行っていきながら進めていきたいと考えているところです。","voiceIndex":21,"id":"exchange-008"}]},{"id":"topic-02","title":"戸籍法改正（令和６年３月１日施行）による戸籍事務の変更","agenda":"戸籍法改正（令和６年３月１日施行）による戸籍事務の変更","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"それで、営業日で３日間とか、５日間とか置かないと取得できないというような仕組みになっておりますが、今回、この法改正によって、品川区の窓口に行った場合に、もうその場でやり取りをして、電子的な形で、先方の役所の、いわゆる人的なものとはやり取りをしないで、もうオンライン上で全てやり取りをして、その場で他自治体での本籍地の戸籍が取れるようになる、戸籍謄本が取れるようになるという。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおり、その場で即時でオンラインでつながって、即時発行が可能になります。","voiceIndex":27,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"今まで相続の手続き等で、いわゆる亡くなった方の出生から逝去までの戸籍を全て取らなければいけないということがあって、そのやり取りは、本籍が変わっていて、役所が変わっていて、それを探すという結構大変な作業があって、それを専門家等に依頼をしていることもあるのですけれども、例えば、品川区の窓口に行って、個人の出生から逝去までの全ての戸籍謄本が欲しいのですけれどもとお願いをした場合には。","respondent":"吉野戸籍住民課長","answer":"出生から死亡まで全部調べて、その場で交付します。","voiceIndex":29,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"それで足りなければまた追加で請求が来たりして、そのような非常な苦労があったのですが、そのようなものも一瞬というか、その１回の手続きで、利用者が来ればそれは終わるという認識でよいか、最後にこれだけお伺いします。","respondent":"吉野戸籍住民課長","answer":"ただ、やはりデータの持ち方というのが、昔の戸籍はＰＤＦの形になっているのです。ですから、ちょっと中を見なければいけないということもありますので、すぐにではないのですけれども、お時間をいただいて、全部の発行は可能です。","voiceIndex":31,"id":"exchange-011"},{"speaker":"横山委員","kind":"確認","question":"今のところで少し確認なのですけれども、法務省のホームページを見ると、「コンピュータ化されていない一部の戸籍・除籍を除きます」と書いてあるのですが、ＰＤＦ化されていればコンピュータ化されているという認識でよろしいのでしょうか。その辺りを教えてください。","respondent":"吉野戸籍住民課長","answer":"一応法務省のほうでは今そのような形になっているのですけれども、令和２年に大体データ化できたというような話を伺っております。","voiceIndex":34,"id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問","question":"すみません、もう１点だけ。例えば戸籍を遡るということは、先ほど直系尊属であればできるということになっていますが、これは今までもそうだったと。特に今回のことに関して、この手続きで兄弟は駄目となっていますけれども、特に何かそこは、狭まったり広まったりということはないと。今までの手続きどおりで変わらないということでよろしいのでしょうか。","respondent":"吉野戸籍住民課長","answer":"今までは本籍地であれば、いわゆる第三者請求などといったものができました。いわゆる兄弟で委任したり、そういったことができたのですが、今回の広域交付に関しましては、他自治体にもわたりますので、これに関しては、直系尊属、直系卑属のみが対象になります。","voiceIndex":37,"id":"exchange-013"}]},{"id":"topic-03","title":"本日は、昨年７月４日の委員会において決定いたしました所管事務調査項目のうち、町会・自治会支援","agenda":"本日は、昨年７月４日の委員会において決定いたしました所管事務調査項目のうち、町会・自治会支援","exchanges":[{"speaker":"せらく委員","kind":"質問","question":"マンションとの関係づくりのことで少し質問したいのですけれども、建設時からのお付き合いで加入促進というところで、手引を作成するといったご説明をいただきましたが、町会からのお話を聞いていると、やはりワンルームマンションばかり建つだとか、そういったところで若者の一人暮らしが増えていると、そのような声が届いておりました。","respondent":"宮澤地域活動課長","answer":"町会とマンションとの関係づくりということで、委員ご指摘のとおり、いわゆるファミリー世帯向けの分譲マンション以外にも、やはり小規模でもワンルームマンション等の加入に苦慮しているという町会のお声は聞いて、認識しているところです。","voiceIndex":46,"id":"exchange-014"},{"speaker":"せらく委員","kind":"質問","question":"もう１点、ＩＣＴ活用促進補助金についてなのですけれども、ここが予算に対してなかなか執行が少ないという状況なのです。この場合、コンサルタントを町会・自治会に派遣してということで、今、５町会に派遣されていて、これは毎年同じ町会が申請というか、利用できるものなのか、利用回数制限などがあるのかを教えていただけますでしょうか。","respondent":"宮澤地域活動課長","answer":"必要があれば継続的に支援をしていきたいというところです。年度ごとに、今年度行っている５町会に対しても、７月ぐらいから、毎月コンサルタントを含めて会合を持ちながら、支援を進めているというような形です。","voiceIndex":48,"id":"exchange-015"},{"speaker":"せらく委員","kind":"確認","question":"今、町会へ利用するかどうか聞いているというところで、やはり役員の高齢化がある中で、こういう支援がありますよと出しておくだけではなかなか利用が進まないと思ったので、そのように町会に確認していただいているということで安心いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-016"},{"speaker":"えのした委員","kind":"質問・要望","question":"２３区で初となる品川区町会および自治会の活動活性化の推進に関する条例。地域の不動産業者がお話ししていたのですけれども、やはり条例があると、店舗やお引っ越しの方に町会に入ってくださいということをすごく促しやすくて、条例ができて本当によかったというお話も伺っております。ただ、これをもう少し落とし込んでというか、読んでいてこの事業名はなかなか難しいと思うのです。これは要望です。","respondent":"宮澤地域活動課長","answer":"それで、届出がなされましたら、その該当する町会・自治会に、届出が出ていますがその情報を開示しますかというお声かけはするところではあるのですけれども、それでお伝えして連絡を取ったというケースもお聞きしておりますし、建築時というところでもありますので。","voiceIndex":51,"id":"exchange-017"},{"speaker":"えのした委員","kind":"質問","question":"今の地域連絡調整員ですか、これは先ほど、せらく委員からもマンションの加入率もありましたけれども、これはマンションが建った後だと、結局、マンションの組合の管理規則、規約というのですか、その中に盛り込まれていないと、もうそもそも町会に入らなくていいなどということになってしまいますので、ぜひ、この地域連絡調整員という方がいらっしゃるのであれば、区からも町会へ声かけをしていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"すみません、これはありがたいのですが、人工でいくと、そうすると半額ぐらい出していただけると、町会も様々予算状況があって、うちは３基買えましたけれども、４５万円ぐらいはかかったというところもありまして、そのうち１５万円は区から助成が出たということなのですが、多分これが決まったときと比べると、大分、また時代とともに物価高騰もあって、金額も上がってきたりもしておりまして。","respondent":"宮澤地域活動課長","answer":"そのようなサポートをさせていただいています。ただ、町会・自治会からの相談というのは、ここ数年はないですが、平成２６年から始めておりますけれども、過去、複数の相談はあって、それに対応しているという状況です。","voiceIndex":54,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"提案","question":"たしか前に私が質問したときに、今、区内で集合住宅は８割、これは全てが分譲マンションではないですが、８割という中で百十数件という、地域連絡調整員の確認ができている数ですから、そこのところを、ここが地域連絡調整員ですよと示すようなもの、町会・自治会の方が分かるようなものをぜひ。この一覧になっているものは、今町会・自治会支援の全てが載っているのですか。","respondent":"宮澤地域活動課長","answer":"運営サポートという形で、例えば行政書士であったり、弁護士であったりというところ、また、他課でも町会・自治会に対して支援している、補助金を含めたメニューなどもありますので、そのようなものを含めたものの一覧というのも作成して。","voiceIndex":56,"id":"exchange-020"},{"speaker":"横山委員","kind":"確認","question":"幾つか確認になるのですけれども、２の具体的取り組みについての（３）好事例集の作成・配付なのですが、こちらは令和４年度のものと、その後の、例えばこのコンサルタントの部分であったり、交流会等でいろいろとマンションの部分であったり、マンションの住民の方であったり、そういった側からのご意見や、子育て中の若い世代の方からのご意見などというような。","respondent":"宮澤地域活動課長","answer":"令和４年度から伴走型支援に取り組んでおりますし、交流会も開いておりまして、コンサルタントを活用しておりまして、そのコンサルタントのまとめた報告書、そこにどこの町会にどのような支援をしたという取組と。","voiceIndex":59,"id":"exchange-021"},{"speaker":"横山委員","kind":"質問・要望","question":"接点づくりというような形で好事例集にも書いてありましたけれども、小さい形で取り組みやすいような、大きな一歩を踏み出すということはなかなか、ちょっと時代的にも難しいところがあると思うのですけれども、お互いの顔の見える関係のような形で一歩進んでいただくということが、今のタイミングではすごく重要だと思いますので、この（１）の部分に関して。","respondent":"宮澤地域活動課長","answer":"地域の多様な団体との、いわゆる連携強化ですけれども、これまでも、例えばＮＰＯと町会がコラボしてやるというところで、町会の会員向けにスマホの、いわゆるデジタル・デバイド対策なのですが、スマホの取扱いの説明会というものを。","voiceIndex":61,"id":"exchange-022"},{"speaker":"横山委員","kind":"質問・要望","question":"いろいろ求めている、例えば課題同士とか、課題とその解決の手段、スキルを持っているＮＰＯだったとしても、様々な観点で、マッチングというのは難しさがすごくあると思いますので、その辺りもやはりコンサルタントの知見を活かしていただいたり、あまり焦り過ぎずに、事業に、何か実績に結びつけるというところは長期的なゴールとして持ちつつも、まず第一歩としてはやはり関係性づくり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-023"},{"speaker":"山本委員","kind":"確認","question":"これまでのご説明ありがとうございました。その中で改めての確認になるのですけれども、町会・自治会として新規加入率がなかなか上がらない、それから、イベント等の活動参加がなかなか増えないと町会・自治会が思っているというところなのですが、区としては、それに対してどうしてだと思っていらっしゃいますでしょうか。お聞かせください。","respondent":"宮澤地域活動課長","answer":"なかなか役員含めて、担い手が不足している背景には、やはり固定化というところ、新たなやろうとする方をなかなか見込めないというところが原因なのかなです。","voiceIndex":65,"id":"exchange-024"},{"speaker":"山本委員","kind":"質問","question":"ですから、そういったそれぞれの地域での行事を、住んでいる多くの皆様にいかに知っていただくかということは課題なのかなと思っておりまして、それを今、それぞれの町会に任せているというか、主に地域の掲示板だったり、回覧板だったりが主かと考えていますが、また、町会によっては町会のＳＮＳやウェブサイトなど、それぞれ町会によってばらつきがあると思うのですけれども。","respondent":"宮澤地域活動課長","answer":"町会ごとというところもありますけれども、品川区町会・自治会連合会のホームページ等でも、このような活動をしましたというイベントの実施報告等も含めて、お知らせしながらしているというところもあります。","voiceIndex":67,"id":"exchange-025"},{"speaker":"山本委員","kind":"質問・要望","question":"そういった方々にもしっかりと発信をしていって、今メリットがないと思って入っていない方にも、入っていただくことにメリットがあると感じていただくために、引っ越しでの転入の方だけではなくて、それ以外の方々にもきちんと届くような発信をしていただきたいということが一つ、これは要望です。そのようなものをぜひ実現していただきたいなと思っているのですが、これについてのお考えをお聞かせください。","respondent":"宮澤地域活動課長","answer":"ただ、先ほど町会・自治会連合会のホームページ等でも、そういったツールもあります。そういったところに関しましては、最も身近な支援をしている地域センター等もありますので、相談等に乗りながら対応していきたいなと考えているところです。","voiceIndex":69,"id":"exchange-026"},{"speaker":"山本委員","kind":"質問・要望","question":"タイムリーさもあると思うのですけれども、いろいろなイベント、現状は観光協会だったり、民間のサイトだったりなどと、いろいろなところが様々な情報発信をされて、ああ、このようなものがあるのだなと、それぞれ区民の皆さんは気づいて、行かれたりしていると思うのですが、せっかく連合会としてこのようなホームページがあって、イベント自体あるものが分かっていれば、それを周知したり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう１回考える必要があると思うのですけれども、その辺はいかがですか。たしか山口市のテーマは町会などだったけれども、加入率が全然違うではないですか。違いますよね。８０％を超えていたところがありましたよね。自治会支援という意味で、今八潮はどうなっているのですか。いろいろどうなっているのかということと、それと八潮地区においては、外国の方々はどのぐらいの人数いらっしゃるのでしょうか。","respondent":"宮澤地域活動課長、川島地域振興部長、中西八潮まちづくり担当課長","answer":"それでこうすればいいということもなかなか難しいのですが、やはり若い世帯に活動に参加してもらうには。やはり先ほど来答弁させていただいていますが、マンションの増加というのは非常に大きくて、新築の大規模マンションが増えてくるに伴って。ただ、新しく自治会長、それから役員になられた方と直接、私も少しお話をさせていただいたのですか、やはり役員の固定化、それから。","voiceIndex":73,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"いろいろなイベントがある中で、本当に悲しい出来事だったのですが、１月１日に地震が起きたわけですから、いつ東京にも地震があるか分からないという意味においても、１回、町会単位で、単位というのは町会ごとという意味ではなくて、地域センター内でもいいし、品川区全部でもいいけれども、防災という意味でなぜ町会組織が必要か。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"何かあまり変わっていない感じが私は少ししているのですけれども、この課題の推移というのですか、変化はあるのか。それで町会・自治会が求めている支援、これもずっと言われていることのような感じがしているのですが、ここの変化というものもあれば教えていただきたいです。","respondent":"宮澤地域活動課長","answer":"今年度新宿区のほうで検討委員会を設けて、検討しているということは聞いている状況です。続いて、課題や求めている支援の変化ですけれども、加入の減少であったり、高齢化というのは、やはり条例制定時から引き続いている課題なのかなというところはあります。","voiceIndex":79,"id":"exchange-030"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やはりその課題や求めている支援にどう応えていくかというところで、区としても様々支援策を打ち出して、増やしたりしてきていると思うのです。この伴走型支援プログラム、昨年度が５町会で、今年度も今の時点で５町会ということですけれども、これは別に５町会に区切っているわけではなくて、使っていただけるならもっと使ってもらいたいというものと考えていいのですか。","respondent":"宮澤地域活動課長","answer":"伴走型支援のところ、他区の事例という話もありましたが、実は先ほどの交流会では第１回目の、協働の部分に関しては、港区の町会長をお招きしてお話を聞いたというところもあります。","voiceIndex":81,"id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"本当に様々交流しながら、連携しながら施策を打ってきているというところでは、引き続きよろしくお願いしますという状況にはなってしまうのですが、私たち自身も様々、これを聞いた上で一緒に存続させていく、そしてさらに大きいものにしていくというところでは、連携していきたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-032"}]},{"id":"topic-04","title":"の中小企業支援","agenda":"の中小企業支援","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"モンゴル高専は５年生制だということで、まずどのくらいの人数の方が通われているのかなというところを確認したいです。今後の主な連携先のモンゴル高専３校ということですが、その学校の規模などもお聞かせいただきたいと思います。","respondent":"小林商業・ものづくり課長","answer":"その上で品川区として、品川区の中で長く働き続けていただくための支援や、あるいは企業のほうでも先輩職員をきちんと指導役につけまして、一緒に働くようなチームワークづくりというものはやっていただいておりますけれども。","voiceIndex":91,"id":"exchange-033"},{"speaker":"えのした委員","kind":"質問・要望","question":"モンゴル高専出身で就職された方がその地域に住むときに、町会にご紹介したり、モンゴルから来ているのですから、またそこで交流が広がったりして、就職後の定着につながるのかなと考えています。そういった取組も、ぜひしていただければと思います。これは要望として終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-034"},{"speaker":"横山委員","kind":"質問","question":"質問なのですけれども、この人材育成の部分で、ＤＸ・デジタル技術の部分の人材がなかなか足りていない、不足しているというお話が、割といろいろなところであるのかなと思うのですが、デジタル、ＩＣＴに関するスキルというものも、細分化するといろいろあるのかなと思っていまして、例えばなのですけれども、東京都のデジタルスキルマップのような形で、これは職員向けにつくられたものだと思うのですが。","respondent":"小林商業・ものづくり課長","answer":"実際に中小企業の人材というところでいきますと、さすがに全社員、全てということはなかなか難しいところでありますけれども、品川区の問題意識としまして、その中小企業の中で中核的にＩＴの利用を進めていただけるような、リーダーといいますか。","voiceIndex":95,"id":"exchange-035"},{"speaker":"横山委員","kind":"提案","question":"現在は社長であったり、経営者の方であったり、会社の中でのＩＣＴのリーダーのような方に、どういったことがデジタル技術を使ってできそうかというところを幅広く勉強するようなセミナーであったり、体験会を行っていただいているということで、その次の段階としては、細かく、どういった分野でどういった人材が必要なのかというような形で提案していただいたり、または社内でレベルアップというか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう１回言います。でも中小企業支援についてという項目の中で、私はまずは日本の方の確保も大事だと思うのですけれども、その辺についてはいかがですか。それと、創業支援・スタートアップなのですけれども、なぜ、そもそもスタートアップに関して、区は支援するのでしょうか。その辺についてはいかがでしょうか。この辺について、観光の立場からどのように思うか教えていただけますか。","respondent":"小林商業・ものづくり課長、篠田文化観光課長","answer":"そのような中で少しでも、若手で将来的に会社の中できちんと活躍してくれるような人材といったときに、ある程度能力を持っているというところでいったときに、先ほど申し上げたようなモンゴル高専というのは。ただ、品川区の都市型観光については、いわゆる地域の特徴を活かしたものということで、それぞれ対外的にどのような見せ方をしていくかということを考えながら進めていくことが基本にありますので、五反田バレーは。","voiceIndex":99,"id":"exchange-037"},{"speaker":"藤原委員","kind":"質問・要望","question":"すばらしいです。もう１回人材確保について。モンゴル高専もすばらしいのだけれども、その施策が終わって５年以上経ってしまっているので、もう１回その辺を考えていただきたいという思いがありますし、すごくいいことは、昔、その中小企業振興をされていた課長が部長になって、今ＳＨＩＰへ行っているではないですか。そのような思いで質問をしているので、ぜひそれについて答弁をいただきたいと思います。","respondent":"小林商業・ものづくり課長","answer":"今回の資料にも書かせていただき、私の説明にも少し入れておりましたけれども、特に若手、学生というのですか、そのような方がなるべく来やすいようにということで、スタッフというか、経営相談に乗るような人材についても、特に若手の人材を少し意識して入れるようにもしていて。","voiceIndex":102,"id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"そこがスタートアップなのです。スタートアップが、スタートアップのために創業してやられるわけではないですか。でも、その中で大きい会社になる可能性というのもあるわけです。西大井創業支援センターから上場している会社が出ているのですから。そのために品川区としては税金を投入して、スタートアップ事業を支援していっていただきたいという思いがあります。最後にもう１回、この辺を答弁してください。","respondent":"小林商業・ものづくり課長","answer":"本日、創業・スタートアップ支援の施設ということで、各施設の特徴も含めて取組をやっておりますけれども、この施設の中での事業や、あるいは五反田バレーも含めた、あるいは品川区外の、例えば自治体との連携なども含めて、また、このような事業をより広げて、品川区の発信なり。","voiceIndex":104,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"もういろいろ質疑はあったので、私からお伺いしたいことは２つぐらい。モンゴル高専との交流事業なのですが、現在までに６社２０名が区内製造業へ就業ということで、今拝見をすると、うちの地元もそうなのですけれども、大体電気関係の仕事ですね。全然待遇が違うので、その辺り、この２０名の方というのはどのような在留資格で現在いらっしゃるのかというところを教えてください。","respondent":"小林商業・ものづくり課長","answer":"その話を聞いてきて日本に帰ってきて、インターンシップが始まるときに、すごくいい話だなと思ったのですが、北品川に宿を取って、それで実際にインターンシップに通うのですけれども、ちょうど電車が止まってしまったという日がありまして、そのときにきちんと電話をかけてきて。","voiceIndex":107,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"モンゴルは想像するだけでも遊牧の世界ですから、時間の感覚というものは多分相当。現代ですからそれほど違うことはないのかもしれませんけれども、有名なテレビドラマの舞台もモンゴルですから。そのような感覚からすると、今のお話を聞いて、そちらにも非常に力を入れている、そして日本から高専の先生も行かれているわけですから、多分その辺も力を入れて教えているのかなというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-041"},{"speaker":"山本委員","kind":"質問・要望","question":"区として、今の区の中小企業の人材不足の状況をどう捉えているかというところで、この５年で２０名というのは、これで十分かどうかというところで、多くの中の手段の一つとして取り組まれているところなのですが、これが、この数字に対してどのようにお考えかということと、企業から、これまでのこの取組を通じて。","respondent":"小林商業・ものづくり課長","answer":"今後の展望といったときに、実はこの資料にありますように、やはりこの事業だけで全てうまくいくわけではなくて、実際にやっていくに当たってはＤＸ化、例えばロボット化というところも含めた人の問題の解決もありますし、あるいは既にいる、社内での人材育成というか。","voiceIndex":111,"id":"exchange-042"},{"speaker":"山本委員","kind":"質問・要望","question":"これは要望になります。これも要望です。お聞きしたいところなのですけれども、ＳＨＩＰやほかのところも、それぞれ多くの入居者、利用者の方がいらっしゃる、そして年数も経ってきているというところで、これまで入居して使われてきた方々の成果です。例えば、売上げや規模、ここまで成長している企業がこれだけあるですとか、そのような形での成果、実績というものがあれば教えていただきたいと思います。","respondent":"小林商業・ものづくり課長","answer":"五反田バレーアクセラレーションプログラムができてからということでいくと、まだそれほど年数は経っていないのですけれども、その１期生の中には、先日雑誌を見ていましたら、『週刊東洋経済』という雑誌があるのですが、今。","voiceIndex":113,"id":"exchange-043"},{"speaker":"山本委員","kind":"質問・要望","question":"このＳＨＩＰなどはコワーキングスペースなので、１対１で個室に対して１企業の割当てではないということは理解しているのですが、先日議会報告会で利用させていただいたときにも、関係者の方にもお聞きしましたが、平日はもう結構にぎわっていて、場所がなかなかいっぱいの状況になりつつあるのですというようなことをお聞きしまして、それぞれの施設。","respondent":"小林商業・ものづくり課長","answer":"郵便が使えるのだったら入りますという形で、もう少し使いたいですという方がいるので、かなり稼働率が高い状況とは思っておりますけれども、もう少しＳＨＩＰのほうで受け入れることができるのかなと、そのように認識しています。","voiceIndex":115,"id":"exchange-044"},{"speaker":"山本委員","kind":"質問","question":"ＳＨＩＰは非常に高い稼働率というか、多くの企業にも利用されていて、人気も高いということで理解しました。ちなみに、それ以外の３つの施設はどうなのでしょうか。少し気になるので教えてください。","respondent":"小林商業・ものづくり課長","answer":"西大井創業支援センターが、会員という形で、同じようにコワーキングスペースを使えるようなものを会員と呼んでいるのですけれども、３０社程度入れるように、３０プラス（オフィススペースの）４ですので、この西大井創業支援センターも比較的稼働率は高い状況になっていまして。","voiceIndex":117,"id":"exchange-045"},{"speaker":"山本委員","kind":"質問・要望","question":"それぞれの施設がかなり満室に近い状況でご利用いただいているということで、また、その満室の中でも、多くの方に来ていただくような工夫をして進めていただいているということで理解しまして、そのように進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-046"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この人材確保のところで、モンゴル高専のほうは確保策の一つということでご紹介いただきました。冒頭でも、中小企業支援ということで、物価高騰等で大変だと、そして人材確保も苦慮しているということを説明いただいたと思うのですけれども、この今の中小企業が人材確保に苦慮している理由、原因というのを、区としてどのように考えているのか教えてください。","respondent":"小林商業・ものづくり課長","answer":"そのような意味で、我々として直接、なかなか給料の部分を区が助成するというわけにはいかないのですけれども、我々が実際融資あっ旋や助成金、あるいは本日ご説明したような取組でやっていることは、そういった中で少しでも余力を企業の中につけていただいて。","voiceIndex":121,"id":"exchange-047"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"消費税が１０％になった時点で仕入額が上がる、だけれども売るところで転嫁できない、そこにすごく苦労されている。中小企業を支援していく姿勢を持っているというところでは、中小企業独自での賃上げは難しいと、今もう業者から声が出ているので、そこへの国の支援、そしてそこに人材確保が進むということになっていくので、それはぜひ求めていっていただきたいなと思うのですけれどもいかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"そのようなものがソフト事業として継続しているところでございまして、そういう中で、単純に今仕事をすぐどうこうするということだけではなくて、自分が今後、例えばどのような仕事をしていきたいか、あるいは子育てを経てどのように仕事をしていきたいのかとか。","voiceIndex":123,"id":"exchange-048"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"中小企業は。ですから、本当にその支援を継続的に、区としても実施していく必要があるし、しっかりと、それをそのときだけの支援にせずに継続的にするためには、やはり国にしっかり物を言っていかなければいけないなと思いますので、ここはお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2980#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":61776,"voices":135}},{"id":"r06-20240122-7","meetingId":"r06-cm01","date":"2024年1月22日","dateIso":"2024-01-22","committee":"厚生委員会","time":"午後 １時００分～午後 ６時０８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を94件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"請願・陳情審査および報告事項","agenda":"請願・陳情審査および報告事項","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"私からは２点だけお伺いいたします。こちら、いただいた資料の６９ページに、障害者手帳保有者の推移が表で出ているのですが、近年、精神障害者の手帳を申請されている方が非常に増加しているのですが、こちらの精神障害者が増えている理由について、区のほうでは、情報や方策や展開といったものがもしあれば教えていただきたいと思います。続けてよろしいでしょうか。以上、２点です。","respondent":"榎本荏原保健センター所長、東野福祉計画課長","answer":"詳細な、明確な理由というのは、はっきりしているわけではないのですけれども、社会情勢の変化でありますとか、様々なことが起きている中で、お一人お一人が様々なストレスの中で。２点目の各所管での取組数に応じた人員配置等の見直しにつきまして、まず私のほうからお答えいたします。こちらに載せている事業につきましては、それぞれの施策に合わせた、所管別の取組の内容について網羅して載せているものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"精神障害の方が増えているという理由が、私も同じ考えで、社会情勢やストレスかなという部分なので、また、明確な情報等があれば考察等を共有していきたいと思います。新しく今回、包括ケアということで、やはりやってみて、意外なところにニーズがあったりとか、そういったものを柔軟に対応していっていただければと思います。非常に期待しておりますので、ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"ひがし委員","kind":"質問・要望","question":"確かにいろいろな計画が立っていて、その時期が重なってくると、どういうものなのだろうというところで難しいのかなと思うので、ぜひそのいろいろな計画があると思うのですけれど、その計画が何についての意見を求めているのかとか、その計画はどういうことをやっているのだというところを簡単にでもいいので、ぜひ区民の方に説明していただけると、パブリックコメントの内容というところも、もっと意見が。","respondent":"東野福祉計画課長","answer":"パブリックコメントの実施に当たりまして、現在のところ説明会については実施の予定はございません。","voiceIndex":10,"id":"exchange-003"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ、区のところと、説明会というのはご意見として何名かから聞くところであるので、ぜひ検討というところは進めていただければなと思います。要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今の説明会ですけれど、私も毎回求めていますが、説明会をぜひやっていただきたいということで、これは本当に検討していただきたいと思っています。それなので、この冊子だけだと、本当に私たちが読んでもよく分からない部分がすごくいっぱい出てくるのです。地域福祉計画で、他の区がやっているかどうかも分かったら教えていただきたいのですけれど、介護保険などもほかの区、説明会を毎回やっているのです。","respondent":"東野福祉計画課長","answer":"パブリックコメント全体の品川区の状況としては、説明会をほぼやっていないというような状況でございまして、これらを今後どうしていくかについては、十分検討する余地はあるかなと考えています。今回につきましては、特に説明会はする予定はございません。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"森澤区長も、情報公開と区民参加というのはうたわれていると思いますので、ぜひそういう点からも、説明会をやっていただきたいと思います。そういったことからもぜひご検討いただけたらと思うのですけれど、この、区民に知られていないという状況に対しては、区としてどう考えられているかも含めて伺えたらと思います。","respondent":"東野福祉計画課長","answer":"これらを説明会につなげていくという部分におきましては、どういう機会をもってということになるかなというふうには思いますけれども、区としてどういった形で区民の方へもっと周知をしていくかという部分については、所管としまして考えていきたいと考えています。","voiceIndex":16,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それと、今の概要の最後のページ、２０ページのところで、計画の進行管理というところで、この地域福祉計画についても、ＰＤＣＡサイクルマネジメントに沿ってということで、地域福祉計画推進委員会というのがつくられて、進捗状況の把握、評価を行いますということで書かれているのですけれど、これは今までも、第３期までもこういう推進委員会というのはあったのか、その点を伺いたいのと、それであれば。","respondent":"東野福祉計画課長","answer":"委員のほうから先ほどお話がありました、困ったときにどこに相談すればいいのかという部分につきましては、現在取り組んでいる重層的支援体制の強化の中で、一つの窓口に相談に行けば、次、いろいろな課題を踏まえて、次の相談窓口に結びつける。","voiceIndex":18,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、介護保険は介護保険で、運営状況という形で１年間のまとめをここで報告していただいているのですけれど、この地域福祉計画もそういうことで、毎年ＰＤＣＡでまとめられて、評価と課題ということが明確にされているということであれば、ぜひ１年ごとの評価の課題というところで、ここの厚生委員会にご報告いただけたら、また、私たちがこの地域福祉計画についての認識も高まるというか。","respondent":"東野福祉計画課長","answer":"令和６年度、来年度の検討期間を経まして、令和７年度本格実施に向けて、現在取り組んでいるところです。地域づくりなどにつきましても、現在、見える化できるようなシステムの構築ですとか、そういったものも含めて検討しています。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問","question":"具体的に、重層的支援体制というところで、例えば複合的な問題がある方の場合は、いろいろな部署が関わってケースカンファレンスをやって、具体化していくというのは、されていると伺ったのですけれど、そこら辺のところは、実際にどういう関係部署が集まって検討するという形でされているのか、そこら辺も具体的に今がどんな状況になっているのか、それはもしされているとしたら。","respondent":"東野福祉計画課長","answer":"こちらの厚生委員会のほうでも、所管事務調査の中で、その辺については一度ご説明させていただいておりまして、そういうときにお話、ご要望いただいたのが、定期的に集まったほうがいいのではないかというようなところ。","voiceIndex":22,"id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうしますと、それはまだ準備段階というところなので、まだ本格実施ということではなくて、２０２５年から本格実施になるということで考えていいのでしょうかということと、あと、私たちも相談を受けるところで、本当にすごく複合的な問題が絡んでいるなと、保健所にも関わってもらいたいし、高齢も関わってもらいたいし、医療も関わってもらいたいし、病気を抱え、ひきこもりを抱え、精神を抱え。","respondent":"東野福祉計画課長","answer":"地域包括支援につきましては、これまでも説明してまいりましたが、品川区としては、直営型、品川区の高齢者福祉課のところに統括をといった形で、在宅介護支援センターそれから支え愛・ほっとステーションなどとの連携の上で、地域の困りごとについて解決を図っている。","voiceIndex":24,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"後でまた、コロナの対策も出てきますけれど、保健所や保健センターの保健師も２３区で下から２番目という状況であるにもかかわらず、在宅支援センターに保健師がいないので、地域に地域包括支援センターがなくて、保健師がいないので、そういうふうなところでは、しっかりとその医療の専門というか、そこのところを３職種で検討できる、チームで対応できるというところでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"地域活動や参加を促進する取り組みということで、具体的に出ているわけなのですけれども、この中で、確認というかお考えをお聞きしたいのは、この３４ページの下のほうに計画期間中の目標ということで、例えば２つ目の矢印「身近な地域におけるゆるやかな見守り活動を支援します。この事業もやりますとうたっているわけなのですけれども、この辺はどういうふうに具体的にされようと、今お考えなのでしょうか。","respondent":"東野福祉計画課長","answer":"現在２４企業、参加いただいておりますので、そういった皆さんと、実は今年度中に皆さんが顔合わせをして、ふだんどういった活動しているかというようなものも行っていく予定で計画をしています。","voiceIndex":29,"id":"exchange-012"},{"speaker":"こんの委員","kind":"質問","question":"やはり、人のこの気づきと、その気づいた方が行政につながるツールとして、そこまで広げていかないと、なかなかこういう孤独・孤立という、また、複合的な課題を抱えていらっしゃる方の問題解決、まずはそこにつながらないと、という、その担い手は、そういったところまで広げる必要が今後あるのではないかなというふうに私は考えるところなのですけれども、いかがでしょうか。","respondent":"東野福祉計画課長","answer":"その辺を、町会・自治会、民生委員、支え愛・ほっとステーション、そういったところが皆さん連携をした形で、今後、地域へ広げていければ、少しでも顔見知った活動というのができるかなと考えています。","voiceIndex":31,"id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"次の質問なのですが、こうした取組を周知していくといったところで、ホームページ等で公表していくということなのですが、いろいろな多くの人に周知するためにはこうした手法が必要だと思うのですけれど、ホームページのつくり方というか、広報広聴課もこれ関わるのでしょうか、中身はもう所管が全部つくって、こういうのを掲載してくださいというふうにつくるのでしょうか。","respondent":"東野福祉計画課長","answer":"区としては、そういったところも含めて検討を進めてまいりたい。様々な場づくりというのをこれまでも区としては進めてきたところですが、地域がどう関わっていくかという部分を改めて、これからも検討していきたいと考えています。","voiceIndex":33,"id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"小地域ネットワーク化の記述を読みました。こうしたことで、今進めてくださっているという考えも伺いましたので、より実効性のあるというか、具体性のある、そうしたものに進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"２点ほど確認させていただきたいのですけれど、この第４期品川区地域福祉計画策定委員会が、今４回まで開催されたと思うのですけれど、品川区のホームページで３回までしか載っていないのですが、いつ頃この第４回の結果が公表されるのかということと、あと、パブリックコメントの実施についてなのですけれど、障害者団体の方からパブリックコメントの期間がいつも短いというふうに言われまして、今。","respondent":"東野福祉計画課長","answer":"特に短くしている、意図的に短くしているということではなく、掲載を３週間として、その後の取りまとめの時期につきましても、十分な期間を取っていきたいというふうに思っているところです。","voiceIndex":37,"id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。この地域福祉計画概要版の２０ページによりますと、地域福祉計画推進委員会で、毎年度、進捗状況の把握および評価を行いますということですけれど、これは、この把握、評価の結果というのは品川区のホームページなどで公表されるのかということの確認と、また、これをしたとして、区民からいろいろなご意見をいただく機会というのはあるのかということをお聞きします。","respondent":"東野福祉計画課長","answer":"区民からそれに対してのご意見を伺うような形ではなく、あくまでも推進委員会としまして区の状況を把握して、それを次年度につなげていくための委員会というふうな位置づけです。","voiceIndex":39,"id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"いろいろ、他の委員会もその担い手不足とかいろいろな課題が、この計画を立てて、それに基づくその事業がいろいろ行われると思うのですけれども、その中でいろいろな課題などが出てくると思いますので、そのときにこうした地域福祉計画推進委員会の進捗状況の把握および評価というのを、やはり区民の皆様に公表して、その課題解決のヒントというのも。","respondent":"東野福祉計画課長","answer":"ただ、推進委員会自体は公開をしているものですので、こちらについて傍聴などもできるような仕組みを取っているところです。こちらのまとめにつきましては、次期計画にどう反映させられるかという部分を含めて、毎年委員との意見交換を行っているものです。","voiceIndex":41,"id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。ぜひとも、いろいろな、適宜、課長、部長、いろいろな各種団体とか区民の方からのご意見を伺っていると思いますけれども、ぜひ、積極的にご意見を取り入れていただいて、地域福祉の状況をしっかりと諮っていただきたいと思います。これは要望で終わります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私からは素案の６８ページなのですけれども、要介護者定数推移なのですけれども、これは区としての受け止めをお伺いしたいのですけれども、認定者数は５年前の２０１８年と比べてほぼ横ばいという中で、要支援の方が増えていると。要介護者数が大体５５０人ぐらい増えていると。これについて、どういった理由といいますか、区として分析というか受け止めがあれば、お答えいただければと思います。","respondent":"菅野高齢者福祉課長","answer":"そういった事情もあるので、令和２年、令和３年、令和４年については、全体的に、新規の方ももちろんいらっしゃるのですけれども、介護認定の傾向としては自動更新の方が多くて、動きがなかったりとかするという実態がありますので、その部分をまず。","voiceIndex":45,"id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"意見","question":"そのコロナの特例は２０２０年から始まったということだと思うのですけれど、その中でも結構変動があると思うのです。要支援２の方が結構増えていたり、逆に要介護１の方が減っていたり、ここら辺の数字の変化については、何か受け止めがあればお願いしたいのですけれども。","respondent":"菅野高齢者福祉課長","answer":"個別に、例えば、病気で一回救急搬送されて、そのときには要介護４だった方が、自動更新でずっとやっていて、実際はもう今、要支援２ぐらいに回復しているのかなという方とか、反対もあると思うのですけれども、実際に重いけれども自動更新だったので、というところで。","voiceIndex":47,"id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"確認","question":"お話あった、予防の、品川区の取組の成果もあるのではないかというようなことで、それが一番、そうなっているのが一番いいことだなというふうに当然私も思っておりまして、つまり、次の２０２３年の調査で、自動延長がなくなった状態での、ある意味、よりリアルな数字というのが上がってくるというような解釈でよろしいでしょうか。確認です。","respondent":"菅野高齢者福祉課長","answer":"今年度が２０２３年度なので、自動延長がなくなるのが来年度、２０２４年度ということになるので、その結果が自動延長なく、調査を全てするということになりますので、大分変わってくるのかなというふうに捉えております。","voiceIndex":49,"id":"exchange-022"},{"speaker":"やなぎさわ委員","kind":"質問","question":"かしこまりました。ちなみに、今後の区としての予測というか、この介護者、認定者数もそうですし、要支援、要介護の割合とかというのは、どのような推移をたどるというような予測をされているのか、もし数字があれば教えてください。","respondent":"菅野高齢者福祉課長","answer":"その先の１０年後にはその方たちが８５歳以上になるというところで、その方たちの部分が８５歳以上になる２０４０年ぐらいに向けて、介護保険事業計画というのは、国も大体進めている次第なのですけれども、やはり介護認定の傾向として、８５歳以上の方が。","voiceIndex":51,"id":"exchange-023"},{"speaker":"やなぎさわ委員","kind":"意見","question":"現場のケアマネージャーとかも、「品川区は予防に力を入れているのよ」ということを周りの高齢者の方に自信を持っておっしゃられているので、ぜひ、介護費用の抑制という意味でも、要介護をなるべくだんだん要支援に、要支援の方を自立になるような、ということをぜひ一緒に続けていければと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"最後もう１点、この議事録の中でも、介護職員の人材確保・育成というのが、これからもすごく大変というような中で、ここのところは大きな課題ということが意見としても出されていたのですけれども、それは本当に介護にしても障害者にしても、社会的なというか政治の大きな課題になっていると思うのですが、そういうところではこの地域福祉計画の中では、介護人材の確保、育成、そこのところは。","respondent":"東野福祉計画課長","answer":"先ほど来話をしている、地域の皆さんが集まれる場については、様々な施策の中で取り組んできているところですが、どういった形が福祉的な分野として取り組んでいけるのかについては、十分な検討を重ねてまいりたいと考えています。","voiceIndex":57,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"やはり、平均の全産業の収入よりも平均で１か月７万円少ないというような状況なので、これはぜひ国のほうにも声を届けていただいて、人材がしっかりと確保できるための国の処遇改善というふうなところで求めていただきたいということで要望しておきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"すみません。大変に細かいことで恐縮なのですが、文言の表現の仕方で、本編の２１ページの重層的支援体制整備事業、最後の行です。３段落目の最後の行の、品川区においても、２０２５年から重層事業の本格実施に向けて準備を開始していますという文言になっている。ただ、６年間の計画なので、いつ実施をしたかということが最後分かる文言のほうがいいのかなと思うところなのですが、いかがでしょうか。","respondent":"東野福祉計画課長","answer":"ご意見いただきましてありがとうあります。ここにつきましては訂正させていただきたいと思います。","voiceIndex":61,"id":"exchange-027"}]},{"id":"topic-02","title":"障害者相談支援事業等に係る消費税の取扱い","agenda":"障害者相談支援事業等に係る消費税の取扱い","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"平成２４年の改正のときに、そういうふうに消費税がかかるということになったということなのでしょうか。それは、これまではかからなかったのに、何でこの相談支援のところだけ消費税がかかるということになってしまったのでしょうかということを教えていただきたいのです。","respondent":"松山障害者支援課長","answer":"平成２４年度の自立支援法の改正の内容についてです。平成２４年度に相談支援体制が見直されまして、計画相談がそこから開始されることになりました。","voiceIndex":68,"id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問","question":"区の委託なので、消費税分として委託費を出すということで、他の指定特定相談支援事業所は、区が委託していないところというのもいっぱいあると思うのですけれど、そこのところはもう既に消費税は払っていて、区だけが漏れてしまったということなのか、それともその平成２４年にこういう改正になったのであれば、本来であればそういう通知というのは、その時点で来てしかるべきなのかなと思うのですが。","respondent":"松山障害者支援課長","answer":"相談事業の中でも、課税のものと非課税のものがあるです。非課税なものは幾つかあるのです、計画相談の事業所が複数ありますけれども、そちらのほうは特定相談支援事業に当たるので、非課税だということです。","voiceIndex":70,"id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問","question":"そうなのですか。非課税でもいいような気がするのですけれど、そうなのですね。分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほど、鈴木委員の質疑の中で、遡れるのが５年までだということは承知したのですけれども、とはいえというか、この対象事業者の方たちと、要は、ある意味、時効というわけではない……、時効のような扱いなのかなと思うのですけれど、「いやいや、とはいえそんな、取扱いを間違えていたのだから遡って払ってください」、みたいなことというのは特に話合いしたりとか言われたりはしていないのですか。","respondent":"松山障害者支援課長","answer":"事業者についても時効となっておりまして、区が委託している事業者につきましては、現在、丁寧に話合いを進めておりますので、事業者については、金額的な負担というよりは修正申告を税務署にしていただくというところをお願いしている次第です。","voiceIndex":76,"id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"質問","question":"つまり、この対象事業者３社に関しては一応事情を説明して、これは時効なのでお支払いできませんというような……、あと、ここの部分は課税分というかその消費税分の支払いができないというようなことは、話合いは進めていて、ある程度理解をされているというような状況でよろしいでしょうか。","respondent":"松山障害者支援課長","answer":"少し説明不足でしたけれども、５年より以前のものにつきましては、消費税を支払う必要がないということで税務署と確認しておりまして、事業者にもその旨、きちんと丁寧に伝えておりますので。","voiceIndex":78,"id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほどの鈴木委員の質問の補足ですけれど、これはでは、全国的に一斉にこのような事案は、品川区だけとかではなくて起きているというような解釈でよろしいですか。","respondent":"松山障害者支援課長","answer":"そのような形で全国的にも複数の自治体が該当しておりまして、同様に、速やかに対応をしています。","voiceIndex":80,"id":"exchange-033"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"相談内容によって課税、非課税があるとは非常に分かりにくいなと思うので、これは別に国のことではあるのですけれども、区として要望を上げていただけたらな、などというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-034"}]},{"id":"topic-03","title":"品川区立杜松特別養護老人ホームおよび品川区立杜松地域密着型多機能ホーム指定管理者候補者の公募","agenda":"品川区立杜松特別養護老人ホームおよび品川区立杜松地域密着型多機能ホーム指定管理者候補者の公募","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"今回、１０年、若竹大寿会でやっていただいていたと思うのですけれど、１０年間ずっと指定管理で、この地域に密着しながらやっていただいたと思うのですが、今回、指定期間満了をもって指定管理者を継続しない旨、若竹大寿会のほうから申出があったということですよね。この理由は何なのかというのをまず、お聞かせいただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"若竹大寿会のほうの、本来であればもう一度非公募でというところなのですが、その手挙げをしない予定ということの理由としましては、こちらの若竹大寿会は、横浜市の中心に事業を展開している法人となっております。","voiceIndex":87,"id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問","question":"そんな中で、これまで赤字ということで、ここの経営そのものが成り立たないというふうな状況になってしまったということだと思うのですけれど、そういうところで言えば、これ指定管理者なので、区のほうからもっと支援をして、赤字を支援するという対応というのはできなかったのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"こちらの施設につきましては、この利用料金制だけではなくて、地域交流の受付などもしていただいておりますので、そちらの委託料や、あとは大規模施設というところの維持管理経費や、あとは看護小規模多機能については、生活相談支援業務といった名目の下。","voiceIndex":89,"id":"exchange-036"},{"speaker":"鈴木委員","kind":"質問","question":"特別養護老人ホームはここだけだと思うのです。そこに対して、区としては、その支援を今までの若竹大寿会以上に、例えば指定管理料を上げていくとか、そういう対策を取っていくのか、辞退というふうなことになってしまったから公募するしかないと思うのですけれど、公募をして応募があるような、そういう対応はどういうふうに区としては取ることを考えられているのか、その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"具体的には、現事業者が継続しない理由というところで先ほども申し上げましたが、そういった部分を参考に、公募の際には経費や業務内容等などの提案もしてもらうなど、今後この施設が安定して持続可能な介護サービスを提供していけるよう検証しながら。","voiceIndex":91,"id":"exchange-037"},{"speaker":"鈴木委員","kind":"質問・要望","question":"若竹大寿会ができなかったことが、では他のところで効率的で質の高いというのがどうしてできるのかというのはよく分からないのです。小規模だということと、今こういう形で介護の人材が本当に大変な状況で、募集しても募集しても確保することができないというのが、もう全国的な問題になっているわけではないですか。そこのところは、国にぜひそれを求めていただきたいと思うのですけれど、その点が１点。","respondent":"菅野高齢者福祉課長","answer":"国のほうの審議会は、結論というか途中経過なので、最終的にはどうなるかというところも、もう少し確認をしたいというところと、あとは区としてもというところなのですけれども、ここの介護報酬の部分につきましては。","voiceIndex":93,"id":"exchange-038"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう本当に発想の転換が必要だと私は思いまして、社会保障にしっかりとお金をかけて、そしてその人材も、仕事を続けていけるような、そういう形にすることが、このＧＤＰが、経済成長が止まった国から脱するというところからも、ぜひ必要なのではないかなと、そういう発想の転換にもしていくというところでも、区としても考え方を、この社会保障、福祉のところにしっかりと一般財源も入れながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-039"},{"speaker":"ひがし委員","kind":"意見","question":"今度公募する指定期間が令和６年１２月１日からの５年間というふうになっているのですけれど、今、お話を聞いていて少し心配だなと思ったのが、公募を２月、３月から説明会などを開始して募集すると思うのですが、１年ない期間の中で、万が一、手を挙げる人がいなかった場合の対応はどうなるのかなというふうに思っていて、継続しないと言っている方に、その見つかるまでの期間をお願いするのか。","respondent":"菅野高齢者福祉課長","answer":"そういった意味で、費用や業務内容等も提案してもらいながらというところで、新しい事業者がどういった形でこの施設を引き受けてくれるのかというところを検討しながら、選定作業も進めていきたいと考えています。","voiceIndex":97,"id":"exchange-040"},{"speaker":"ひがし委員","kind":"意見","question":"今、通われている方とかいらっしゃる方々が不安にならないかなというところが一番心配だったので、継続していけるということで安心をいたしました。利用者さん方を大事に考えて、指定管理者の選定と、もし、今回手を上げないといっても金額が変わればという話もあるかと思いますので、その点についてはしっかりと相談をしながら進めていっていただければなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-041"},{"speaker":"やなぎさわ委員","kind":"質問","question":"もう半年とか迫ってしまっていたら、もう向こうもそういう職員整理とかしてしまっていますとなるかもしれないですけれど、まだ今のうち、ある意味内在の段階に近いと思うので、今からお話をして、どういうふうにしていけば、では計画可能なのかということを建設的な議論をぜひ、していけたらなと思うのですけれども、その辺は何かお話をしているとか、そういった取組みたいなご予定はありますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"ただ、何回も申し上げますが、きちんと引継ぎはしたいということと、サービスの提供が滞ることがないようにという部分につきましては、協力を得てくれるというふうにはお話をもらっておりますので、その辺りのところ、若竹大寿会のほうには、人材。","voiceIndex":101,"id":"exchange-042"},{"speaker":"やなぎさわ委員","kind":"意見","question":"人材確保の困難さと経営赤字というようなところが大きな理由だというふうには承知していまして、介護保険の報酬１.５９％という話もあるのですけれど、赤字に関して言えば、当然、次の指定のときにはもう、介護報酬改定された段階での試算だと思うので、それを加味しても経営難しいのだという判断をされたのだと思うのです。何か受け止めがあればお願いいたします。","respondent":"菅野高齢者福祉課長","answer":"国のほうで、令和５年度の介護事業経営実態調査の結果の報告というところで、ホームページのほうにも載っているのですけれども、各サービス事業における収支差率というところで、令和３年度と比較して令和４年度がマイナスになっているところ、例えば今回の。","voiceIndex":103,"id":"exchange-043"},{"speaker":"こんの委員","kind":"提案","question":"今回、大変に残念なことですけれども、とにかく利用者のためには、この今の事業が継続できるように、前向きに進めていただきたいなというところですけれども、そうなると、次の公募される事業者が、この今ある指定管理者が行う業務全てを請負ってくださるところが本当望ましいのですが、なかなかそれが難しい、だけどこういう提案をしますよ、こういう事業をしますよといった場合に。","respondent":"菅野高齢者福祉課長","answer":"業務の内容ということなのですけれども、こちら今回、３のところで指定管理者が行う業務というところで、現在の業務を出させてはいただいております。","voiceIndex":107,"id":"exchange-044"},{"speaker":"こんの委員","kind":"提案","question":"ご提案をいただいたその事業によっては、今の施設のありよう、いわゆるレイアウト、こうしたものも変更をしていかなければいけない場合も出てくるかなと想像するのですけれども、そうしたものについては、事業者がやるのですか、それとも区として、そこを整備してさしあげて、事業を展開していただくというふうになるのですか。その辺もお考えをお聞きしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"こちらの施設については、指定管理施設ということで区の施設でありますので、事業者から提案していただいた内容を参考に、区が用途変更というか、内容を改修するなどして、新しいサービスを提供する場合にはそのような、区が責任を持って。","voiceIndex":109,"id":"exchange-045"},{"speaker":"こんの委員","kind":"提案","question":"この若竹大寿会がやってくださった事業をさらにアップされるような事業者にぜひお願いをしたいというところですが、なかなか難しいところではあるのですけれども、ご提案くださるその事業で、より、今ある事業をできれば継続できる、プラスアルファというようなところで、その事業者が事業展開しやすい施設のありようとか、また、契約だとかといったところを最大限に見ていただいて、事業が展開できるように。","respondent":"菅野高齢者福祉課長","answer":"今後も、この施設が地域にしっかりと根差して地域住民の方のニーズを吸い上げられるような提案がなされることを、私たちとしても何とか導き出したいなと考えていますし、そういう事業者が現れた際には、一緒になって。","voiceIndex":111,"id":"exchange-046"},{"speaker":"こしば副委員長","kind":"質問","question":"前提としてお聞きしたいのですけれども、サービスの利用者の方々には、この状況というのはお伝えされているのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"こちら、１２月に事業者のほうから継続しないというようなお話をいただいた次第です。","voiceIndex":115,"id":"exchange-047"},{"speaker":"こしば副委員長","kind":"質問・要望","question":"この１２月に指定管理業務開始になっておりますけれども、継続的なこの安定といったものを担保できるように、ぜひ取り組んでいただきたいと思いますし、また、利用者の方々にもその辺はお伝えしていただきたいと思いますので、まず、そのお考えありましたら教えてください。","respondent":"菅野高齢者福祉課長","answer":"現事業者ともお話はしていますが、新たな事業者が選定されたときには、引継ぎを十分に行って、利用者様やその家族が安心してもらえる施設運営に努めていきたいと考えています。","voiceIndex":117,"id":"exchange-048"}]},{"id":"topic-04","title":"新型コロナウイルス感染症対策の検証と健康危機管理体制の基盤整備検討報告書","agenda":"新型コロナウイルス感染症対策の検証と健康危機管理体制の基盤整備検討報告書","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"こうした過去の検証とこれからの対策について検討されるということは非常に重要かなと考えているのですけれど、これ、ちなみにこのこうした検証と報告書を出すというのは、区独自の判断でこれをやろうとしたのか、それとも何か国の指導とかあって、こうしたことをやろうということになったのか、その点お聞かせください。","respondent":"坂野保健予防課長、舩木生活衛生課長","answer":"国とか都からやりなさいみたいな指示は出ていません。実はこの検証報告をまとめるに当たりましては、保健所の庶務担課である生活衛生課のほうでも中心になって動いておりましたので、若干補足的な説明をしますと、今、筒井委員のご質問におきましては、昨年度。","voiceIndex":124,"id":"exchange-049"},{"speaker":"筒井委員","kind":"質問","question":"すばらしい判断かと思います。ちなみになのですけれど、他の区とかでもこうしたことをやっているとかという情報というのは何か、状況把握されていますでしょうか。","respondent":"坂野保健予防課長、秋山保健整備担当部長","answer":"全ての、東京ですと世田谷区がまとめている部分があるのですけれど、ただ、もうちょっとシンプルな感じかと。都外ですと神戸市とか大阪府とかが似たような感じでまとめているかなと思います。ここまで体系的にしっかりまとめているところはないと思います。","voiceIndex":127,"id":"exchange-050"},{"speaker":"ひがし委員","kind":"質問・要望","question":"この報告で、すごく区として取り組んでくださっていて、いいなと思うのですけれど、逆にこんなにしっかりとまとめてくださったのだからしっかりと活用していただきたいなと思うのですが、具体的に各種計画に整合性が取れるように盛り込んでいくという言葉があったのですが、具体的にどういうふうに進めていくのかなという。","respondent":"舩木生活衛生課長","answer":"１点目のご質問につきましては、来年度から事務局体制を構築した上でという説明いたしましたけれども、実際には第４回定例議会で原案可決いただいていますような組織改正というところで、実は地域医療連携課というのを健康推進部内に設けまして、しっかりこの辺り平時の対応。","voiceIndex":131,"id":"exchange-051"},{"speaker":"ひがし委員","kind":"確認","question":"本当に内容を見ていても、時系列で書かれているところとかもすごくまとめるの大変だったのではないかなというふうに思うのですけれど、こうやって先行事例としてしっかりと資料でまとめていただいて、さらにやはり、組織支援体制というところで新たな取組、体制をつくるというところまで取り組んでいただけているということが確認できたので、安心をしております。","respondent":"舩木生活衛生課長","answer":"１点だけすみません、答弁漏れございましたけれども、具体的な計画にどのように結びつけていくかということに関しましては、既に２００９年の新型インフルエンザのときに、新型インフルエンザ等対策行動計画というものをつくっておりまして。","voiceIndex":133,"id":"exchange-052"},{"speaker":"ひがし委員","kind":"質問・要望","question":"は区民の方へ広め方というところも今後検討していくとは思うのですが、この紙をどさっと見せられても、なかなか読んでいくのが大変かなと思ったりすると、分かりやすくまとめられていたりとか、一般の方々が読んでも分かるような内容というところにまとめるということも大切なのかなというふうに思いますので、その点については、要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私も、コロナの感染が始まったときとか、ずっと厚生委員会で所属しておりましたので、本当に区の職員の皆さんが大変な実態というのは、ご報告もいただきながら、職員からもお話も伺いながら、特に保健予防課長とか、本当に大丈夫かしらと思うぐらい心配するような状況でしたし、保健師たちも本当にもう毎日毎日、もう深夜遅くまでお仕事されていて、議会の中でも質問したときに。","respondent":"舩木生活衛生課長","answer":"検討委員会の委員の構成につきましては、区の理事者と、あと、両医師会のほうに推薦という形でいただきまして、これは町なかの診療所の先生方なのか、それとも病院のいわゆる先生方なのかというところ、なかなか区のほうでも指定ということではなく。","voiceIndex":137,"id":"exchange-054"},{"speaker":"鈴木委員","kind":"質問","question":"それと、続けて伺いますけれど、ワクチンのところは資料編のところに、いつ、どういう方が何人ワクチンを受けられたというのがすごい細かく書かれていて、こんな形なのだなというのがすごくよく、年の刻みも含めて書かれているのですけれど、感染者の状況というのが、本編の６ページのところにグラフで、品川区の新規感染者の推移というところで書かれているのですが、これはもうちょっと分かりやすく、１波。","respondent":"秋山保健整備担当部長","answer":"第三者委員会ですけれども、３名ほどおられて、一人は、これは東京都ないしは自治体で感染症の対応をされた医師の方、それからもう１人は東京都のＯＢで、東京都の福祉保健局の部長をされて退職をされた方、それからもう１人は。","voiceIndex":139,"id":"exchange-055"},{"speaker":"鈴木委員","kind":"質問","question":"それからあと、これは棒グラフでは出していただいているのですけれど、結局これを全部足した数が感染者ということで考えていいのか。そこら辺のところも、その感染者が何人というところも、多分このグラフだけだと思うのですけれど、そこのところも、これを自分で計算しないといけないのかなという感じなので、そこら辺も見えるような形にならないかなと思ったのですが、その点についてはどうでしょうか。","respondent":"坂野保健予防課長、阿部品川区保健所長","answer":"患者数の６ページのグラフです。結局、２回感染した方がいるので、２回目なのか１回目なのかのカウントが出ない。特にオミクロンのときとか２回目の方がすごく多かった印象があります。というようなことがありますので、区民の方の正確な感染者数というのは、当時も実は把握できていない、ただ、医療のニーズにはきちんとお応えするという形でやってまいりましたので、その辺は確定しないということ。","voiceIndex":141,"id":"exchange-056"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それと、何度もここでも申し上げているのですけれど、やはり保健師の数が品川区は２３区の中でも本当に少ないので、そこのところは、今回のコロナを通して、保健師は確保していきたいとずっと答弁され続けているのですが、なかなかそれが改善されていかないので、ここの中にも、ぜひその保健師の増員というところもぜひ入れていただきたいなと思っているのですけれど、その点はいかがでしょうか。","respondent":"阿部品川区保健所長","answer":"もちろん、本来といいますか専門性が高い業務以外のところをなるべく事務に振り分けるというようなことも、今回の組織改正を踏まえた対策については検討してまいります。","voiceIndex":144,"id":"exchange-057"},{"speaker":"こんの委員","kind":"質問・要望","question":"今申し上げたところからいきますと、そうすると、この報告書を見させていただいて本当にそうだなと思ったのが、各部署から応援態勢の職員の方が来てくださって、やってくださるのですが、その、今日はどういう業務をしていただくのかというこの引継ぎとか、その時々の対応していただきたい業務が、細かく説明がなし得なくて、なかなか業務にスムーズに行くことができなかったという、こうしたこともあって。","respondent":"舩木生活衛生課長","answer":"今の委員のご質問ですけれども、まさにそういった部分もしっかりとマニュアル、計画もそうですけれども、今回のいろいろな対応を踏まえて、組み入れるものは組み込んでいくというところも考えておりますし。","voiceIndex":147,"id":"exchange-058"},{"speaker":"こんの委員","kind":"質問","question":"先ほども少しご説明あったのですけれども、そうすると、これは新たな計画を立てるということなのでしょうか。新型インフルエンザ等対策行動計画というのも、先ほど整合性を持たせながらといった、それはそれで、今回の検証により健康危機対処計画というものになるという理解でいいでしょうか。その点お聞きします。","respondent":"坂野保健予防課長","answer":"感染症法が令和４年の４月に改正されたのです。その中で、各保健所ベースで健康危機対処計画を策定せよということが、正確には感染症法の改正に伴う地域保健法の改正ではあるのですけれども、というのがあります。それで今、各自治体動き出しているという状況です。","voiceIndex":149,"id":"exchange-059"},{"speaker":"こんの委員","kind":"質問・要望","question":"その中でそうすると、細かいことなのですが、第２部のワクチン接種編のほうなのですけれども、例えば５２ページのところで、予防接種の予約申請、これについてのサポートをしてくださった、時系列的に庁内応援体制というのが出ておりますけれども、本当にここも緊急要望を上げてすぐに対応してくださって、３階のプラッツァのところでテントを張って。","respondent":"濱中新型コロナウイルス予防接種担当課長、秋山保健整備担当部長","answer":"ＤＸ化も、接種券ですとか予約ですとか、そういったものについても区電子申請システムを中心に進めていきますが、それだけではなくて、なかなかこのシステムに対応が難しい方、いらっしゃいますので、そういった方にも配慮した体制を。ご質問１点目の、対処計画にワクチンのという話なのですけれども、健康危機管理対処計画にはワクチンの中身は入ってございませんので、それは盛り込むということはありません。","voiceIndex":151,"id":"exchange-060"},{"speaker":"こんの委員","kind":"質問・要望","question":"もしワクチンという対応でしたらば、この今回のことを踏まえた対応になってくるかと思いますが、おっしゃるとおりなので、ここの計画というところは、今回の、あったらいいなという部分と今おっしゃってくださいましたが、まさにそういったところも少し盛り込んでおいていただいて、今後の、起きてほしくないですけれども起きてしまった感染症への対応がワクチンだった場合は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それで、この資料編のところの関係機関へのアンケートのところにいろいろ目を通してみたのですけれども、介護事業所、障害者事業所というか、結構やはり、当然保健所を含めた区役所も相当大変だったと思うのですけれども、やはり事業所も大分、私もデイサービスの管理者を当時もしていましたので、経験というか記憶があるのですけれども、それで要望に近いかもしれないのですけれども。","respondent":"菅野高齢者福祉課長","answer":"区としては、少しでも介護サービス継続できるようにというところで、例えば令和２年度においては、介護サービスの事業者がサービスを続けているという中で事業継続支援金をお渡ししたりとか、あとはＰＣＲ検査や抗原検査キットなども。","voiceIndex":156,"id":"exchange-062"},{"speaker":"やなぎさわ委員","kind":"確認","question":"これは少し確認なのですけれども、令和３年、２０２１年の夏、第５波のときに、私の管理者をしている事業所で職員がコロナになったということで、濃厚接触に疑われるような職員とか利用者の方を、事業所、デイサービス１か所に集めてＰＣＲ検査を実施したのですけれども、そういったことというのは、この第５波のとき含めて、継続的に今でもやられているような、区の対応なのか。","respondent":"菅野高齢者福祉課長","answer":"委員のお話のあった、ＰＣＲ検査を１か所にというところの部分については、記憶がないのであれなのですけれども、対応は何らかの形でいろいろと、波もいろいろあったので、どこかでそういう対応は取られたのかなと思うのですが、その辺りまた、すみません。","voiceIndex":159,"id":"exchange-063"},{"speaker":"やなぎさわ委員","kind":"意見","question":"恐らく保健所の方も非常に多忙で、そうせざるを得なかったのかなと思っていたのですけれど、それが継続されているのかどうか、結構これぐらいのスペースで、３０人ぐらい椅子並べてやっていたので、そういう感じのものが今もあるのかなというふうに思ったので、私の記憶違いかな、すみません。もし何かあれば。","respondent":"阿部品川区保健所長、舩木生活衛生課長","answer":"すみません、当時その現場に従事していたものが、今、厚生委員会に出席している理事者の中にはおりませんので、その今、委員のご指摘の検査そのものについてはちょっと確認が難しいのですけれども、時期と状況を考えますと。区としては、そういう対応を取っております。","voiceIndex":161,"id":"exchange-064"},{"speaker":"やなぎさわ委員","kind":"意見","question":"分かりました。それが悪いとかではなくて、それぐらいやはり保健所も大変だったのかということで、やはり人員を確保する必要性があるのだなというふうに感じたというところですので、かしこまりました。資料編の８８ページのアンケートのところに、これは感想だけですけれど、アンケートの中で「区議が色々な事業を手柄にしようと茶々入れてきたのを抑えてほしかった。感想で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":164,"id":"exchange-065"},{"speaker":"おぎの委員","kind":"質問・要望","question":"最後に１つだけ、今回災害のような、急に起こった大混乱の事態で、災害みたいなものだなと思いますが、昨今地震等も起きていますので、アルコールや衛生用品の備蓄に関しては今、区のほうではどれぐらい持たれているのでしょうか。","respondent":"舩木生活衛生課長","answer":"区の備蓄品につきましては、この間ずっとコロナ感染対策本部というのを立ち上げて、主に総務課のほうが備蓄含めてやってきましたので、私どものほうに、現存している備蓄がどれほどのものかというのはデータがないので、答弁ができない状況なのですけれども。","voiceIndex":166,"id":"exchange-066"}]},{"id":"topic-05","title":"令和５年陳情第５１号、心身障害者福祉会館の不適合箇所の早急な是正を求める陳情","agenda":"令和５年陳情第５１号、心身障害者福祉会館の不適合箇所の早急な是正を求める陳情","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"こちらの陳情を拝見しますと、大きく２つの要望があるなと思いまして、指摘している不適合箇所の早急な是正を求めるという部分と、前回の陳情に対して、用地取得ということが整備を遅らせる原因だということの理由を説明してくださいという２点だと思うのですが、まず、最初の部分の、不適格箇所を幾つかこの中、指摘で挙がっておりますが。","respondent":"小林施設整備課長","answer":"所管のほうと調整しておりまして、今回、指摘上がっている中では、ガラスの改修工事、これにつきましては、今年度中に行う予定での計画を進めております。","voiceIndex":173,"id":"exchange-067"},{"speaker":"おぎの委員","kind":"質問","question":"できることからということですので、進めていっていただければとは思いますが、今回、能登半島の地震を見ましても、急に災害は起こるものですので、地震等の面で、今の状態で完全に避難ができる状態ではあるのでしょうか。","respondent":"松山障害者支援課長","answer":"本施設のＩｓ値は０.９７というところで、そちらが最も値の小さかった階での数値となっておりますので、耐震化というのは今回の指摘事項には上がってきておりません。","voiceIndex":175,"id":"exchange-068"},{"speaker":"おぎの委員","kind":"質問","question":"それとも、品川区としても全く同じ見解ということでしょうか。","respondent":"松山障害者支援課長","answer":"仮移転先の用地についてのお尋ねです。用地取得以外にも、既存の用地を活用するなど用地の確保の手法は、ほかにもあります。手法が用地の取得に限定されるものではないということで、区としては受け止めております。","voiceIndex":177,"id":"exchange-069"},{"speaker":"おぎの委員","kind":"質問","question":"そうしますと、用地確保と用地取得と、別のものであって、こちらは用地取得と書いてあるから逆に限定しているということなのでしょうか。","respondent":"松山障害者支援課長","answer":"区といたしましては、そのようにおっしゃられたように受け止めております。必ずしも手法が取得だけに限定されるものではないということで受け止めております。","voiceIndex":179,"id":"exchange-070"},{"speaker":"鈴木委員","kind":"質問","question":"この陳情者から資料も提供されているのですけれど、この資料では、要是正という箇所が結構何か所もありまして、屋上部分の劣化および損傷の状況、防水押さえモルタルの位置に劣化が見られるですとか、パラペットの立ち上がり面の劣化および損傷の状況で、１階機械室、電気室の屋上の防水パラペット立ち上がり面のモルタルにひび割れが見られるですとか、そういうのがいろいろとその後も幾つも、１、２。","respondent":"小林施設整備課長、松山障害者支援課長","answer":"２つの質問のうちの、前段のひび割れについては私のほうからご説明いたします。ひび割れにつきましては、いろいろな種類のひび割れがございまして、建物の構造的に課題があるひび割れがある場合とか、様々あります。後段の部分についてのご質問にお答えいたします。結論を先に申し上げますと、まだ検討中ですので、特に何か具体的なものというのはございません。","voiceIndex":183,"id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ここの施設は、老朽化していて建て替えるというふうな方向というのは区としても出されているということなので、それはぜひもっと積極的に前に進めていただきたいということでお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-072"},{"speaker":"ひがし委員","kind":"質問・要望","question":"すごく大切なのでここ確認させていただきたいのですけれど、今回こうやって出てきている、不適合箇所を是正してくださいということに対して、こうやって定期点検で、既存不適格ではありますが、できれば変えておいたほうがいいよというふうに結果として出ているというところで、その必要な箇所、さっきのひび割れとかはまだ大丈夫だからというようなお話あったのですけれど、必要な箇所については。","respondent":"松山障害者支援課長、小林施設整備課長","answer":"最初の前段のところは、既存不適合箇所の項目については、区としても課題として認識しておりますので、できるところから改善を進めるという方針は変わりませんので、修繕はしてまいります。そういった観点で申し上げますと、いわゆる運営に関して支障がない範囲でまずはできることという考えで申し上げますと、今回、資料として添付いただきました中には、２ページ目の部分、調査結果表という。","voiceIndex":188,"id":"exchange-073"},{"speaker":"ひがし委員","kind":"質問","question":"今２点、区画不成立のところと遮煙性能のところ聞かせていただきましたが、逆に出てこなかった、この戸開走行保護装置のところについては、現状だと難しいという判断なのでしょうか。","respondent":"小林施設整備課長","answer":"先ほど申し上げましたとおり、全ての既存の不適格を解消するためには全てのエレベーターを新しいものに交換しなければなりません。この部分につきましては、今回の来年度、今予定している工事の中では対応が難しいというふうに考えてあります。","voiceIndex":191,"id":"exchange-074"},{"speaker":"ひがし委員","kind":"質問","question":"ただ、やはり耐震のところはいけるけれど、震災について十分ではないのかなというところも見受けられるので、改築というところに、改築をするときには絶対に新しくしっかりしたものにしてくださると思うのですけれども、改築までに時間がかかるのかなというふうに思っているので、どのぐらいの期間がもしエレベーター全部替えるとなるとかかるのかとか、予算のところについても。","respondent":"小林施設整備課長","answer":"金額につきましては、これらエレベーターにつきましてはオーダーメイド的なところもありますので、一概には幾らということはすぐに即答することはできません。","voiceIndex":193,"id":"exchange-075"},{"speaker":"ひがし委員","kind":"質問・要望","question":"改築に向けて何年ぐらいかかるのかというところと、工事するのにやはり止めるとなると利用者のことも考えなければいけないのかなというのはすごくよく分かるのですが、震災が起きたときに戸が開いたままで事故などが起きているというニュースなどを見てみると、何かしら計画を進めていっていただきたいなというふうに思いますので、その点については要望とします。何かありましたら。","respondent":"松山障害者支援課長","answer":"震災のときの避難経路なのですけれども、エレベーターというのはあまり想定がなくて、２階からちょうど階段の裏に配管の横を通っての横のスロープがありますので、そちらを使って外に避難するという形を今、想定しております。","voiceIndex":195,"id":"exchange-076"},{"speaker":"ひがし委員","kind":"意見","question":"もちろん、災害のときにエレベーターを使うというのは、看護師として医療の現場で働いている身としては、そこは使わないのでそこは理解しているのですけれど、乗っている間に起きるかもしれないので、そのときにというところで多分、法令が変わったのではないかなというふうに私も期待しているので、そこについての対応というところで考えていただければいいかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":197,"id":"exchange-077"},{"speaker":"筒井委員","kind":"確認","question":"確認で、先ほどご答弁あったかもしれないのですけれど、耐震性自体は問題ないということでよろしいでしょうか。","respondent":"小林施設整備課長","answer":"先ほど所管課長からお話がありました、建物の耐震性でございまして、当然ながら、先ほど答弁したとおり、耐震制能につきましては関係法令に基づいて確保されたものです。","voiceIndex":199,"id":"exchange-078"},{"speaker":"こしば副委員長","kind":"質問","question":"結論を出すで、不採択でお願いします。この２か月の期間によって多くのサービスの利用者にとって不利益を被るおそれがあるということもありまして、区役所のほうからは、課長のほうからは先ほどは適宜、改善をしていきたいという答弁をいただきましたので、今後の措置、取組に期待をしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-079"},{"speaker":"こんの委員","kind":"質問","question":"本日結論を出すでお願いしたいと思います。それで、先ほど皆さんの、他の委員の質問で、この陳情内容に書かれている具体的なところについても、また、是正をするところについても、区としては計画的に進めているという、こうした答弁も分かりましたので、そうした意味からしますと、この陳情については、区も進めているといったところでは、この陳情については添い難いといったところで、結論を出します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":203,"id":"exchange-080"},{"speaker":"ひがし委員","kind":"質問・要望","question":"結論を出すで、今回福祉会館の不適合箇所の是正については、必要な箇所について現在行政がしっかりと進めてくれるというふうな説明がありましたので、今回は不採択とします。そのため、戸開走行保護装置等の設置については、いつ起こるか分からない災害に備えて、一刻も早く、災害が起こったときに安全が確保できるような整備を進めていただくように、そちらについては求めします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-081"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結論を出すということで、採択でお願いしたいと思います。しかし、エレベーターのところでは、二、三か月止めなければならないということなので、全面的に改修するというようなことはなかなか難しいというところで、そういうことで言えば、この陳情者もずっと求めていますけれど、身障者会館を早くに改築をしていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-082"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。ご答弁あったとおり、既存不適格の箇所はやれるところはやるということですし、また、建物自体の耐震性も問題ないということから、不採択でお願いします。一方、なるべくその既存不適格の箇所は早期に是正していっていただきたいということと、将来的な改築をぜひ早期に進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":206,"id":"exchange-083"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すでお願いします。今、お話を聞きまして、既存不適格の部分もできるところから、真剣に予定してやっていただけるということですので、そちらのほうはぜひ進めていただきたいと思います。現状で不適合と指摘されている部分は、今お話いただいたように早急に改善のほう検討していただいて、また、建て替えに関しても併せて真剣に取り組んでいただきたいと思いますので、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"本日結論を出すで、採択にしますけれども、お話伺っていて、前回の陳情出されたときに比べて、やはり是正箇所に、来年度、予算の要望をしているなど、取組をしていただいているのは非常によく分かって、恐らく、前回のときと違って、他の委員も、区として進んでいるということを非常に感じているような雰囲気が出ていると思います。私もそうだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-085"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"それから３つ目なのですけれど、地域支援のほうで同行援護も就労で使えるようにするという方向で区としては検討されているのか、これもずっと要望が上げられていて、就労でも使えるようにしてほしいということは、区独自に判断してできることだと思うので、ぜひそうしていただきたいということは申し上げてきたところですけれど、そういう方向で区として検討されているということなのか。","respondent":"松山障害者支援課長","answer":"同行援護のサービスにつきましては、詳細につきましては、ただいま検討しています。何とか可能な限りお応えができるような形で検討しています。","voiceIndex":218,"id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問・要望","question":"同行援護がそういう方向で進みそうだというのは本当にぜひよろしくお願いしたいと思います。そういうふうなところも把握もしていただきながら、社会福祉法人のほうとしても積極的に障害者雇用を進めていただきたいということで、仕事をつくり出す、そういう視点で取り組んでいただくようにということで働きかけていただきたいということで、時間も押していますので、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-087"},{"speaker":"ひがし委員","kind":"確認","question":"それと、その就労移行の支援などを受ける事業所に視察も行かせていただいたことがあるのですが、結構手続のところに時間がかかるというような話を聞かせていただいたのですが、窓口にそういう事業所を利用したいとなったときに、ステップとしては、就労移行事業所にまず、問合せして事業所に見学に行って、その後、内容とかを見て事業所を決定した後に。","respondent":"松山障害者支援課長","answer":"その前に、就労移行支援事業所とかで、国から就労アセスメントを取るようにということが出てきているので、もしかしたらそこの期間がプラスされているようにはお見受けしますが、区としてはできるだけ早く、やはりご利用いただきたいので。","voiceIndex":222,"id":"exchange-088"},{"speaker":"ひがし委員","kind":"確認","question":"例えば、医療の電話とかだと、退院する前にアセスメントを電話とかで聞いたりとか、現場に来て聞いて、その人が大体どのぐらいの認定なのかといったことを見込みの確認を取ってから、利用は退院してからすぐにはできるけれど、遡って料金を請求したりとか、まだ認定証は届いていないけれど、このぐらいの介護認定を取れそうだからこの利用ができるよねといってお金を後から逆算して請求したりとか。","respondent":"松山障害者支援課長","answer":"地域自立支援協議会等で就労支援部会というのがございまして、就労関係の事業所は集まって、現状ですとか改善するような課題というのを区と一緒に話すのですけれども、こちらのほうで現実的に。","voiceIndex":224,"id":"exchange-089"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ、そういう事業者のお声聴きながら、もう既にそういうような利用をしているようなサービスとかというのがあると思うので、こういう移行支援のところでもそういう手続の取り方ができると、事業者の負担だったりとか、さらにその利用する方々も、利用したいと思ってすぐに始められるというようなところで、移行支援のところに利点も多いかなと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-090"},{"speaker":"こんの委員","kind":"質問","question":"障害者の方のお仕事をどう確保するかというか、そうした観点を少し聞きたいのですけれども、方向性というところにもうたってありますが、多様な就労機会の確保、それから就労支援の充実といったところがあるわけですが、具体に、例えば就労継続支援Ｂのところで先ほども質問がありましたが、事業によって工賃が違うといったところで、去年ですか。","respondent":"松山障害者支援課長","answer":"一つ、今回１月２９日にある超短時間雇用シンポジウムのところでは、本当に業務の切り出しというのが非常にポイントになってきておりまして、例えば具体的に言えば、本当に少し、１５分単位のお仕事、それ以外にはお仕事をしないというもの、はっきりとした業務の明確化をして。","voiceIndex":228,"id":"exchange-091"},{"speaker":"こんの委員","kind":"質問","question":"現状分かりました。この１月２９日のシンポジウムでも、ぜひ参加させていただいて、その取組なども、私も勉強していきたいというふうに思います。今、パン屋さんを、プチレーブ、やっていらっしゃると思いますけれども、こうした、いわゆるこれは、例えば、今度新庁舎を建てたときに、その中に障害者の方のそうしたショップなども考えられると思うのですが、その辺はどんなふうにお考えでしょうか。","respondent":"松山障害者支援課長","answer":"２点目の障害者の方の就労、プチレーブ等も例に出していただきますけれども、この新庁舎の中でということで、今、新庁舎整備のほうもいろいろ検討を進めているところです。","voiceIndex":230,"id":"exchange-092"},{"speaker":"こんの委員","kind":"意見","question":"新庁舎のところでは、そのように進めてくださっているということですので、ぜひお願いしたいというふうに思います。何かございましたら。","respondent":"松山障害者支援課長","answer":"委員ご提案の様々な区内の場所もありますし、なかなか就労支援部会の中でも、様々に事業者からの声を聞いて、皆さんで協力して、どこか区内の、実製品の物を皆さんにより見ていただいて、販売ができるようなスペースがあるかどうか。","voiceIndex":232,"id":"exchange-093"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"１点だけお聞きします。募集等はもう始まっていらっしゃるのでしょうか。今後のこういった対象になる方の流れ等を教えていただければと思います。","respondent":"松山障害者支援課長","answer":"今お尋ねの、募集の受付期間です。１月１７日から２月２９日までということになっておりまして、２月２９日の５時までに区役所に必着ということになっております。","voiceIndex":240,"id":"exchange-094"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3682#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":80863,"voices":247}},{"id":"r06-20240122-8","meetingId":"r06-cm01","date":"2024年1月22日","dateIso":"2024-01-22","committee":"建設委員会","time":"午後 １時００分～午後 ４時５４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の順番を入れ替えまして、(3)令和６年２月都営住宅入居者募集","agenda":"の順番を入れ替えまして、(3)令和６年２月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"それと、区営住宅のときにも求めましたけれども、申込用紙の配布期間が受付期間とずれているという問題で、やはりそうすると、申込者の方が申し込もうと思っても用紙がもらえないということにもなってしまいますので、ぜひ配布期間を受付期間まで延ばしていただきたいと思いますけれども、いかがでしょうかということと、区営住宅でも空き室のお話をさせていただきましたけれども。","respondent":"竹田住宅課長","answer":"４点ご質問いただきました。倍率ですが、前回、令和５年１１月の平均の倍率が１９.７倍、それから前年の同時期の２月の募集が１９.０倍となっています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"ですので、実際に申込みができる期間だけれども受け取れないという人が出てきてしまうと思いますので、そこはぜひ改善をしていただきたいと思いますが、いかがでしょうか。今、どこを交渉しているのかも含めて伺えたらと思います。空き室の公表については、区営住宅のほうになってしまうのですけれども、区営住宅の空き室も公表したらどうかと思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"区営住宅の空き室ですが、前回も申し上げましたが、様々な理由で、退去されても残置物があるとか、あるいは、原状回復途中だとか、様々な理由がありますので、区営住宅をご提供できる可能数を提示することによって、ご理解いただきたいと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"これは要望しておきたいと思います。移管のところでは、私の手元で見ると、管理戸数が１００戸以下というものが５棟あるので、５棟とすると、照会が来ているのかなと思います。移管するにせよ、東京都のままにせよ、公営住宅のニーズが、やはり実績として倍率が高いというところで、これを減らさず、むしろ増やしていくということで進めていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"}]},{"id":"topic-02","title":"戸越６丁目地区における地区計画の変更","agenda":"戸越６丁目地区における地区計画の変更","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、先ほど、意見書での意見についてはご説明があったのですけれども、説明会では、どういった質疑や意見などがあったのかを伺いたいと思います。それと、防災生活道路３号のところなのですが、現在の道路幅員が４.５ｍから８ｍということだと思うのですが、大体この辺は広かったかなと思ったのですが、６ｍ以下になっている箇所はどこになるのか伺います。","respondent":"小川木密整備推進課長","answer":"令和３年度には、その勉強会を基に密集住宅市街地整備促進事業を導入しておりまして、これを受けて、地区計画を現在検討して導入を進めていこうと考えているところです。","voiceIndex":14,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"拡大する経緯について、検討段階は分かったのですけれども、東地区でどういう効果があってなったとか、そういったことは特にないということなのかというところを伺えたらと思います。要望です。","respondent":"小川木密整備推進課長","answer":"拡大するに当たっての東地区の地区計画による効果かどうかというご質問ですが、具体的な目に見えての効果はまだないのですけれども、やはりこの戸越六丁目の周辺の町丁目も全て地区計画がもう定められておりまして、残すところは。","voiceIndex":16,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"この周辺は、補助２９号線の開発もやっているし、それから、少し外れますけれども、戸越公園周辺のまちづくりも始まっているので、多分ここに住まわれている方々が、何が起きているのかというところなのかなと思うのです。ほかの地域で、最近、同じような説明をして、そういうふうに受けたところがあるので、そこは丁寧にご説明いただきたいと思いますが、いかがでしょうか。","respondent":"小川木密整備推進課長","answer":"２点目の分かりづらい、今、様々なまちづくりが、特に戸越においては行われておりまして、地域の協議会からもそういった声を多くいただいておりますので、今後、その協議会の場等で、再開発等に関係する所管の都市開発課と連携して。","voiceIndex":19,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"戸越公園周辺の開発も進んでいるところがあると、このまち、どうなってしまうのかということが、やはりこの地域の方々は非常に気になるところだと思います。それもお知らせをしていただくことによって、夢というか、希望というか、何かそういう利便性がよくなるのねという思いがあるのであれば、そちらも教えてあげたらいいのかなというふうに思いますが、いかがでしょうか。","respondent":"小川木密整備推進課長","answer":"まちづくりの取組に関する進捗に合わせての地域の皆様等へのお知らせ関係ですけれども、進捗等に合わせては、我々も年に２回、まちづくりニュースを発行して、この地域に住まわれている方、また、権利者の皆様、全ての方に配布をしていますが、そういったものの中で、現在。","voiceIndex":21,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"同じく防災生活道路に関連してお伺いしたいのですが、２号、３号、先ほどのご質疑の中で、６ｍ以内のところは、特に大井町線との交差の部分だというお話がありましたが、一方で、大井町線も連続立体交差事業ということで高架化の方向にいって、今、準備が進められておりますが、それとの関係性で、今の既存の形態においての防災生活道路の線引きになっていますが、鉄道の立体化との関係性で。","respondent":"小川木密整備推進課長","answer":"防災生活道路の２号と３号と東急大井町線の高架化の関係性ですけれども、２号、３号につきましては、幅員もそうなのですが、それよりも、やはり線形が課題というふうに我々は捉えておりますので、高架化の整備と併せて、まずは線形を解消したいと、できる限り。","voiceIndex":24,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"目指すところは同じだと思うのですけれど、その過程におきまして、高架化された後の直線ルートを防災生活道路として使用することが理想だと思うので、先にそれを、この部分も直線で線を引くということは、現状は難しいというか、できない。今の既存のルートの中においての拡幅を先に指定せざるを得ないということが現状なのでしょうか。","respondent":"小川木密整備推進課長","answer":"こういったものを防災生活道路として指定することで、より防災上重要な道路と位置づけられますので、より線形をしっかりとやっていかなければいけないという区の姿勢をしっかりと示して、それを鉄道事業者、また、道路・交通管理者のほうに訴えて。","voiceIndex":26,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"併せて、鉄道の立体化に関連して、最近の法改正で関連側道ということで、立体化したことで側道を設けなければいけないような箇所もあろうかと思うのですが、今後、将来的には、そういった関連側道も６ｍにする必要があるのかどうかということもあるのですけれども、そこも１つ、この地域での防災性の強化という視点では大きな効果を発揮するものだと思うのですが。","respondent":"大石まちづくり立体化担当課長","answer":"連立事業に伴います関連側道に関するご質問です。今現在予定しております幅員につきましては、説明会でもご説明しているのですけれども、６ｍを予定しておりまして、基本的には歩行者、自転車の専用、車が通れないような規制をかける予定にしております。","voiceIndex":28,"id":"exchange-010"},{"speaker":"田中委員","kind":"確認","question":"すみません、少し範囲が広がってしまいますが、駅前広場となると、戸越五丁目の地域のほうで、六丁目の区間での関連側道も、歩行者・自転車専用道路になると、防災生活道路の指定にはそぐわないというか、当たらないというところでしょうか。そこだけ確認をお願いします。","respondent":"大石まちづくり立体化担当課長","answer":"防災生活道路としては、基本的には位置づけは予定しておりません。ただ、アクセス、歩きやすいまち並みだとか、歩いて広域避難場所の戸越公園のほうに避難できるような形で、関連側道の部分の６ｍをしっかり活用していきたいと考えております。","voiceIndex":30,"id":"exchange-011"},{"speaker":"田中委員","kind":"意見","question":"そういう意味でも、この地域の道路、車道ではないのですけれども、地域の安全性という視点では、関連側道も将来的には防災性向上の１つの大きな役割を果たしてくるだろうと思えるので、そういうところも含めてお示しをいただけると、オール区役所としてのこの地域での取組が、ここには書かれていない要素も含めて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-012"}]},{"id":"topic-03","title":"ごみ分別アプリの導入","agenda":"ごみ分別アプリの導入","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"内容はすごく分かりました。これからの展開の段階を伺えればと思います。これは必要だと思うのでいいと思うのですが、多くの方に利用していただきたいという中で、これをまず知っていただく方法。受け身なのか、それとも、区からどんどん営業をかけるではないですが。アプリのダウンロード数だとか、数値目標があれば、併せてお知らせください。","respondent":"品川品川区清掃事務所長","answer":"それから目標なのですけれども、大体他区の導入率を見ると、１０％にいっていればかなり上出来なほうなので、とにかく少しでも多くというところですが、まずは１０％ぐらいを目標にやっていきたいと考えております。","voiceIndex":37,"id":"exchange-013"},{"speaker":"渡辺委員","kind":"意見","question":"段階ということで、私の思いも次年度すぐというわけではないのですが、１つ動機で申し上げたいのが、回収した後の清掃事務所での火災だとかトラブルが年末にあって粗大ごみの搬入が困難になっている。それが背景です。これがやはり３か年計画だとかを立てて、より多くの人に知ってもらう、そして、やはりそこでごみの分別の大事さを普及啓発するにはコストがかかっていいと思うのです。","respondent":"品川品川区清掃事務所長","answer":"ただ、完璧にこれが周知できるという状態を達成するのは非常に難しいかなと思いますので、少しでも、いろいろな方法で周知できるようにということは考えております。","voiceIndex":39,"id":"exchange-014"},{"speaker":"西本委員","kind":"提案","question":"今の渡辺委員の提案、すごくいいなと思って聞いていたのですけれども、このアプリは、独自のもの、それとも既存のもので品川区バージョンにしたのかということと、自由度、いろいろ将来性のある内容だと思うので、変更であるとか、あとは付加することも自由にできるのかという、ある程度決まってしまっている部分があって、なかなかそこを越えられないとかということなのか、少しそこを教えてください。","respondent":"品川品川区清掃事務所長","answer":"この製品につきましては、基本的にはパッケージ商品となっておりますが、独自でこのパッケージ商品を購入しているというような契機もありまして、変更については、ある程度は柔軟にできるかなというふうに思っております。","voiceIndex":42,"id":"exchange-015"},{"speaker":"西本委員","kind":"意見","question":"もう１つ、気がついた点をお知らせくださいみたいな、そういう機能はつけられるのか、これ、クレームが多いので、職員の方の対応が結構大変になってしまうかなという思いはありつつも、取り残しているよとか、いろいろご意見を聞くことは悪いことではないかなと思うのですが、その辺の対応はどうお考えになっていますか。","respondent":"品川品川区清掃事務所長","answer":"現在のところは、情報を出す、発信するだけの機能になっていますので、収集する機能のほうについては、少し研究させていただきたいと考えています。","voiceIndex":44,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"なかなか見て見ぬふりをするというケース、カラスの問題もあるでしょうし、猫の問題もあるでしょうし、そういうところも解決できるような、また、情報発信ということであれば、やはりこういう問題がありました、こういう解決をしましたみたいな発信をしてあげることも大きな興味の起きることかなと思いますので、どうぞこれから研究を深めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"それと、発信が主だという話ではありましたが、ある意味、細かい話かもしれませんが、カラスが突っついて散らばっているというところをたまに見かけますが、逆にそれをあえて受けていただいて、なかなか理解が進んでいない方がこの辺にいらっしゃるということが分かれば、その周辺なり、そういうケースは特定の集合住宅だろうと思うのですが、そういうところの入り口などに。","respondent":"品川品川区清掃事務所長","answer":"確かに情報を収集する機能というところは、つけることが非常にいいと思うのですけれども、これも時と場合によりまして、やはり収集していると、対応が物すごい量になってしまったりとか、そういう例なども聞いたりしますので、その辺は少し慎重に進めていきたいと思います。","voiceIndex":48,"id":"exchange-018"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"アプリは大変すばらしい機会になると思っています。そこで、パッケージ商品なので、これからいろいろ何をつけるということはある程度柔軟にできるというお話が今ありました。そこで、質問としては、これはもう当たり前ですけれども、日本語対応だけではなくて、外国の方も当たり前のように見られるといいますか、外国語対応、そういうものも入っているのか、そこだけ確認させてください。","respondent":"品川品川区清掃事務所長","answer":"メニューの設定状況とかを見ている限りでは、外国語対応が今はできていない状況ではありますので、〔同日後刻に「多言語対応をある程度やっている」と答弁訂正あり〕当然こういうものですから、外国語対応していくような形で進めていくべきですので。","voiceIndex":51,"id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"私も今のまつざわ副委員長の外国語対応、そこが一番聞きたくて、この事業の目的が、収集日とか、分別をしっかりやっていただきたいと。逆に言うと、こういうことはいろいろな声で、守りづらい方、守る環境がなかなかない方は、どのような方々なのか、まずお聞きしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"こういう方については、アプリというのは非常に有効的ではないかなと考えております。","voiceIndex":54,"id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"最初から対応できるのであれば、この場で明確にご答弁もあるのかなというふうに思うので、そこはひとつ力強いご答弁を聞きたいなということが１つと、ちなみに、粗大ごみはどういう形になるのかということと、少しこれ、飛び火してしまって、さっき、所長のほうからも環境というお話があって、私の漏れがあったら申し訳ないのですけれども、エコルとごしという。","respondent":"品川品川区清掃事務所長","answer":"外国人に対しては、ごみの出し方等のパンフレットでは４か国語の対応をしていますので、何かあるときには、そのパンフレットを持っていって身振り手振りで説明をしながら理解をしてもらうということが現状の対応なのですけれども、いろいろとご説明をしている中で。","voiceIndex":56,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、全体版は今回資料としてないのかなというふうに思うのですが、ぜひ出していただきたかったと思うのですけれども、いかがでしょうかということと、今回、２６地区に分けて影響を受けたということとか、いろいろ出されておりますけれども、２６地区で、実際に回答は何件あったのかということも、ぜひ出していただきたいと思うのですが、いかがでしょうかということと。","respondent":"河西情報戦略担当課長、鈴木都市計画課長","answer":"ですので、区民の皆さんには、このイメージ図を見ていただいて、共感いただけるところがきっとあると思います。区民の皆さんがどのように感じているのかを参考にしていただくための資料とご認識ください。本日は概要版でのご説明ということで、全体版につきましては、本日お示ししながら概要版でご説明というところが一番よかったのかなですが、なかなか全体版が、本日、鋭意まとめを頑張ったのですが。","voiceIndex":64,"id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"区民の２４.３％ということで、約４人に１人が回答したということで、このことをもっても、このアンケートは重要なものだと思うのですけれども、そこの受け止めも伺えればと思います。そして、「影響を受けている」という方が、やや受けているという方も含めて、４４.５％いらっしゃるということは、私は重大な影響が出ていると思っているのですけれども、区の受け止めを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"全区民アンケートの結果の受け止めですが、委員ご指摘、ご説明いただいたように、４人に１人の方にお答えいただきまして、その中で約４４％の方が、ややも含めると、影響を受けているという回答。","voiceIndex":67,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"このアンケート、今回、約８万７,０００人もの方が答えていただいたということで、これまでこうしたアンケートは、区として行ってきたのかどうか伺いたいと思います。今回、新たに集計データを国交省に届けるということで、恐らくこの自由意見の中には、影響を受けている区民のより生々しい声が示されていると思いますが、これを受けて、何を要望するのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"は１点目のこれほど大規模なアンケートをこれまで区として行ったことがあるかですが、羽田に関してということでお答えしますが、羽田新飛行ルート運用開始前、あるいは運用開始後、こうした区としてのアンケートをこれまでに行ったことはございません。","voiceIndex":69,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、集計データをまとめて届けるということで、そのときにも恐らく何か要望するのかなと思うのですが、何を要望するのか、改めて伺います。","respondent":"鈴木都市計画課長","answer":"最終的には、その結果を国に直接届けたいというふうに考えてありますが、先ほど、この概要版の１４ページのところでもお示ししておりますが、この係り受けの「飛行機－飛ぶ」ですとか「窓－開ける」、２万８,０００件弱の自由意見。","voiceIndex":71,"id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、この集計データ、オープンデータを区ホームページにも載せるということですけれども、区ホームページにアップするものは、オープンデータと同じ中身がアップされるという考えでいいのかどうか、そこのところを確認させていただきたいと思います。","respondent":"河西情報戦略担当課長、鈴木都市計画課長","answer":"こちらに掲載するものは両方とも同じものになります。全ての回答いただいたデータ。ただし、個人を特定するようなデータは、黒塗りないしは削除させていただいたものを公開する予定です。併せて、空港環境担当係長、係員が２名おりますが、そちらの職員の中でも目を通させていただいたです。アンケートの１つ１つの自由意見の結果については、区長にもお渡ししています。","voiceIndex":73,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"自由意見欄を読んだということですので、ぜひ課長の読んだ感想というか、受け止めを伺いたいと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"非常に膨大な数の意見を１つ１つ読んでいくというところで、全体としては、結果で先ほどもご説明させていただきましたが、やはり騒音で、例えば、コロナ禍でリモートが進んで自宅で仕事をされている方が、なかなか音がうるさいですとか、これは以前から。","voiceIndex":76,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりルート直下だけでなく、区内全体としても影響があるということですので、区としてやはりしっかり取り組んでいただきたいと思うのですけれども、だからこそ、今回、住民団体の代表の４名の方が連名で、羽田新ルートのアンケート結果について、ぜひ区長と直接会って面談をしたいということで申入れをされたというふうに思うのですが、それはどういった対応を区としてされたのか伺いたいのと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"これはアンケート結果のことについてなので、ぜひ区民に説明してほしいということなのです。そうしたことをお願いしているのですが、ご答弁いただけるでしょうか。","respondent":"鈴木都市計画課長","answer":"区民の方への丁寧な周知ですが、今回、概要版、それから全体版、それからオープンデータという形で、しっかり区のホームページ、あるいは東京都のホームページにも掲載して、しっかり広く公表していきたいです。","voiceIndex":80,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"直接申出があったわけですから、ぜひそうしたところも含めて説明をしていただきたいというふうに要望しておきたいと思います。やはりこうしたアンケート、多くの方に答えていただいて結果が出たわけですので、今度、集計データを国交省のほうに持っていくということですので、そこでも、ぜひ羽田新ルートはやめてほしいということで要望していただきたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今、自由意見欄を含む最終的な取りまとめを行っている中で、国のほうに改めて直接届けるために、今、準備を進めているところですが、先ほどご答弁したとおり、区民負担軽減につながる取組を、全体版をお渡ししていく中でも、しっかり国のほうに求めていきたいです。","voiceIndex":82,"id":"exchange-030"},{"speaker":"西本委員","kind":"意見","question":"そもそも論から入りたいと思います。アンケートをやるということは、当然そのゴールがありますよね。目的があって、何のためにこれをやったのか。その目的に対してゴールがあるのだろうと思うのですが、まずそこをお聞かせください。","respondent":"鈴木都市計画課長","answer":"今回のアンケートを行うときも、区としては議会等でご説明していますが、アンケートで何か賛成反対というところをお聞きしてアンケートを行うということはせずに、やはり地域ごとで、それぞれ区民の負担感、影響が様々あろうというところで。","voiceIndex":85,"id":"exchange-031"},{"speaker":"西本委員","kind":"確認","question":"負担軽減ということなのですけれども、何も書いていないですよね。今までと同じですよね。状況確認は必要なことだと思うのですが、アンケートというのは、かなり恣意的なのです。この全体版を国交省に持っていって何をするのですか。品川区としてどうしてほしいかということはっきり言わないと意味がないのではないのですか。これ、どうするのですか、このアンケートの結果。これからどう料理するのですか。","respondent":"鈴木都市計画課長","answer":"これは全体の結果を受けても、これから全体をお持ちするところにおつけする文書についてもしっかり検討して、国のほうには改めてしっかり要望していきたいです。","voiceIndex":87,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"負担軽減とは何でしょうか。地域によってもいろいろ変わると思うし、人によっても変わるだろうし、だから、区として、負担という、負担軽減というのは、どういうことを示しているのかということの方向性は明確にすべきではないのでしょうか。なぜこれをやったのですか、１億円もお金をかけて。目標は何でしょうかということです。でも、国交省の見解はどうなのでしょうか。そこを確認したのでしょうか。","respondent":"鈴木都市計画課長","answer":"第１回の中でも、冒頭そういうご説明もありましたし、しっかり区民負担、区民の影響の軽減に向けた取組を固定化回避検討会の中で一刻も早く示していただいて、具体的に実施していただきたいというところが、これはアンケートの結果を背景にして、区長が直接、大臣のところに届け。","voiceIndex":89,"id":"exchange-033"},{"speaker":"西本委員","kind":"確認","question":"私が言いたいのは、１つに、国が思う感じ方と、品川区が感じている数字に対する感じ方は一緒ですかということです。確認したのですか。だから、それをずれていないような確認はいつやるのでしょうかということが１つ。でも、あれは公の場所ではないですから。ここで何を言うのでしょうか。区民の方々への説明は、ここで終わりですか。どういう説明をするつもりなのでしょうか。それについてお答えください。","respondent":"鈴木都市計画課長","answer":"国のほうには速報版という形のものをお持ちしているわけですが、当日の１２月１日は、この速報版を使って、アンケートの結果を区長のほうからご説明をして、大臣のほうからは、「重いアンケートであり、しっかり受け止め、検討する」という回答、発言があったところです。","voiceIndex":91,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、１月３１日の記者会見では何を言うのですか。こういう結果でしたと、それだけですか。これを基にして、品川区の考え方や方向性を言わないといけないのではないのですか。次、どうするのですかという話ではないですか。アンケートをやって、このアンケート結果を次にどう持っていくのですか。知らせて終わりなのでしょうか。テキストマイニングで何を言いたいのですか。非常に不親切ですよね。","respondent":"鈴木都市計画課長、河西情報戦略担当課長","answer":"今回のテキストマイニングですが、やはり相当の数をこうした係り受けという言葉で、その傾向といいますか、その固まりをある程度お示しして、やはり１つ１つ、これだけの大きな結果ですので。「飛行機－騒音」に関しては、６７７件、回答いただいたアンケートのうち、これだけの数の区民の方が「飛行機－騒音」に関して関心を持っていらっしゃるというところで、区民の意見をまとめて集計して。","voiceIndex":93,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"そろそろまとめますが、結局、このアンケートで何を言いたいかということを、１月３１日にはっきり言ってほしいと思います。ですから、区長としては、賛成もしない、反対もしないという態度だということです。はっきり言っていないのですから。そこは要望として言っておきます。そこから何を言いたいのですか。何のための分析をやっているのですか。それが区民の方々に対して当たり前の報告ではないですか。","respondent":"鈴木都市計画課長","answer":"特にルート下近傍については非常に大きかったですので、しっかり取りまとめを行って、国のほうには改めて、この負担軽減につながる取組、これは国策として国のほうで進めている羽田新ルート、その中で固定化回避の中で国がそうした検討会を立ち上げて。","voiceIndex":96,"id":"exchange-036"},{"speaker":"西本委員","kind":"確認","question":"最後に１点だけお聞きします。例えば、二重窓をつけるために支援をしますとか、助成金、補助金を出しますよとか、そういう話に持っていこうという話はないですよね、それを確認させてください。騒音だけになると、やはりお金で解決しようというふうに動く可能性もあるので、決してそれは区民の皆さんの総意ではないというふうに思っているので、そこは少し気をつけてほしいと思っていますが、いかがですか。","respondent":"鈴木都市計画課長","answer":"固定化回避の中で示されようとしているのが、当初１２の飛行方式の中から、今、２つの飛行方式に絞られて、安全性の検証、曲線を描きながら同時進入する、その安全性の検証が今行われているというふうに聞いてありますので、国のほうには。","voiceIndex":98,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"そういった前提の中で、今回の飛行機の関連で、私もまだ１年たっていませんけれども、議会と区長との関係性でいうと、地域の方々から再三、毎回のように建設委員会に羽田空港のルート変更なり見直しに対する請願・陳情が出ていて、私は結論を出すべきとして言っていますが、結果的には、継続審議にずっとなってしまっていました。きっかけは何だったのか。","respondent":"鈴木都市計画課長","answer":"今回、その内容が、騒音、しかもルート下近傍について非常に顕著であったというところと、この軽減策を、１２月１日は直接訪問して強く申入れをしたです。","voiceIndex":101,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"なので、いろいろな声を聞いて、それをそのまま直接国交省に伝えるというやり方ではなくて、区長として、区民の声をアンケートという形だけでなくても、いろいろな形で声を聞き、政策としてどうあるべきかというものが一本筋が通った中で、それを補う上で、アンケートなり、また一方で議会からの声もしっかり踏まえた中で施策に生かすということが本来だと思うのですが、今回のアンケートの集計も。","respondent":"鈴木都市計画課長","answer":"他区の状況ですが、お聞きしているところ、港区で、アンケートといいますか、区民に行ったということは聞いていますが、この港区の実施の仕方が、基本的には全区民に羽田新飛行ルートの運用はこういうものですよということを説明した国の資料を配布して。","voiceIndex":103,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"だから、区長がどういう意図でということはあるし、また、区長が今回のアンケート結果を受けて、区民負担軽減につながる取組を求めるということでありますが、もう一歩踏み込んでとか、では、具体的にどういうところを今回の結果を受けて、飛行機が飛ぶ飛ばない、見える見えないとかということをどうされようとしているのかが、いかようにもとれるので。","respondent":"鈴木都市計画課長","answer":"これは国策ですので、その取組についても、国のほうで、その方法については、今正に固定化回避検討会の中で示していきますよと国は言っておりますので、区としては、一刻も早い具体的な提示を求めて、その実現を一刻も早く行っていただきたいというところは。","voiceIndex":105,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"同様の姿勢で、やはり航路に関しても、声がこうだったからこうというのは、どこまで影響を受けてしまっていいのかというか、要は、区長としての基本線がしっかりあった中で、声は声としてしっかり承り、不安に対してはこのような形で対応するという、そういう姿勢で今回のアンケートを受け止めていただいて、区長としての施策推進につなげていただきたいと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-041"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、実際、区内では、管理不全の兆候ありが７５棟あるということで、これはその後、どういった手続というか、どうなっていくのか、対応がされるのかということと、不全になっている理由はどのようなことがあるのか伺います。","respondent":"竹田住宅課長","answer":"管理不全の兆候ありの７５の内訳なのですが、マンションによって１つしかつかないもの、あるいは複数つくものがあるのですが、最も多かった項目が、修繕の計画的な実施が行われていないマンションが５２、それから、総会の議事録がないものが２２、それから３番目に多かったのが。","voiceIndex":113,"id":"exchange-042"},{"speaker":"のだて委員","kind":"確認","question":"そうすると、どちらかがついてしまうわけだから、あっても管理不全ということなってしまいませんかということなのですけれども、今、そういう説明になってしまっているのですが、そこはどういうことなのかというところの確認です。","respondent":"竹田住宅課長","answer":"こちらの届出項目のところですが、例えば、管理組合があれば居住者の方の意思決定ができるわけですが、ないということになると、例えば修繕が必要になっても、修繕に対する意思決定ができないということになりますので、管理組合が「ある」、「ない」というのは。","voiceIndex":115,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"管理不全の状況ということで、今ご説明があったのですけれども、７５棟が現在そうなっているということで、それも含めて、あと、実際問題、マンションの耐震化とかをしていく中での合意ができないということとか、さらには、建て替えを行っていくというのは、さらに難しいのかなというふうに思うので、そうしたことをやはり区として支援をしていくということが、もう１つ必要なのかなと思うのですが。","respondent":"長尾建築課長、竹田住宅課長","answer":"マンションの耐震化支援に関わるご質問について、お答えいたします。こちらにつきましては、建築課のほうで、マンションの耐震診断、補強設計、耐震改修工事に関わる部分の助成制度があります。マンションの建て替え修繕相談を行っておりまして、マンション管理士、弁護士等の方にご相談に乗っていただいております。それから、マンション管理士の派遣、相談等も定期的に開催しておりまして、様々なご相談に対応しています。","voiceIndex":117,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"なので、やはり使いやすくするという意味では、登録住宅も要配慮者が入居した場合、補助の対象にしていくということが、より使いやすく、要配慮者も住まいをしっかり見つけられるということになるのではないかと思うのですけれども、いかがでしょうか。それと併せて、ほかにも家賃補助をさらに広げていくということが私は必要だと思いますけれども、そこを併せて伺いたいと思います。","respondent":"竹田住宅課長","answer":"それ以外の支援も広げてはというお話ですが、まずは家賃低廉化から始めまして、登録状況等を見ながら、今後、検討していきたいと考えております。","voiceIndex":120,"id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"改めて答弁があれば伺いたいと思います。それと併せて、空き家対策のところでは、所有者不明土地のところが、財産管理人の選任が可能になったということで、これは区内では幾つあるのかというところと、実際にあるかということは分からないのですけれども、仮に処分をしてしまった後に所有者が見つかった場合はどうなるのか伺いたいと思います。","respondent":"竹田住宅課長","answer":"そういったところで、家賃の低廉化をすることによって入りやすい住宅にしていくというところが、こちらの制度の基本的な考え方ですので、まずは居住支援協議会にご参加いただいている不動産団体等のご協力を仰ぎながら家賃の低廉化制度が始まりましたので。","voiceIndex":122,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"今日も都営住宅の募集の報告がありましたけれども、１９倍という高倍率、以前の区営住宅のときには５０倍ということもあったと思うのですけれども、やはりそれだけ今、物価高騰で暮らしが大変だということもありますので、公営住宅の役割が求められていると思います。区としては区営住宅ということになると思いますが、ぜひ公営住宅の増設をすべきだと思うのですけれども、いかがでしょうか。","respondent":"竹田住宅課長","answer":"公営住宅に関する点ですが、セーフティネットの制度そのものですが、今後、日本全体が急激に高齢化、高齢者が増えて住宅の確保に配慮が必要な方が増えること、また、人口減少社会に向かう中で、民間賃貸住宅を有効に活用する必要があることなどから。","voiceIndex":124,"id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、家賃低廉化補助、他区では実績があるところもあるということで、ぜひそれは制度を使えるように増やしていただきたいとは思うのですが、実際、８戸、７戸、６戸と、多くて一桁台。特別区の自治体で一桁台の登録しかないということを見ると、やはりニーズと全くマッチしていないというふうに思うのです。これは強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"これ、多分、築４０年ぐらいたっている感じなのですか。それから、区独自基準があります。その解釈の違いを教えてくださいということと、空き家対策のところでは、上のほうに区内空き家の現状で、不適正管理状態９７があって、除却されたものが５４というのは、この９７の中の５４なのですか。それとも、不適正管理状態のものが９７足す５４という数値で見ればいいのでしょうか。そこの数値を教えてください。","respondent":"竹田住宅課長","answer":"マンションの未届、それから不全兆候ありの部分ですが、こちらのマンションについては、マンション管理士の方に１棟１棟訪問していただいて、管理組合がないということになると、代表者の方も分からないということで、非常に困難を極めているのですけれども。","voiceIndex":128,"id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"相手がいないのですから。誰か分からないのですから。だって、相手がいないのですから、いくら話に行っても進めようがないのです。それから、区独自基準というのは、５件目なのですけれども、もっとやってほしいです。町会が困っているのです。不安です。建て替えをしていただかなければいけないということだと思うのですけれども、それに対しては何か手だてはされているのでしょうか。","respondent":"竹田住宅課長","answer":"今後も粘り強く交渉するとともに、所有者が解決に全く関心がないということであれば、最後の代執行という手段もありますので、そういったものも視野に入れながら、所有者の方とは粘り強く対応していきたいと考えております。","voiceIndex":130,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"いずれにしても、住宅はそれぞれ個人の持ち物であり、生活ですので、なかなか強制的にというところは難しいかと思うのです。なので、その中に１人でも、そういうふうに何とかしなければいけないという人がいれば、その方をサポートする、そういう方を増やしていくという行動はぜひお願いしたいと思うのですけれども、そういうところがない場合は、やはり災害のときなど、周りも非常に心配だと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"今後、金利が上がったり、あるいは、ますます物価が上がり、人件費が上がったり、資機材費が上がったりしてくる中で、今現在の修繕計画が果たしていいのかどうかというところも、今は届出項目の中で修繕積立金があったり、計画がありますということで評価の対象になっているのかもしれませんが、継続的に今後も新たな経済状況の下において、それが有効に対応し切れるのかどうかというのは。","respondent":"竹田住宅課長","answer":"委員おっしゃるとおり、セーフティネットと空き家、両方非常に関連性のあるもので、空き家を利用してセーフティネットを改善していくということは、私どもも念頭にございまして、今まで空き家対策担当という係がセーフティネットのほうも担当してきたのですが。","voiceIndex":134,"id":"exchange-052"},{"speaker":"若林委員","kind":"質問・要望","question":"私どもも、この居住支援協議会を何とか早く、１年でも早く立ち上げていただきたいということで、ようやくという言い方はあれですけれども、令和２年に立ち上がって、ここまで取り組まれているのですけれども、今年度の開催も、この年度末になって１回というところで、今後の居住支援協議会のテーマ、在り方、そこも不動産団体との関係とか、協議内容とかというものもすごく、今回は、この居住支援相談会。","respondent":"竹田住宅課長","answer":"それは、不動産事業者のお立場から、それから、居住支援のお立場から、それぞれのお立場から入居後の支援のご意見をいただいて、今後の施策の参考にしていきたいと考えております。","voiceIndex":137,"id":"exchange-053"},{"speaker":"若林委員","kind":"質問","question":"２番の居住支援（セーフティネット）のほうですが、都の独自の支援は、毎年積み重なっているというような表現があったのですが、具体的にどのような、直近で、例えば、今年度だけでも、どういう独自なのか、今でも、後日でも構いませんので、教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-054"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"１月２日に発生した日本航空機と海上保安庁機の衝突事故について、少し伺いたいのですけれども、年初から様々情報提供をいただき、ありがとうあります。Ａ滑走路からの北向きの離陸が行われなくて、区民への被害がなかったことはよかったと思っています。","respondent":"鈴木都市計画課長","answer":"併せて、１月１９日になりますが、有識者を入れた航空機衝突事故対策検討委員会、この立ち上げが行われるというところも事前にお聞きし、これは１９日に開かれておりますが、そうした資料も、金曜日の夕方にはなりますが、共有をさせていただいて説明を受けたところです。","voiceIndex":145,"id":"exchange-055"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、原因については、まだあまり説明を受けていないということですか。原因は多分調査中だと思うのですけれども、分からない中で、今、運行が再開されているということですけれども、やはり安全性第一と考えるならば、この原因が分かるまでは便数を減らして運行するということが必要ではないかなというふうに思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"そのために、まずは国交省のほうで、先ほどの取組を、１月９日にまず公表して取組を進めているというところと、大臣のほうでも発言がありますが、安全運輸委員会の調査を待たずに、国としても対策検討委員会を立ち上げて、しっかり検討していきたいという中で。","voiceIndex":147,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4398#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":65126,"voices":149}},{"id":"r06-20240122-9","meetingId":"r06-cm01","date":"2024年1月22日","dateIso":"2024-01-22","committee":"文教委員会","time":"午後 １時００分～午後 ５時４５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和５年陳情第５２号、品川区の学校を子どもの安全に最大の配慮を行う「安全・安心で、楽しい学校」にするための陳情","agenda":"令和５年陳情第５２号、品川区の学校を子どもの安全に最大の配慮を行う「安全・安心で、楽しい学校」にするための陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"質疑を深めるためにも、質疑の前にぜひ意見陳述を受けて質疑をしていただきたいと要望いたします。皆様、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最初に、質疑から始めていただきたいと思っています。その後は、委員長のご判断でよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"陳情項目に沿って幾つかお伺いします。教職員も理解することが第一に重要だと。そこが、子どもの権利条約だけで１時間は使えませんということなのか、それとも、それだけで１時間やっていますということなのか、それが見えないのでお伺いしたいのが、項目１についての質問がまず１点です。職員会議は週に何回、時間は何分ぐらい確保されているのでしょうか。伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"職員会議の頻度ということですけれども、こちらも学校によって様々ですが、例えば、２週間に１回ですとか、月に１回ですとか、そういった頻度で職員会議、職員連絡会、そういったものは各校で設定して開かれております。","voiceIndex":11,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"子どもの権利条約の機会にしても、提要が出されましたといって、この提要を読んでおいてくださいということで周知はしていると思うのですけれども、実際に提要が出された後に、子どもの権利条約について学ぶ機会がどれだけ持たれているのかとか、あるいは、校則についてもそうなのですが、実際、提要が出された後に校則がどう変わったかという、現状把握が全然されていないのかと思ってしまうのですけれども。","respondent":"丸谷教育総合支援センター長","answer":"その辺りは、このようにするといいよというような示しとしては教育委員会はしていないのですけれども、限られた時間の中で効率的に情報共有を行い、教員がそれぞれその中で活動できるような、そういった連絡会というものを開いているという状況です。","voiceIndex":13,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのは、学級活動は定例化しているというところはあるのでしょうか。私は、週１ぐらい定例化していないと、実際何か、学校生活というのは３０人から４０人の子どもが一緒に過ごしているわけですから、いろいろ出てくるわけではないですか。していないのでしょうか。それとも、把握していないのでしょうか。伺います。","respondent":"丸谷教育総合支援センター長","answer":"校則についてですけれども、この数年来、校則の見直しについては周知をしながら、毎年毎年改善を行っているところですけれども、教育委員会としては改訂内容については把握しているところで、例えば、服装のことであったり、髪型のことであったり、そういったものを、例えば。","voiceIndex":15,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは提要でありますような、重視していますよね。それと、校則についての、１２年ぶりの生徒指導提要改訂の記述というのもかなり踏み込んだ内容で、かなり関係者から評価されていたと思うのですけれども、改めて区教委としては、提要の校則の部分のどこら辺を重視、どのように評価していて、今後区内の小・中学校の運営にどう活かしていくというお考えなのかというのを、改めてそちらも伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"今後、生活指導主任会ですとか、また、管理職向けの連絡会、研修会を通して、全ての内容を限られた時間で説明することは難しいとは思いますけれども、機会を捉えながら、生徒指導提要のここの部分にこのように書いてあるので。","voiceIndex":17,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、これは時代の流れもありますし、国の方針も変わっているわけですから、ここは重要視して、軽視しないでいただきたいと私は思います。ぜひ研修も実施していただきたいと思います。ここには一つ、子どものニーズに合わせたスペースを校内に確保し、教師やボランティアなどの人的配置などを求めておりますと。そして、どれぐらい拡大していくつもりなのかというのを伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"予算のことも絡んでくる内容ですので、少なくとも今現状１校ですけれども、これを複数校、もっと拡大をしていきたいと考えているところです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり今のご答弁を聞いても、まずはルールを守ってから考えましょうみたいな感じに、段階論に聞こえるのですけれども、やはり現状というのは、守ることが大事だよということを強調し過ぎるあまり、後半の、ルールそのものの前提を考えようとか、みんなで本当にこのルールというのは必要なのかとか、そういうところがあまりにも弱過ぎるので、今のご答弁を聞いても、前と今は変わっていませんと言われても。","respondent":"丸谷教育総合支援センター長","answer":"不登校のお子さんの民間施設を使ったときの支援についてですけれども、現在、東京都が調査協力金という形で、フリースクールに通われている児童・生徒には、東京都の事業で月２万円という形での支援がされております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"吉田副委員長","kind":"質問","question":"新任の先生とかは当然、これを読みなさいというような形で渡されていると思うのですけれども、私自身の能力の問題だと言われたらそれまでなのですけれども、読みなさいよと渡されただけでは、なかなか理解して、それを実践するというところまではいかないような気がするのですが、その辺について、先生への教育という言い方がいいのかどうか分かりませんけれども、どれくらいされているのか。","respondent":"丸谷教育総合支援センター長","answer":"その他の項目につきましても、先生方が読むことで理解が深まったりとか、児童・生徒に対応するときに役立つ内容が書かれていると思いますので、特に若手研修ですとか、若手から少し離れた中堅教員向けの研修も、教育総合支援センターが受け持っておりますので。","voiceIndex":24,"id":"exchange-009"},{"speaker":"吉田副委員長","kind":"提案","question":"ということは、教育総合支援センターとしては、そういう機会を持つようにということを学校に対しては提案をしているけれども、実態として、例えば、何年次研修のときには必ずその中身をきちんとみんなで共有しているというところまでは把握していないということなのでしょうか。その辺について、もう一度伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"例えば、学級経営ですとか、いじめの相談ですとか不登校対応、そういったものがありますので、生徒指導提要のところに立ち戻って、教員にとっての一つの教科書のような扱いで、そこに書かれていることを十分読んで活用するというような働きかけ、使い方というのはしています。","voiceIndex":26,"id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"まだ納得できるものではないのですけれども、現状そういうものであるということは理解をいたしました。それから、最後の不登校児童が増えているということについては、特に最近は低学年が増えているということは、危機感を持ってもっと捉えていただきたいと思っています。それから、マイスクールは、最終的にはやはり学校に戻すことを前提としておられるのか、その辺についても見解を伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"マイスクールの今後の検討というところですけれども、今、区内全体を見渡して、エリアをなるべく均等にしていきたいという思いがありますので、今回、４つ目のマイスクールができますが、今後、必要なエリアに設置ができればと考えております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"吉田副委員長","kind":"質問","question":"最後、フリースクールについては、品川区には今、私立のフリースクールは存在していなくて、私も把握している、大田区のシューレがちょうど区境なので、シューレがチラシをまいたときも、結構、品川区の区民からも問合せがあったということで、そういうところと連携しているということは評価をしたいと思いますけれども、先ほどの補助金も東京都ですし、品川区にないのに。","respondent":"丸谷教育総合支援センター長","answer":"フリースクール等に通われている児童・生徒への支援ということですけれども、今後の東京都の動きですとか保護者のニーズ等々、十分にこちらで把握をした上で検討していきたいと考えております。","voiceIndex":30,"id":"exchange-012"},{"speaker":"安藤委員","kind":"意見","question":"こういった品川の子どもたちの環境を心配して、陳情まで出され、そして、意見を陳述したいという積極的な区民の皆さんの議会への参加、歓迎すべきだと思いますし、ぜひ審議を深める意味でも、私はこの場で陳述を受けたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"意見","question":"意見陳述なのですけれども、この場では行わないということでお願いいたします。理由は、今、質疑がありましたように、私たちは区民の代表でありますので、それを踏まえて質疑をしている場でありますので、そういう観点から、行わないということでお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"民主主義というのは、間接民主主義と直接民主主義があると思いますので、もちろん私たちは区民から負託された代表者として議会に来て、責任を持った審議をしているわけですけれども、それを補完するという形で、やはり直接区民の皆さんからの意見を伺うという、直接民主主義で補完していくというのはすごく大事だと思っていますので、私は、今、高橋伸明委員が述べましたけれども、そういう意味では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-015"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"私もぜひ意見陳述をしていただきたいと思います。私は、品川区に陳情を出した陳情者に意見陳述の権利があるという制度を大変高く評価をしております。それで、過去をたどると、私が把握している限りは１回だけ意見陳述がありました。議員から物すごく意地悪な質問が飛んでまいりますので。その制度は活用されるべきであると思いますので、ぜひ意見陳述をしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いいたします。理由は、先ほどこの陳情項目４つに関してセンター長からご説明あったとおりだと私は思っております。適切にそれぞれ対応していただいているということで思っておりますので、それと、４番目の不登校児童生徒のマイスクールというのは、必要なエリアに応じてぜひ設置をしていただきたいということで、これは要望として述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"},{"speaker":"ゆきた委員","kind":"確認","question":"本日結論を出すで、態度は不採択でお願いします。理由は、ご答弁を今拝聴する中で、品川区として、各項目について既に取組を進められているということを確認できましたし、今後とも対策を進めていくという姿勢も確認できましたので、この陳情に関しては不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-018"},{"speaker":"吉田副委員長","kind":"確認","question":"本日結論を出すでお願いいたします。それぞれ陳情項目につきましては、今取り組まれている施策について確認をいたしました。個人的な意見としては、ぜひ採択としたいと思っているのですけれども、会派の中で議論したところ、やはり品川区がそれぞれ施策を進めているということで、進んでいる施策について確認をしていこうということになりましたので、会派としての不採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張したいのですが、陳情内容も、これまで現場で様々声が上がっていたことを踏まえた、国や世界的な潮流も踏まえた動きがある中で、それを踏まえて必要な対策を求めるものであり、すごく内容は正当なものだと思いますし、それと、もちろん品川区教委が何もやっていないとは思いませんけれども、今やっている施策をさらに進めていく内容にもなりますし、さらに、まだ不十分な点も。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ただ、やはりこうやって心配されたり、不信という言葉も出てきていますけれども、ということは、今進めていることが、しっかりと進めていただいているのですけれども、さらにここから発揮して進めていっていただきたいという気持ちが私はあります。ですから、現状の方策のさらなる加速を進めたり、あるいは、かゆいところに手が届く、細かいところをしっかりとやっていっていただきたいという要望はします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-021"},{"speaker":"石田（し）委員","kind":"確認","question":"今日結論を出すで、不採択でお願いします。一方で、今、答弁を聞いている中で、各陳情項目についてはそれぞれ対応されている、また、これからもしっかりと対応していくということは確認をいたしました。ただ、１点だけ、時代と社会の流れというのが今大きく移り変わっている中で、スピードも速い中で、そこはぜひ柔軟に対応していただいて、守るべきはもちろん守っていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-022"}]},{"id":"topic-02","title":"令和６年度新入学 学校選択の抽選結果","agenda":"令和６年度新入学 学校選択の抽選結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"前期、後期共に、抽選する割合と、あと、応募する方も減っていると思うのですが、この原因というのはどのように分析しているのか、教えてください。","respondent":"柏木学務課長","answer":"申請率は下がってありますけれども、指導課が実施しております保護者、児童・生徒アンケートでは、「学校選択制は良い制度だと思う」という問いに、保護者で９割近く、生徒では９割以上が肯定的な回答をしておりますので、ニーズとしてはあると。","voiceIndex":53,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"結果として通学区域を選択しているということなのですけれども、何でそういう通学区域の学校を選択している人が多くなっているのかという分析はしていないということなのですか。そこを伺いたかったのですけれども、お願いします。","respondent":"柏木学務課長","answer":"細かい分析をしているかというと、していない部分ではありますけれども、考えといたしましては、あえてほかの学校に行かなくても、自分が望む、または自分の子どもに適した教育が受けられるという判断があると考えています。","voiceIndex":55,"id":"exchange-024"},{"speaker":"ゆきた委員","kind":"質問","question":"もちろん学校案内でも、兄弟姉妹であっても同一の希望校に入学できない場合もありますとうたわれていまして、その点をご了承の上で学校選択してくださいとあり、学校選択においても、就学人口の増加とか、４０人学級から３５人学級の普通教室の不足という厳しい中ですけれども、この八潮学園については、課題として手を打たれていくべきものではないかと思われます。","respondent":"柏木学務課長","answer":"学校選択の取組ですけれども、まず、学校選択につきましては、以前も説明をさせていただいたかと思うのですが、まず、お住まいの方、就学人口に応じて学級数を決めた上で、その上で空きがある場合に、通学区域外の方を受け入れるという制度です。","voiceIndex":58,"id":"exchange-025"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ご答弁ありがとうあります。厳しい状況というのは、私も確認させていただきました。１年生から９年生までで３０学級のところをさらに増やせるようであれば、もう少し枠を増やすとか、受け入れられるだけの許容数があるので難しい課題ではありますが、引き続き区民の要望が形にできるようにと思いますので、こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"中学校はまだ結果が出ていないと思いますので、それで昨年と比較できれば、それを教えていただきたいと思います。それから、もう一つは、城南小と浜川小は６クラスになる予定になっているのでしょうか。受入れ人数からするとそうなるのですかね、１６４人ですから。そこの確認をさせてください。ごめんなさい。数字のことを言ってしまったかな。","respondent":"柏木学務課長","answer":"浜川小学校につきましても、まだ抽選で、浜川から通学区域外を希望している方の待機の状況がまだ、これからも動きがありますので、現時点で何学級というのはお答えできない状況です。","voiceIndex":62,"id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"確認","question":"数字、細かいのを。事前にお話しすればよかったです。すみません。今年の数字がもし何となく把握できていれば、それも踏まえてお願いします。城南は教室数を確保するために、工事等をしたと思うのです。それと、浜川は新しくなったのですが、仮に６クラスとなったときにでも、きちんと影響なく児童が、教育活動ができるような体制の準備ができているのを確認したいと思います。お願いします。","respondent":"柏木学務課長","answer":"今後の学校選択というか、受入れの関係ですが、就学人口の推計等をしっかり見まして、当然、通学区域の方は受け入れができるという体制のため、普通教室の整備等をきっちり進めていきたいと思います。どうなっていくかというのは、実際の人数を見ながら検討していくところです。","voiceIndex":64,"id":"exchange-028"}]},{"id":"topic-03","title":"令和４年度品川区立学校における体罰等の実態把握","agenda":"令和４年度品川区立学校における体罰等の実態把握","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"こういう体罰等や不適切な指導や行き過ぎた指導というのも、当然、子どもたちの心に大きな影響を与えると思うのですけれども、不適切な指導、行き過ぎた指導が７人、暴言は５人ということでしたが、こういうことをされた児童・生徒へどんな影響があったかとか、あるいは、それに対してどのような手だてを取ったのかとか、ケアをしたのかということは、なかなかこの調査からは分からないところなのでしょうか。","respondent":"中谷指導課長","answer":"このようなことをされたお子さんへの、その後の対応についてのご質問であるかと存じます。禁止行為を教職員が行った場合は、速やかに管理職から当該教職員への指導を行っていきます。","voiceIndex":71,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"すごく未然に防ぐということ、そして、これから根絶するということは大事な取組ですけれども、実際起こってしまったところでの対応というのはすごく大事だと思うので、お願いしたいのですが、今回の報告された１２件での、例えばそれがきっかけで不登校になってしまったとか、そういうところというのはなかったということでいいのか、それとも、そこまでたどり着く調査ではございませんということなのか。","respondent":"中谷指導課長","answer":"ここに待ったなしで取り組んでいくというところかと捉えておりますので、そこは引き続き大事にしてまいりたいと考えています。","voiceIndex":73,"id":"exchange-030"},{"speaker":"吉田副委員長","kind":"質問","question":"調査について伺いたいと思うのですけれども、調査は令和４年１２月５日から１２月２２日までの間に調査をしたということですね。前から少し気になっているのですけれども、調査対象期間は１年間あるわけですよね。","respondent":"中谷指導課長","answer":"つまり、今、取った期間としては１２月ですけれども、年間を通して子どもたちが書きたいと思ったときには書けるという環境に変更をさせていただいたというのがこの令和４年度になっておりまして、これを受けて、回答が。","voiceIndex":76,"id":"exchange-031"},{"speaker":"吉田副委員長","kind":"質問","question":"すごく改善されたと思って、よかったと思います。もちろん不適切指導がないことが大前提ですけれども、やはり子どもたちにとってこれはどうなのだろうかと思うことがあった場合、いつでもこういう訴えることができるということはいいと思います。それとも、何か別の方法で訴えることが用意されているのか、その辺を伺いたいと思います。","respondent":"中谷指導課長","answer":"相談シートという名称で、アンケートのような形になっているのですけれども、こちらの用紙を、学校のほうに任せておりますので、置いてある場所はそれぞれだと思うのですけれども、例えば、教室の中に常時置いてあるような形になっておりまして。","voiceIndex":78,"id":"exchange-032"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"分かりました。それから、相談を受けたことについての、例えば、いじめであれば、すごく以前より改善されて、学校の判断を待たずに教育委員会に事例があったら報告をして、教育委員会として判断をするとなりましたけれども、この不適切指導についても、同じような進化といいますか、より当事者の子どもたちの意見が活かされるような改善がされているのか、その辺があれば伺いたいと思います。","respondent":"中谷指導課長","answer":"ただ、起きてしまったからには、その後の学校としてのフィードバックということが大変重要になっておりますので、やはりその行為を受けてしまったお子さんからしっかり声を聞き、今後それをどのようにして学校の中で。","voiceIndex":80,"id":"exchange-033"},{"speaker":"吉田副委員長","kind":"確認","question":"大学のほうでそうなのであれば、やはり教員としての資格を取得した後に、何か最初にそのようなカリキュラムというのでしょうか、そういう教員として現場に立つためのプログラムというのを、メンタルヘルスケアの仕組みとともにぜひ用意されるべきではないかと思うのですけれども、その点についてもしお答えになれることがあったら、お話を伺いたいと思います。","respondent":"中谷指導課長","answer":"こちらについては、ご自身でしっかり管理をすることも大事ですし、教員の場合ですと、やはり管理職が監督をする中で、例えば、働き過ぎてしまっているような教員に対して声をかけてマネジメントをしていくということも大事だと思いますので、校長に対しては。","voiceIndex":82,"id":"exchange-034"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"これからもまた私のほうも、教員の方からもご意見をいただく機会があると思いますので、その辺のこと、品川区の取組はしっかりお伝えするとともに、やはりなぜそれが現場の皆さんにうまく活用されていないのかということのご意見も伺いながら、私たちとしてもやはりこういう不適切な指導というのが減るように働きかけていきたいと考えていますので、ぜひ指導課長がおっしゃったとおりの制度については。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問","question":"教員の話が出たので、「体罰等」の体罰を行った教員はいないので、懲戒を含めた処分はされていないのかということが１つと、不適切な指導、行き過ぎた指導、また、体罰等の「等」については、そういう懲戒はないのでしょうか。","respondent":"中谷指導課長","answer":"今ご質問いただいた件につきましては、まず、不適切な指導、暴言共に、口頭注意という形で行っております。再び同じことをやった例はないかというところですけれども、同じ教員が同じことをやったという事例はございません。","voiceIndex":86,"id":"exchange-036"}]},{"id":"topic-04","title":"運動部活動の地域移行に係る協議会（第１回）および文化部活動の地域移行に係る協議会（第１回）の報告","agenda":"運動部活動の地域移行に係る協議会（第１回）および文化部活動の地域移行に係る協議会（第１回）の報告","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"現在の確保状況と、あと、現在の指導員の方の身分といいますか、雇用形態といいますか、待遇というのがどうなっているか、改めて伺いたいと思いますし、それと、来年度、民間委託による指導者を加配、拡充するみたいなご説明がありましたけれども、それは見通しが立っているのでしょうか。どのようにして確保するのでしょうかということも伺いたいと思います。伺いたいと思います。","respondent":"中谷指導課長、丸谷教育総合支援センター長","answer":"種目としましては、ホッケーとラグビーに加えまして、ダンスとバドミントンということで、こちらの４種目全て、品川区の教育委員会として、合同部活ということで。部活動指導員の身分ということですけれども、こちら、会計年度任用職員として任用を行っているものです。","voiceIndex":92,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"どの部活にするかというのは決めていないにしてもということで、かなり相当多く動くのではないかと思うのですが、やはりこちらの資料にも、現在の活動は守ってほしいみたいな、生徒会長のヒアリングの中でも、「今活動している団体の機会を奪わないようにしてほしい」などの声もありますが、やはり早急に進めるというよりは、きちんと声を聞きながら進めていく必要があると思いますので。","respondent":"中谷指導課長","answer":"それぞれが今併存しているような状況でございまして、目指すところとしましては、今、学校の部活動にあるものについては、地域の指導者の方にお力をいただきながら少しずつ移行していくこと、そして、一方で、地域の中に学校の部活動にはなかったようなものですとか。","voiceIndex":95,"id":"exchange-038"},{"speaker":"ゆきた委員","kind":"質問","question":"１点、お聞きしたいと思います。参考資料の２ページのところの図面が書いてあるところで、スポーツ協会、民間業者に委託される地域部活動は、令和６年度・令和７年度の図を見ると、シーズン部活となっていますが、こちら、年間を通して継続してやっていけるものにはならないのかと感じたのですけれども、この件についてお聞きできればと思います。","respondent":"中谷指導課長","answer":"というのも、例えば、ラグビーを最初に今年度開始したのですけれども、こちらに参加されるお子さんには、学校部活動のほうにあまり頻繁に所属されていなくて、今こういったご案内が来たのでやってみたいと思って入ったというようなお子さんがいらっしゃったりしまして。","voiceIndex":98,"id":"exchange-039"},{"speaker":"ゆきた委員","kind":"意見","question":"部活動となると、私の古い感覚になると、みんなで汗をかいて、毎日部活をやって、年間通してやっていくというのは、古い感覚かもしれないのですけれども、そういうイメージがあるのですが、やはり時代も変わってくる中で、ニーズといったものに寄り添ったものになるのが一番だと思いますので、ヒアリング等を継続してやっていきながら、そのニーズに合った形になるようにできればと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-040"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そういうのにはこういった、合同部活もそうなのだけれども、大会への出場への弊害というのはないのか確認したいのと、４ページのアンケートの中で、第１位にｅスポーツが挙げられているのですけれども、資料の説明、私が聞き漏れていたらあれなのですけれども、見ていると、ｅスポーツというのは一切出てこないわけですよね。この子たちの思いというのはどこに行ってしまったかというのを教えていただきたい。","respondent":"中谷指導課長","answer":"２つ目のｅスポーツの件ですけれども、民間委託の導入に関しては、まず、令和６年度から行う学校に民間委託をどう導入していくかといったところの検証を行いたかったため、ご覧いただいているとおり、学校に今現存している部活動をあえて選択したという経緯があります。","voiceIndex":102,"id":"exchange-041"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"分かりました。研究していきましょう。子どもたちはやりたいと言っていて、条件は整ったので、あとは教育委員会が覚悟を持って決断をして実行するかどうかだけだと思うので、これは要望にとどめておきますけれども、ぜひ研究という意味では、私はトライしていってもいいのかと思うので、そういった意味も含めて検討をしていただければと思いますので、よろしくお願いします。","respondent":"中谷指導課長","answer":"把握している情報として、私立学校で今ｅスポーツ部活というのはございまして、こちらの動向はきちんと把握していきたいと思います。","voiceIndex":106,"id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それはそれで、五中は部活動として残しておいて、サイドスポーツと書いてありますが、そこが五中にいらっしゃる、ほかの部活動でやっているのだけれども、バトミントンで地域の部活に入りたいという方も当然いると思うのだけれども、五中のことに関して言えば、五中は部活動としてやっていただきたいと思っているのですが、その辺、検証含めて、分かっていることをお知らせいただければと思います。","respondent":"中谷指導課長","answer":"というのも、おっしゃっていただいたとおり、各学校において学校の部活動としてバドミントン部を運営されるというところが多いですので、まず、民間委託をやっていくノウハウを今検証していますので、それを今年度中にしっかりやり切った上で。","voiceIndex":109,"id":"exchange-043"}]},{"id":"topic-05","title":"品川区いじめ防止対策推進基本方針の改訂","agenda":"品川区いじめ防止対策推進基本方針の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"なのですけれども、基本的に、条例を品川区もつくりましたけれども、条例のときの、大分前になりますが、そこでもいろいろ意見を言わせてもらった経緯はありますが、いじめ根絶という、禁止というのですか、そういう発想というのは、やはり限界があるのではないかというか、それで禁止をする、禁止ですと言ったからといって、なくなるものではないと思いますし、根絶というところが。","respondent":"丸谷教育総合支援センター長","answer":"いじめの禁止というところですけれども、法律にも「児童等はいじめを行ってはならない」という記載がございまして、いじめはあってはならない、禁止するものだということで、基本方針でもうたっているところです。","voiceIndex":121,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"いじめというのはそもそもこういうものだということをふだんから考えておくということはすごく重要なのですけれども、それにとどまらず、いじめなんていうことを考える、そんな必要ないよというような、学校が楽しい、学びたいというような、もっと大きなところでの防止の視点ということも重要なのではないかという意味で言っているのですが、先ほどの質問なのですけれども。","respondent":"丸谷教育総合支援センター長","answer":"新旧対照表の５ページをご覧いただきますと、アのいじめの未然防止と書かれた項目があります。ここにも赤字で幾つか追記をしておりまして、「いじめに関する授業」を意図的・計画的に年３回以上実施する。","voiceIndex":123,"id":"exchange-045"},{"speaker":"ゆきた委員","kind":"質問","question":"何も更衣室に監視カメラをつけるとか、そういったことではないので、このいじめというのも、複数なのか１人なのかというところも、いじめも陰湿になってきているので、そういったところの対策というか、必要があれば、こういういじめに対して、監視カメラを必要に応じてつけるとか、そういったところも明記すべきではないのかと思いましたので、こちらについてもお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"加害者の特定のための監視カメラ、防犯カメラの設置というところについてですけれども、基本方針の中でも、関係機関と連携した対応というところで、警察というところも含めた記載をしています。","voiceIndex":126,"id":"exchange-046"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"法律というのは恐ろしいというところが私も感じているのですけれども、受け止め方とか解釈の仕方で、なし崩し的に変わっていってしまうようなところがあるので、こういったところで、さらに追って改善とか検討をしながら、よりよいものをつくっていっていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-047"},{"speaker":"石田（し）委員","kind":"提案","question":"委員長に提案なのですけれども、今やっているのと、この次のいじめの重大事態の発生と、所管事務調査のいじめ対策で、かぶってくるところがあると思うのです。なので、もし可能だったら、これ、議案とかではないので、一括で説明を受けて、質疑もまとめて所管事務調査のところでやれれば、かぶらないかと思うのですけれども、いかがでしょうか。すみません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":130,"id":"exchange-048"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"教育委員会で議論したのか。その内容については、どういうものを参考にというか、どういう議論を行ってこういうふうになったのかという、そこら辺をちょっとお伺いしたいなと思いました。過程ですね。改訂案の決定過程というのをお伺いしたいということです。今年度だけで８件ということですが、残りの５事案というのは、調査の終了のめどというのですか。現在どうなっているのかというのをお伺いします。","respondent":"丸谷教育総合支援センター長","answer":"それを教育委員会にも諮りながら、一度検討していただいてご意見をいただいて、１２月１２日に了承を得たという流れで決定しております。重大事態のおおよその一事案に係る調査の期間ですが、目標としては、諮問から答申までに三、四か月を目標としております。","voiceIndex":141,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"これは法の規定などがあるのか。ちょっとすみません、勉強不足ですが、どういった手続をしているのか、必要になってくるのかということをお伺いしたいと思います。そこからどうするかというのはいろいろあるかもしれませんが、それは最低限やる必要があると思いますが、そこら辺については、ちょっと文教委員会としてなのか、議会としてなのか分かりませんが、現教育長のお考え方も伺えればと思います。","respondent":"丸谷教育総合支援センター長","answer":"当時の責任者というところのご意見ですが、教育委員会組織で対応しておりますので、この事案、それ以降に起こった事案につきましても、組織として丁寧に対応していきたいと考えております。","voiceIndex":143,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"システムづくりというのであれば、少なくとも中学校は４０人学級のままなわけですが、品川区として独自教員を雇っているわけですから、３５人学級というのを直ちに広げるべきだと思いますが、それはいかがでしょうか。伺います。","respondent":"丸谷教育総合支援センター長","answer":"今後の取り組みの2)番のところに、「１人１台端末を活用した科学的根拠に基づく調査」と記載しています。登校した児童・生徒のその日の調子を朝、簡単なアンケートを取って、学級全体の様子がデータで分かるような取組を現在検討しています。","voiceIndex":145,"id":"exchange-051"},{"speaker":"安藤委員","kind":"提案","question":"やはり私が提案したいのは、本当に子どもたちをしっかり見られるという体制を、きちんと教育環境整備ということでは、やはり教育委員会が責任であるわけですから、３５人学級を少なくとも中学校まで広げるべきなのではないかと思いますが、そちらについてはどうでしょうか。いじめ根絶、いじめ解決できる学校づくりのうえでも必要だと思いますが、いかがでしょうかと改めて伺います。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"区採用の教員につきましては、あくまでも品川区の教育の中心的な担い手のために雇用しているものですので、いわゆる３５人学級で少人数学級の実施のための雇用ではございません。１人１台端末を活用した科学的根拠に基づく調査というところです。これまでのアンケートは、紙で丸をつけて、手作業で集計して、何かそこで気づいたところを教員が見て対応していくというようなことは繰り返し行ってまいりました。","voiceIndex":147,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"最後の最後になってしまうのですが、この右下のところ、今後の取り組みのところでもう一点だけ伺います。３段階の研修とあります。この研修の内容をざっくり、こんな感じの３段階というのが、全教員向けとリーダー教員向けと専門家向け、それぞれどのような研修を考えているのか、伺いたい。情報の一元管理というのは、具体的にはどういうことなのか、どういうふうにやるのか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"基礎的なところを学ぶものです。リーダー教員向けというのは、学校管理職や生活指導主任、養護教諭等、いじめの相談を受けたり対応したり指示を出したりといった教員向けの研修を考えております。","voiceIndex":150,"id":"exchange-053"},{"speaker":"石田（し）委員","kind":"質問","question":"何点かお伺いします。所管事務調査のいじめ対策についての資料の中で、品川区いじめ対策委員会、品川区いじめ根絶協議会、区長部局と連携のところでいじめ対策協議会と、幾つか委員会や協議会が設置されています。これは常設の会議体なのか、何かあったときに設置される会議体なのか、お聞かせください。そこをお願いします。","respondent":"丸谷教育総合支援センター長","answer":"いずれの組織も常設のものになってあります。","voiceIndex":153,"id":"exchange-054"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"現状の課題で３点掲げられていて、今後の取り組みで、その解決に向けて取り組んでいくのだと思いますが、まず、この1)番の学校風土と言っていますが、僕は、例えばいじめは駄目などというのはもう結構限界に来ていて、スローガンというかキャッチコピーというか。言葉では出ていますが、もうちょっと具体的に、どういう感じで組み込んでいくのか。もしあれば、教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"いじめを発見したら、まずは学校いじめ対策委員会にかけるのだということを、これも繰り返し繰り返し学校には伝えているところです。組織的な対応をすることが何より大切だと思いますので、引き続き努めていきたいと考えております。","voiceIndex":155,"id":"exchange-055"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"品川区も例えばヤングケアラーで今、体験者の方たちに実際、取り組んでいただいて、推進していこうというのもあるではないですか。なぜ僕が一歩踏み込んだ文言を言ったらいいのではないかというのは、実は視察に行ったとき、寝屋川でしたか。これは要望で終わりますので、ぜひ引き続き取り組んでいただければと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-056"},{"speaker":"ゆきた委員","kind":"質問","question":"所管事務調査のところからお聞きしたいのですけれども、まず目安箱について、「全校設置」と載っていますが、目安箱は学校のどこに設置されているか、教えていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"各学校の各学年の教室があるフロアに１つずつ設置しているというのが基本となっています。ただ、あまり目立つところに置くと投函しているところが見えてしまうというのもあるので、少し離れたところや少し陰になっているところに置いてある学校が多いかなです。","voiceIndex":159,"id":"exchange-057"},{"speaker":"ゆきた委員","kind":"質問","question":"もちろん相談のツールとしては、ここに書かれているまもるっちや、タブレット、アイシグナルもありますが、いじめの抑止力といったところでは、機能としてはどうしても弱いのではないかなと感じます。この抑止力という観点で、今後、品川区で何か取組とか考えなどがあれば、教えていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"攻めの情報収集ということがありました。教育委員会として今考えているのは、１人１台端末を使った子どもの観察といったものは今後も進めていく予定です。複数の相談窓口があるということの情報発信というのは、定期的に行っていこうと思っています。","voiceIndex":161,"id":"exchange-058"},{"speaker":"ゆきた委員","kind":"提案","question":"今確認させていただきまして、やはり視覚的なところの抑止力とか、先ほどもあったとおり、いじめは罪だと。いじめは犯罪で、いじめは恥だという風土をつくり上げていくことが大事だと思います。具体的に提案というのはちょっとできていませんが、そういったところでさらに検討していただければなと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-059"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこで、委員会の委員長は管理職の方がなるのか、それとも生活指導の主任の方がなるのかということと、今ちょっとルーチンみたいな話をしましたが、これは今まで生活指導の部というか、そういうことが起きたときに、これとこれとこれはみたいな形でやっていたのを明文化したのでしょうか。今回様々なことがあって、区長部局との連携が課題の一つではあったわけですから、そこは、なぜそれが載っていないのか。","respondent":"丸谷教育総合支援センター長","answer":"区長部局との連携が基本方針に盛り込まれていないのは、これは５月から改訂作業を進めておりまして今この時期になっておりますが、区長部局の組織の体制がまだ見えていない中での改訂でしたので、今回については載せていませんが、今後区長部局との連携も入ってきますので。","voiceIndex":165,"id":"exchange-060"},{"speaker":"高橋（し）委員","kind":"質問","question":"学校いじめ対策委員会の構成が分かりました。ただ、このメンバーの方々は、ほかの部門部署でも大変忙しい部分があります。一方の区長部局のほうです。区長部局のほうから、相当今、体制が整って出ていますから、そうすると、近々区長部局との関係については、再改訂ではないですが追加が行われると受け取ってよろしいでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"そのとおりです。区長部局との連携については、再改訂という形で追記していくつもりです。","voiceIndex":167,"id":"exchange-061"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"最初に基本方針の改訂の文言について伺いたいです。先ほど石田しんご委員からもありましたが、一般的にはもう言われていると思うのです。のほうの具体的な事例などを見ると、明らかにこれは犯罪行為です。一般社会に出れば、これはもう逮捕・起訴される行為に当たるよということをきちんと言っていただきたいと思います。そのことを伺いたいと思います。その辺についても伺いたいと思います。お願いします。","respondent":"丸谷教育総合支援センター長","answer":"区長部局との連携についてですが、今後基本方針をさらに改訂していく中で、必要な事項を盛り込んでいくことになると思います。法律の専門家も今後加わるというお話も伺っていますので、そうした観点からも、いじめへの対処について記述されるものと考えております。","voiceIndex":170,"id":"exchange-062"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"これは要望しておきます。その辺は、現場の先生や生徒たちと議論した中で、どういうところだったら利用しやすいかねというような。そんな事例が起きないのが一番ですが、でもやはり現に起きているわけで、それで目安箱がそういうときは活用されるべきだと思いますので、どういう設置の仕方がいいかということについても、ぜひ意見交換などをしながら、では、うちの学校はこういう形にしようねと。","respondent":"丸谷教育総合支援センター長","answer":"目安箱の設置箇所についてです。もう１０年ほど前になるかと思いますが、それぞれ学校が設置するときに、どの場所であれば子どもたちが周りを気にせず入れられるか。そういったものを各学校がしっかりと検討したうえで決めているものだと捉えております。","voiceIndex":172,"id":"exchange-063"},{"speaker":"吉田副委員長","kind":"提案","question":"目安箱に関しては、私が議員になる前の生活者ネットワークの議員が、個別に入れているの見られると、あ、何か言うんだと思われるから、もう週１回、全員この日は白紙でもいいから入れるという日をつくったらどうかという提案をさせていただいたと考えています。これは要望にとどめます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":174,"id":"exchange-064"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"所管事務調査のいじめ対策についてです。現状の課題で、3)のいじめ予防に関して、教職員の対応力の向上。これはもう本当に重要だと思います。今後の取り組みで、3)の段階に応じた教職員の研修。これから異動の時期になるわけではないですか。転入・転出もあります。新任の意欲のある若い先生も入区してくるわけであります。今後、どう考えておられるのかというのをお聞かせいただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"転出・転入ですが、毎年人事異動がありますので、まず転入された先生方には、品川区の教育の中で、品川区のいじめ対策についてきちんと４月当初に説明してまいります。","voiceIndex":176,"id":"exchange-065"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今までもそういう研修等はあったと思ったのですが、今回は特別ないろいろな案件がありましたので、今まで以上に新任の先生には対策を講じていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-066"},{"speaker":"吉田副委員長","kind":"提案","question":"すみません、１点だけ。今、センター長のお話を伺いながら思い出したことがあります。あっという間にみんなから、そうだ、あいつはいじめをするやつだという感じで、いじめられる側に回ってしまった事例を伺いました。これは、別に提案も何もないのです。これは本当にふと過去の事例を思い出してしまって、ご報告だけさせていただこうと思ったことですので、ご連絡にとどめておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":182,"id":"exchange-067"}]},{"id":"topic-07","title":"令和６年度品川区立学校における土曜授業の実施","agenda":"令和６年度品川区立学校における土曜授業の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"年８回にして、来年度で３年目に入るというわけですが、この間、土曜授業実施を減らしたら、子どもや保護者あるいは地域からの反応というのはどんな感じでしょうか。私は減らしてよかったのではないかなと思っていますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"教職員につきましても、土曜授業の回数が減ったことで、働き方改革も含めて進んだというお話は伺っているところです。","voiceIndex":187,"id":"exchange-068"}]},{"id":"topic-08","title":"子ども・若者活動拠点の整備","agenda":"子ども・若者活動拠点の整備","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料についていろいろお伺いしたいのですが、ワークショップが行われておりますが、それぞれ児童センター利用者、フリースペースワークショップですが、開催回数、参加人数、参加者構成等について伺いたいと思います。ちょっとそこら辺が分からなかったので伺いたいと思います。現在の子ども若者応援フリースペースはこちらに移ってくるということなのか、お伺いしたいと思います。お願いします。","respondent":"藤村子ども育成課長","answer":"基本構想の案の報告があるかというところです。基本構想については今年度中に作成したいと考えておりますが、どのタイミングで報告できるかというところがありますので、進捗状況を踏まえて、また検討したいと思います。","voiceIndex":194,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっといろいろタイミングがあると思うのですが、子ども・若者まんなか拠点と言われても、今の時点ではちょっと方向性しか分からないので、意見を言いようがないというのもあるので、ぜひ案の段階での報告をお願いしたいと思います。こちらは何回で何人ぐらいだったのかというのをお伺いします。こちらは要望したいと思います。質問のほう、よろしくお願いいたします。","respondent":"藤村子ども育成課長","answer":"フリースペースのワークショップは１回実施しておりまして、こちらは参加者１２名でした。","voiceIndex":196,"id":"exchange-070"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"今、安藤委員からもありましたが、専門性の高いスタッフを配置とあります。これは要望としてあるので必要だと思いますが、これだけでなく、やはり同じ若者が受け入れる側として寄り添っていけるような体制も必要ではないかと感じています。品川区でも、こういった施設の運営として人の魅力の発信という仕組みづくりといったところで、この辺についてお考えがあれば、お聞きできればと思います。","respondent":"藤村子ども育成課長","answer":"ユースワーカーといった形で乳幼児から青少年まで全てカバーできる人や、乳幼児担当の方と青少年担当の方といった形で寄り添って対応できる方を配置したいと考えています。例えば職員を置きつつ委託を置くなどいろいろな方法があると思いますので、様々検討したいと考えています。","voiceIndex":199,"id":"exchange-071"},{"speaker":"ゆきた委員","kind":"意見","question":"先ほど申し上げたところで、この発信についてです。若者がホームページを見て、この人だったら話してみようかなといったきっかけづくりになるような発信もぜひ検討していただければと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":201,"id":"exchange-072"},{"speaker":"石田（し）委員","kind":"提案","question":"１点だけ。特にやはり人。そこはぜひそういう選定をしていただきたいなと思います。何をもってリスタートと言っているのか。「夢を描け、リスタートするため」と書いてあるので、以前も提案していますが、例えば伝統工芸をやられている方たちで、弟子を受け入れるのに、今、自分たちで抱えて、弟子にするのは難しい。ここで言っている区内企業との連携というのはどういうことなのか、お知らせください。","respondent":"藤村子ども育成課長","answer":"東大井児童センターで今ものづくり館というコンセプトでやっているところがありますので、伝統工芸というくくりですと、東大井の取組をもうちょっと強化して、子どもたちに伝統工芸のことを見ていただいて、興味を持っていただくような取組もできればいいかなと考えています。","voiceIndex":203,"id":"exchange-073"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それはもうぜひこういった拠点をつくる際には、そういうのを検討していただきながら進めていただきたいなと思います。そういったものも含めて、誰もが輝けるというのであれば、僕はそういった部分に関して、積極的に少し力を入れていただきたいなと思います。こういった施設ができるときには、ぜひそういったところに力を入れながら進めていただきたいなと。これは要望で終わりますが、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-074"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"いろいろな若者と子どもと両方の集まれる場所を検討されているということで、難しいだろうなと思いつつ、ぜひ実現していただきたいと思います。外だと難しいなと思いつつ、こういうことが既にもう検討が始まっているのか。あくまでこれはワークショップで出た意見を羅列しただけだよということなのか。その点について伺いたいと思います。把握されていることがあったら伺いたいです。","respondent":"藤村子ども育成課長","answer":"まだ検討の最中ですが、何かしらご用意できればと考えています。女性も通いやすい工夫というところです。今お話がありましたが、子ども若者応援フリースペースには、オハナルームといって女の子だけが入れるような部屋を準備しております。","voiceIndex":207,"id":"exchange-075"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"希望はすごくたくさん出てくると思います。これは南品川なので、報告会で出たご意見は、荏原地域に何とかならないかというご意見だったので、ちょっとそのご意見の実現にはなりませんが、やはりバスケ、バレー、ボールを使ったスポーツというか遊びができる場所ということでは、ぜひ引き続きそういう機能を持たせていただきたいです。女性もという、ちょっと若干抵抗が。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-076"}]},{"id":"topic-09","title":"令和６年度 私立保育園および幼稚園の設置等","agenda":"令和６年度 私立保育園および幼稚園の設置等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２ページから３ページと４ページの(8)の設置者の変更ですが、こちらは、変更によって保育のサービスが変わるところはあるのかということと、保護者への説明というのはどのようにしたのでしょうか。これからなのか。そこら辺をお伺いしたいというのが１つです。転園先については心配ありませんということでしたが、どんな感じで手を打ったのかというのをちょっとお伺いしたいと思います。","respondent":"石井保育支援課長","answer":"続きまして小規模保育園についての行き先ですが、この間、保護者等への説明などを行いまして、例えば転園については２点加点による転園ですとか、あとは受入先の調整支援ということで、近隣の私立保育園といったところと協議しまして。","voiceIndex":214,"id":"exchange-077"},{"speaker":"安藤委員","kind":"質問","question":"廃止というところの４つの園ですが、今の小規模等も含めて、廃止の理由というのですか。戸越幼稚園は後継者という話もありましたが、戸越幼稚園とがくどうえんが元いたところというのが、例の２９号線の道路事業にかかっているところだと思いますが、そういうところとの関係はなかったのか、伺いたいと思います。","respondent":"石井保育支援課長","answer":"戸越幼稚園に関しては、現在の幼稚園の園長のお父さんの代からスタートしているところではありましたが、やはり次がいないという相談があったので、こちらも補助２９号線に関連してということではございません。","voiceIndex":216,"id":"exchange-078"},{"speaker":"安藤委員","kind":"確認","question":"ありがとうございました。戸越幼稚園は、では、東京都から、道路用地なので買いますけれど、売ってくださいという話は来ていないということでよろしいのでしょうか。そこを再度確認させてください。","respondent":"石井保育支援課長","answer":"私のところに来た相談というものは、あくまでも代替わりということです。例えば補助２９号線に伴う用地交渉の件につきましては、私のほうに相談が来ているものではございませんので、詳細については把握してはおりません。","voiceIndex":218,"id":"exchange-079"}]},{"id":"topic-10","title":"行政視察報告書","agenda":"行政視察報告書","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"やはりこの成果をぜひ活かすためにも、調査報告書の区議会ホームページへのネットアップということを、ちょっと委員長としても、ぜひ議長や議運委員長などに、こちらにいらっしゃいますけれど、検討してほしいとお申入れをしていただきたいと思うのですが、ぜひよろしくお願いしたいと。ほかの委員会の説明もあります。ぜひ委員長として、申し入れていただきたいと思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":223,"id":"exchange-080"}]},{"id":"topic-11","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"これは、文教委員は見学はできるのかということと、全国連絡協議会というのは、会員は何自治体あるのか教えてください。","respondent":"中谷指導課長","answer":"見学に関しましてはもちろん可能ですので、お声かけいただければと存じます。小中一貫教育全国連絡協議会の正会員が、まず５３。そして賛助会員が団体と個人とありますが２１。合わせて７４。昨年の１１月２０日現在ですが、そのような数となっております。","voiceIndex":230,"id":"exchange-081"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません。なぜ読めないか。数学が４とか３、理科が５とか書いてありますが、フォントが大きいので読み取れない。ですからアスタリスクになってしまう。これは数年前から導入された仕組みですが、ほかの教育委員会は改善して、フォントを直して、高校がスキャンできるようになったのですが、品川区がなぜか直っていなかったという話があります。それはどうして起きたのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"その中で我々も校務システムで出力しているわけですが、今後うまく都立高校との連携を進められるように、都教委とも連携しながら、フォントの種類やサイズといったものはそろえるように、システムとも連携していきたいと考えているところです。","voiceIndex":237,"id":"exchange-082"},{"speaker":"高橋（し）委員","kind":"確認","question":"そうすると、品川区の中学生の調査書だけが、都立高校の全受験校で担当の教員が手入力しているという現実があります。今お話がありましたが、品川区教育委員会は、今年初めてそのフォントはスキャンできないということを聞いたというところをちょっと確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"昨年度は、そういったお話はセンターとしては把握しておりません。本年度はそういうことがあったということで、都立高校から品川区のは読み込めないというお話をいただいたところです。","voiceIndex":239,"id":"exchange-083"},{"speaker":"高橋（し）委員","kind":"質問","question":"分かりました。ということは、２月の一般入試はもっと数が多くて、たくさんの受験生がいるのを、都立高校の教員が全て手入力しなければいけないという。直せないならばです。一般入試に間に合わないでしょうか。間に合わないとそうなってしまうのですが、そこのところはいかがですか。","respondent":"丸谷教育総合支援センター長","answer":"現状ちょっと間に合うかどうかというところは、まだはっきりとこの場では申し上げられないのですが、もし間に合えばそのような対応をしたいと思います。","voiceIndex":241,"id":"exchange-084"},{"speaker":"高橋（し）委員","kind":"意見","question":"品川区の教育委員会として、全都立高校にそういうことになってしまったので、どこを気をつけてどうすればいいかは、ちょっと仕組みが分かっていないので、そこをしっかりしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":243,"id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5120#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":81741,"voices":244}},{"id":"r06-20240122-5","meetingId":"r06-cm01","date":"2024年1月22日","dateIso":"2024-01-22","committee":"総務委員会","time":"午後 １時００分～午後 ５時０７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"先ほど申し上げたとおり取り上げる順番を変更して、初めに、(2)区民アンケート","agenda":"先ほど申し上げたとおり取り上げる順番を変更して、初めに、(2)区民アンケート","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"それと、この集計データですけれども、個人であれ、研究者であれ、大学であれ、自分なりに何か分析をしたりとか、エクセル上に入っているものなのかどうか、どういうものなのかも併せてご説明ください。羽田新ルートについては全区民的に関心はあるものの、年齢ごとでも何か特徴が見えてくるものがあるのかなと思ったのですが、その年齢とか年代ごとの分析の公表についてのお考えを伺いたいと思います。","respondent":"辻広報広聴課長","answer":"３点ご質問いただきました。１点目の自由記述の公表についてですが、委員ご指摘のとおり、個人情報や人を誹謗中傷するようなものを除きまして、全て公表する予定です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"澤田委員","kind":"質問・要望","question":"それともう一点は、区民アンケートの定期的な継続をしてほしいという要望もこのアンケートの回答の中にあったのですけれども、今後、また行う予定もあるのかなとは思うのですが、例えば頻度などをどのようにお考えなのかも、併せてお聞かせいただければと思います。","respondent":"辻広報広聴課長","answer":"例えば今回は郵送して、郵送かインターネットで回答というようなことで、経費もたくさんかかってしまいましたけれども、その他のいろいろな手法を研究しながら、区民の意見をまた集めるような方法というのは引き続き考えていきたいと思っています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"澤田委員","kind":"質問","question":"ということは費用面もありますし、定期的にやっていくわけではないけれども、また必要であればやっていくという、ただ、定期的にはやっていかないということですね。もう一つのリマインドをしていたというのは、世論調査のほうがリマインドをされていたのですか。例えば今後の区民アンケートでも、またそういう手法などを取り入れていただけたらいいのかなと思うのですが、いかがでしょうか。","respondent":"辻広報広聴課長","answer":"そうですね。費用面と費用対効果、様々なことを考えながら、多くの方からご意見をいただけるような手法を考えていきたいと思います。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"これだけのことにやはり関心を持ってもらって、今、これだけ時代がどんどん変わっている時期なので、本当に１年に一回でも、大変だと思いますけれども、こういうアンケート調査をしていただいて、区民の意見を聞いて、そして区政に関心を持っていただくというようなことを今後も続けてほしいと私は思います。もう一つ、自由意見については、これはまとめるのが大変ですね。","respondent":"辻広報広聴課長","answer":"先ほど申し上げましたとおり、費用面と、意見をたくさんいただけたらいただけたほど、私どもはうれしい反面、それを１件ずつ目検で見ないと、個人情報だとかそういったことが出ているといけないので、時間がかかってしまうところがありますので、そうとは言え。","voiceIndex":11,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"今日は副区長もいらっしゃいます。企画課、財政課の理事者の皆さんもいらっしゃいますので、ぜひ、区政に関心を持っていただけるように、私は様々工夫をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"意見","question":"これでいいです。それで、区長も国土交通大臣まで行った。それでこれからどうするのだということだと思うのです。だから、それは固定化回避検討会も含めて、行政側がしっかりそれは踏まえた中でお金をかけてやったのだから、どうやってフォローしていきますよということぐらいは言ってくれないと、と思っているので、そこら辺は何か一つだけでも聞きたいです。","respondent":"辻広報広聴課長","answer":"それ以外の意見についても、来年度の予算ですとか位置づけはまた各所管のほうに戻して、今後の施策の参考にしていくというふうに考えておりますので、これを取って終わりとかそういうことではなく、今後に生かす生きたデータとして、活用していきたいと考えています。","voiceIndex":14,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"お願いだけしておきます。これはしっかりと費用もかけて区民アンケートでしっかりご意見を伺った。この手法は手法として、それを選択したということであって、国土交通大臣にも行ったということだと思っています。それぐらいまでは来ているわけじゃないですか。けれども、極端なことを言えば、それほど聞いてくれていないわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"}]},{"id":"topic-02","title":"請求書等の押印省略","agenda":"請求書等の押印省略","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ。今回、押印の省略についてということで、こうした取組みを今後も進めていく必要があるのかなとは思っています。２３区の動きがどうかということと、あと品川区は区民と事業者との関係で今説明がありましたけれども、当然東京都だったり国との契約や、様々請求もあるわけで、そこでの取扱いは現状どうなのかということと、今後どのように考えているのかもご説明いただきたいと思います。","respondent":"大串会計管理者","answer":"ただ、今後もその流れはどんどん増えていくだろうということです。それから、都あるいは国との関係ですが、やはりそこはまだまだ公印を使ってやっているというのが現状です。ただ、これも徐々に変更・変化していくものと考えているところです。","voiceIndex":22,"id":"exchange-008"},{"speaker":"須貝委員","kind":"確認","question":"確認ですが、必ずどなたかが作成して、請求書か納品書か分かりませんけれども、そういうことをやるときに、押印することによって責任が誰だというふうに確定されるわけですね。それは今後、押印はしなくても、誰がこれを了解したのか、請求書を作ったのかというのは分かるようになっているのでしょうか。それだけお願いいたします。","respondent":"大串会計管理者","answer":"それをもって押印を省略します。もう一方、法人の場合につきましては、基本的には契約書に基づいての請求になりますので、そうした中においては、ここでも例外としてということで２番の2)に書かせていただきましたけれども、書類発行責任者等の記載ということを求めしています。","voiceIndex":24,"id":"exchange-009"}]},{"id":"topic-03","title":"「公共施設等総合計画改定（素案）」にかかるパブリックコメントの実施","agenda":"「公共施設等総合計画改定（素案）」にかかるパブリックコメントの実施","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"児童センターと区営住宅について伺いたいのですが、児童センターについては、ネウボラ相談機能の充実や多世代が交流できる施設への転用なども含めて検討しますと、今後のあり方の方針が示されておりますけれども、現在児童センターは資料によると２４か所ということですけれども、この施設については今後も同じか、それについて伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"こちらの計画は、全体計画あるいは個別の施設の計画のあり方をまとめさせていただいているものですけれども、先ほど統廃合というお話がございましたが、今後の人口動向、あるいは施設の老朽化状態、そういったものを含めまして、全体的に検討する事項だと考えております。","voiceIndex":31,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"質問は、区営住宅の部屋の数、戸数を減らす考えがあるのかということを伺いたいと思います。もちろん私は増やすべきだということをさんざん言っているわけですけれども、ここで言っている集約化・複合化によって、建物の数は変わるかもしれないけれども、部屋の戸数は従来どおり減らす考えはない、変える考えはないということでいいのか、ここだけ伺いたいと思います。","respondent":"せりざわ委員長、吉岡政策推進担当課長","answer":"総合計画なので、各課からおまとめいただいて今出ていると思うので、大分細かい議論になってきていますから、それは答えられないと思います。区営住宅というところで、戸数のところは当然触れてございませんで、先ほど申し上げたとおり、人口動向等、全体のバランスを鑑みながらそこは検討していくということで考えているところです。","voiceIndex":33,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"１つだけ。ましてや集約化・複合化という名目で戸数を減らすなどということはあってはならないし、能登の地震を見ても、今度品川区も公営住宅で１０戸ほど協力するという発表がありましたけれども、災害時にも役割を発揮する施設でありますので、重要な施設だと引き続き位置づけていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"なぜ総務省の通知によって、各自治体が、品川区が、またわざわざ検討しなくてはいけないのか。各自治体、品川区は品川区でやっているわけで、国は品川区のことなど分からないのに、このような通知をなぜ自治体に出す意味があるのでしょうか。それを教えてください。","respondent":"吉岡政策推進担当課長","answer":"品川区が前回作ったのは平成２９年度ということで、この後、区のほうでも長期基本計画、総合実施計画、新しい人口動向のほうも出させていただいておりまして、この間より大きく伸びているというところをお示しさせていただいているところです。","voiceIndex":37,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"いや、そうではなくて、各自治体で、品川区は品川区でこういう基本計画を作って、施設もこうして改修なりまたは新たに造っていくという方針をきちんと立てられてこれだけできているではないですか。なぜわざわざ総務省が品川区にこのようなことを言ってくるのか、また言わなくてはいけないのか。言われっ放しでいいのか。私はこれはおかしいと思うのです。","respondent":"吉岡政策推進担当課長","answer":"今まで、こういったもともと品川区のほうが平成２９年度に立てました総合計画につきましては、他の自治体でも作っているところですけれども、やはり同じぐらい年数が経過いたしまして、なかなかそういった個別施設計画との整合性が図れていないですとか。","voiceIndex":39,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっと今質問と答弁が合っていないのであれですけれども、私が言うのは、質問はしませんけれども、やはり総務省がよその自治体に口を出すというのは変な話だし、品川区は品川区で独自でこれだけのものを書いてきちんと計画を立てているのに、なぜこのようなことを言ってくるのだと。このように通知をよこすなら、その分それなりの財源もくださいと言っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"品川区の公共施設の延床面積は基本的には増えているというところは、７ページのところで累計延床面積がどんどん増えているところがある。少子高齢化というのはどこの自治体も同じ問題を抱えている。私個人としては、やはり今、どんどん増えている。その観点から、今回の計画をまとめていくにあたって、区としてこの延床面積という点からはどのように考えていらっしゃるのか伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"目標という数値を何か持っているところではございませんけれども、今後の人口動態も含めまして、１人当たりのこういった面積というところは、一つ基準になるのだろうと捉えているところです。","voiceIndex":42,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問・要望","question":"なかなかこれ、目標を立てるのは難しいとは思うのですけれども、例えば今のお話であった人口との関係では、１人当たりの面積である程度どこかでキャップをはめるとか、そういったことも具体的に検討していかなければ、やはりもう我々区民というのはどうしても要望する側なので、どんどん要望するとむしろ増やせ、増やせという方向に行きがちですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ。これはこれで品川区公共施設等総合計画改定（素案）だけれども、長期基本計画があったりいろいろなものがあるじゃないですか。その中で実施計画もいろいろある。例えば一番いい例は、障害者のグループホームができてやろうやろうと言うけれども、現実はできないのです。その考え方をもう少し、少しずつ出すようにしてほしいというのがあるのだけれども。それはちょっとどうかという感じです。","respondent":"吉岡政策推進担当課長","answer":"こちらの公共施設等総合計画につきましては、あるいはその施設を考える上でも一番の上位の計画とは考えてありますけれども、個別の施設の計画があったりですとか、あるいは施設のあり方方針といったものも個別に存在するようなところでございまして。","voiceIndex":45,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"なぜこのようなことを言うかというと、区の思いというのがあるでしょう。後で能登の話があるから、そのときに言うかもしれないけれども、他区のことを例に出すというのは、多分あまりいいことではないと思うので、ぜひ品川区独自でいろいろ考えていただきたいということだけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-019"}]},{"id":"topic-04","title":"令和６年能登半島地震に対する区の対応","agenda":"令和６年能登半島地震に対する区の対応","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは、１月４日というのは仕事始めでありまして、地震があったのが１月１日ということで、役所に当直の職員がいることは知ってはいるのですが、休みの間、区長や部長や職員が、私は相当動いていたと思うのです。そうでなければ、４日の日に本部などを開いて早速動き出すことはできませんから。自治体職員ならではの使命感と公務員としての役割と、しかし正月ですからね。","respondent":"勝亦総務課長","answer":"中部地方での地震ですので、連携交流のある福井県坂井市につきましても震度５という情報がございましたので、こちらのほうに何回か確認を取りまして、被害状況を確認した状況です。","voiceIndex":53,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"本当に驚く思いでして、緊急地震速報がテレビで流れると、今自分がいるところも揺れるのではないかという思いがあって、家族で不安な思いをしたことをよく覚えておりますけれども、本当にいつ何どき起きるか分からない事態でありますので、今回の経験も踏まえて、さらに緊急対応をレベルアップしていただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"上水よりも下水ですよね。こういうのが、例えば水に困っているとか、こういうのというのは今話題になっているでしょう。備蓄が大丈夫かとか、極端なことを言えば３日間、本当に７２時間生きてくれていれば、東京だったら３日間生き延びてくれれば、こういうことも支援物資から何からいろいろなことがある。品川区は井戸をやっていないじゃないですか。例えば２３区では、１０区ぐらいは多分やっている。","respondent":"勝亦総務課長","answer":"そういった意味で引き続き、今回は被災地支援という形にはなっておりますけれども、区民の方の防災意識といったものは引き続きさらに強く啓発・周知していきたいと考えております。","voiceIndex":56,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"意見","question":"ぜひ、よろしくお願いします。私はミサイルは想定していなかったけれども、今回地震が来たのでそういうのを考えて、広報しながわとか何かがあるので、そういうところで紙も含め、ホームページは後でそれを載せればいいのだから、ネットは後でもいいけれども、そういう紙媒体を含めてやってもらったほうがありがたいと思うので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-023"},{"speaker":"澤田委員","kind":"質問","question":"１月４日から義援金の受け付けをされていて、いつ終わる予定かというのはまだ現段階では決まっていないと思いますが、時間の経過とともに、様々な情報に紛れてだんだん風化していってしまうのかなと思うと、継続してＳＮＳなどで、今回１０７万円という金額が出ていますけれども、現時点では幾ら義援金が集まっていますとか、総額幾らになりました。","respondent":"勝亦総務課長","answer":"寄付に関しましては、引き続きの周知といった部分と、頂いたものを何に使ったか、そういったものをお知らせしていくことが、さらなるこの寄付へのモチベーションといいますか、意欲をお願いできると考えておりますので。","voiceIndex":59,"id":"exchange-024"}]},{"id":"topic-05","title":"区長部局におけるいじめ相談窓口の設置","agenda":"区長部局におけるいじめ相談窓口の設置","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"相談対応について、いじめ相談員による適切な対応とご説明がありましたけれども、伺いたいのは、電話など連絡があったときのいじめ相談員の姿勢と言いますか、構えについて伺いたいと思ったのです。友達には相談などできない。非常に孤立化していく中で、ここに電話をするその生徒・児童の気持ちをやはり十分踏まえて、命を守る取組みを優先していただきたいと願うわけですけれども、いかがでしょうか。","respondent":"勝亦総務課長","answer":"話していることを否定せずに全て聞く。そしてしっかりと気持ちを受け止めてあげる。そこから様々な話をさらにたくさん聞いていけると考えています。お話を聞く姿勢としてしては、受容して共感していくところから入っていくのかなと考えています。","voiceIndex":66,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひその構えもしっかり位置づけていただきたいと思うのですけれども、改めていかがでしょうか。ついつい何がどうなったのか理路整然と説明せよと、そのような状況では、やはり相談に来る時点で追い詰められていますから、そこを区長部局にも求めたいし、ぜひ教育委員会にもその専門性を生かして力を発揮していただきたいと、双方に願うわけですけれども、改めていかがでしょうか。","respondent":"勝亦総務課長","answer":"今、委員がおっしゃったように、いじめについてはこういう形になったらいじめだよということではなく、その行為を受けた方が心理的・肉体的に苦痛を感じたら、それがいじめであるというふうにこちらのほうは捉えて、ご本人のお気持ちも含め。","voiceIndex":68,"id":"exchange-026"},{"speaker":"松本委員","kind":"質問・要望","question":"これはこの紙と、あとホームページも拝見しながら質問させていただきたいのですが、平日の午前９時から午後５時に相談というのが、やはりこれがどうなのかなということで、保護者からの相談の場合だったらまだ、それでも今共働きの時代ですから、まず連絡できるかという問題がありますけれども、大人の場合は、場合によっては少し休憩を取って電話してくるということもあるかもしれません。","respondent":"勝亦総務課長","answer":"相談場所についてですけれども、こちらについては学校もしくは区役所ということで、やはり今、委員がおっしゃいましたように、学校に行くのは少し心配だとか気持ちが前に向かないということであれば、ご希望に沿った形で区役所のほうで対応したいと考えています。","voiceIndex":70,"id":"exchange-027"},{"speaker":"松本委員","kind":"意見","question":"寝屋川市も９時から５時半で、それほど変わらないので、そういう意味では寝屋川市も十全かと言われると、私はどうかなと思います。今回は、資料に書かれていますけれども、１月から３月までまずやっていただいて、それで反応を見るということですので、そちらを待ってということになると思いますが、お子さんだけでなく保護者もですが、できるだけ具体的な相談がしやすい体制を作っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-028"},{"speaker":"須貝委員","kind":"確認","question":"前にも申し上げましたけれども、それぞれ児童・生徒に何か相談事がありますか、いじめ等ありますかというような返信用の封書等を送って、区長部局にその内容が届いて、それでそのいじめの内容を確認して、当事者に出向くという形が私はよりベターだと思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-029"}]},{"id":"topic-06","title":"（仮称）ジェンダー平等を推進するための条例に盛り込むべき考え方に関するパブリックコメントの結果等","agenda":"（仮称）ジェンダー平等を推進するための条例に盛り込むべき考え方に関するパブリックコメントの結果等","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"パブリックコメントの様々なコメントを私も率直に読ませていただきました。こういうときだからこそ大きな一歩を踏み出す必要性があると、私はパブリックコメントを読んで率直に感じたわけですけれども、品川区としては、区の考え方の説明は先ほどあったとおりではありますけれども、今回のパブリックコメントの結果を受けて率直にどう思ったかというところを伺いたいと思います。","respondent":"加島人権啓発課長","answer":"パブリックコメントを実施しての、所管としての思いというところでお答え申し上げます。総括的なところが最初の説明で抜けてしまったのですが、今回パブリックコメントを実施した中で、条例の制定に賛成するとおっしゃってくださったご意見は６５件中７件。","voiceIndex":79,"id":"exchange-030"},{"speaker":"中塚委員","kind":"提案","question":"現状ではまだ第１回品川区議会定例会に出すというところですから、条例を提案するにあたって、早速、例えばですけれども広報しながわで特集を組んでみるとか、みんなの広場で特集を組んでみるとか、こういう提案をしますという提案の過程も含めて、今まで以上に理解を求めていく、ご意見を伺っていく、そうした取組みが必要なのではないかと思います。","respondent":"加島人権啓発課長","answer":"条例制定前にこのような条例を考えていますよというようなことを広報等に出していくというご提案につきましては、議会との議案審査の関係もありますので、制定前にそのようなものを出してよいのかどうかというところもありますが、条例が制定された暁には。","voiceIndex":81,"id":"exchange-031"},{"speaker":"中塚委員","kind":"提案","question":"私が言ったのは、同時に区民に対してもこういう条例の提案を今準備しておりますというのは、議会に説明した上で区民に説明し、理解を求め、意見を集めるという、その制作過程で議会とともに住民の参加を位置づけるという視点で述べさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-032"},{"speaker":"須貝委員","kind":"提案","question":"今回、ジェンダー平等推進にかかる条例ですが、議会に提案されるというお話です。確かに社会的にやはり多様性を尊重して、誰でも自分らしく生きられる地域社会の実現に向ける。ただ、どうしても区民の理解を得られるためには時間がかかると思いますので、私は少しずつ焦らずに一歩一歩前進していっていただければいいのかなと。意見だけ言わせてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-033"},{"speaker":"松本委員","kind":"質問","question":"ただ、ここは結局偽ってしまえば、場合によっては逃げられてしまうのかなというところで、まず２段階に分けてお伺いしたいのですが、今回の中で、例えば品川区というふうに明記されていないものもここに掲載されているのかというのが１点です。２点目として、品川区というところまで書いてあるけれども、その具体的な地番まで書かれていないものも掲載されているのか。その点はいかがでしょうか。","respondent":"加島人権啓発課長","answer":"６５件いただいたご意見のうち、住所の欄に品川区ないしは品川区の町名等以下、番地等も含めて記載があったご意見については、５１件ございました。","voiceIndex":85,"id":"exchange-034"},{"speaker":"松本委員","kind":"確認","question":"確認です。５１件ということは、では例えばファクス等含めてという話になってくると、１０件以上は品川区と明記されていないものがあったということでよろしいのか、１回確認させてください。","respondent":"加島人権啓発課長","answer":"６５件から５１件を差し引いた残りの件数につきましては、そもそも不明と明記されていたり、空欄というか匿名、それから区外の住所等が入っていたものについては、５１件の中にはカウントしておりません。","voiceIndex":87,"id":"exchange-035"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"そこら辺のところを条例の中で心配されている方に、大丈夫なのだというのはちょっとあれですけれども、その懸念を払拭するような表現というのをぜひ求めたいと思っているのですが、その点についてというのが１つ。もう一つは、女性のエンパワーメントということで、様々女性に対するある意味女性ゆえの不利益があるから、支援していこうという考え方が出てきているのかと思います。","respondent":"加島人権啓発課長","answer":"２点目のトランスジェンダー女性、こちらが女性スペース、主にご意見の中であったのは風呂ですとかトイレですとかに入ってきてしまうのではないかというご心配・ご不安の声に対しまして、条例上でどのような表現ができるのかというところですけれども、率直に申し上げまして。","voiceIndex":90,"id":"exchange-036"},{"speaker":"塚本副委員長","kind":"提案","question":"２３区の中では比較的最後のほうになってこういう条例を品川区が今回提案していくということなので、本当に時代によっていろいろと変わってきている部分もすごくあり、過去に許されていたことがもう許されないという部分もあると思うので、そういったところでは先進的な時代の先をしっかりと捉えたような形で、さすがにこれは今の時代に即しているというものになるようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-037"}]},{"id":"topic-07","title":"，所管事務調査","agenda":"，所管事務調査","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今、このように２兆円も超えてしまって、再算定するとお金が余っているから、それこそ児童相談所の費用だって、そのうち始まったら、それだけあるのだからいいのではないですかといって、パーセントに入らない可能性があるような気がしてならなくて、だからここら辺のところは、担当課長会が最初だからお願いするしかないけれども、特別区で戦略的に例えば何区か。","respondent":"遠藤財政課長","answer":"決算分析はかなり時間をかけてやっているところで、これを変な話、２３区全てが出していろいろ積み上げて、こちらから言いたいことはきちんとエビデンスに基づいて説明すると。","voiceIndex":100,"id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"質問","question":"いつ見てもそのような程度だから、ぜひそれを今の区長会の話が出るのなら、区長会でもう一回そこら辺はもう５回ぐらい話が出るくらい頼むというぐらい、ぜひそれはやってほしいです。それと、ふるさと納税はもう一回勉強しますけれども、京都市の話が出て、この前どうかと言ったけれども、ホテルの支援というか旅館券みたいなものが出ているけれども、ああいうのを品川区は出せないのですか。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"意見","question":"それはぜひいろいろなことを、今、ここは財政課とか税務課で、ここでいいとか悪いとかという話はしないけれども、何かある程度そういうことをしていかないと、何かもうその返礼品競争はしないと言っているのはいいのだけれども、あまりに収入が少な過ぎるような気がしてならないので、ぜひそこら辺はもう少し何かプロを入れてやってほしいなということだけ言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"そのときに整備するのは各自治体ですから、それに備えて、やはり事前に算定基準を上げていただいて、それを使えなくてもいいですけれども、各区でやはり基金にして持っておくような何かそういうことをやっておかないと、いずれ２３区ももう財政的に困ってしまうような状況が来るのではないかと思うのですが、そういうことは区の中でも考えられていると思うのですが、２３区のほうでも財調算定に対して。","respondent":"遠藤財政課長","answer":"特別区全体的に子育て世帯等が増えているのと、あとは高齢者の方も増えてきて、一方で生産年齢人口がそろそろピークになるというところで、需要額がどんどん必要になっていくというところがあって、一方で収入額が減ってくるというのも目に見えている部分がありますので。","voiceIndex":106,"id":"exchange-041"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区にある財産、不動産ですね。それに対して、その分に対して、では２３区がどうなのかという話になったときに、今までの配分だけではなくて、やはり将来を見据えた配分も頂くようにしていかないと、私は大変なことになるのではないかと思いますので、区としても検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2288#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":48174,"voices":115}},{"id":"r06-20240123-14","meetingId":"r06-cm01","date":"2024年1月23日","dateIso":"2024-01-23","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、特定事件調査","agenda":"の１、特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"建物の概要・外観計画について伺いたいのですが、先ほどのご説明では、基本設計がある程度固まってきてということで、ご報告ということだったのですが、ここに出ているのは概要・外観というところで、どこに何が、例えば総合庁舎の中に何がどういう形で入っていくのかとか、そういう報告は今のところはないのですけれども、取りあえず。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"中の配置とか、その他のものにつきましては、今後検討が進み次第、随時お出ししてご報告させていただきたいと思っているところです。資料にあります行政機能、区民交流スペースというところの記載についてですけれども、こちらは基本計画で申しますところの区民協働・交流の機能の部分のスペースということで考えてあります。","voiceIndex":6,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"中が決まらなくて、外観とか概要は決まるものなのかというのが、私は素人なので分からないので、いわゆる概要が決まる、何階建てになるとか、中のものが、先ほどのご答弁だとこれから決まっていくというお話ですけれども、それはまだ決まっていないということでよろしいのでしょうか。それと、行政機能、区民交流スペース。これは基本計画の何ページに、ほかの建物でつくるというところがあったのでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"その上に３階部分、４階部分として設定していくというところで、別棟の建物という形ではないというところで、補足説明します。","voiceIndex":9,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"各方面からも注目を浴びている施設でありますので、いわゆる国の施設が入ったり、東京都の施設が入ったりということもあるので、いろいろなご調整は必要かと思うのですけれども、本委員会にはなるべく速やかに提示をしていただきたいというところで、すみません、最初に受けた印象が、外だけなのか、外観だけなのかという印象が少しあったものですから、そういうことで質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"いろいろと意見集約に当たってはご苦労があったと思いますが、ご対応、誠にありがとうございました。ぜひ多くの方々に見ていただけるよう、ご活用いただきたいと考えています。これは要望です。見た感じでは、窓のところとかが一部、特徴的な意味があったりしていて、そういったところが普通とは異なるとは思うのですけれども、そこに対するコンセプトとかがあれば、教えていただければと思います。","respondent":"大友新庁舎建設担当課長","answer":"具体的にお示ししますと、誰もが使いやすいという点で低層としたというところと、区民利用、区民活用が多い場所、低層部を広く持っているところ、また、先ほど少しお話をいただいた、外観的に少し特徴的なでこぼこのある外装デザインというところにつきましても。","voiceIndex":13,"id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"暫定というところで、変わり得るというところですけれども、環境に配慮したつくりであるというところで理解しました。ぜひ、これから品川らしさ等の意見も反映して、さらによい外観となるよう、ご検討を進めていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"暫定ですけれども、外観のイメージが出てきたということで、いよいよかなということはあるのですけれども、一方、この資料は、「ＪＲ東日本着工プレスリリース掲載資料を加工したものであり」とか、そういった旨が書いてあるのですけれども、この暫定イメージ図を作成したのは、品川区が主体となって、このイメージを考えたということでよろしいのでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"こちらを反映した結果が、お示しした２枚目の資料、また、単独で絵を描いたものが１枚目のイメージパースとなっています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"先ほどおっしゃられた３つのコンセプトがあるということなのですけれども、それとこの絵がどのように関係するのかというのが、今、なかなか想像しづらいのですが、新庁舎整備基本計画に載っていることを３つのコンセプトにして、それをこのイメージ図に表したということでしょうか。計画に書いた３つのコンセプトというのは、具体的にはどれでしょうか。にぎわい都市の３つの基本理念というところでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"先ほど３つのコンセプトという形でお話させていただいたものなのですけれども、こちらにつきましては、基本計画において、３つの基本理念をまず示しています。その３つの基本理念から、６つの基本方針が定められてあります。","voiceIndex":19,"id":"exchange-007"},{"speaker":"筒井委員","kind":"確認","question":"分かりました。イメージ図ができているということは、逆算すると、このフロアはこうだとか、ある程度おおよそのことができている、先ほどそのような旨をおっしゃられていましたけれども、大体もうおおよその想定はできているということでよろしいのかということと、このイメージ図は、専門の業者に委託して作成したものかということ、２点ほど確認したいと思います。","respondent":"大友新庁舎建設担当課長","answer":"おいおい固まり次第、逐一ご報告させていただきたいと考えているところです。こちらのイメージパースを作成するに当たり、今回受注している設計業者の中で専門の部隊がいますので、そちらで計画の設計図からイメージパースに変換して、少し分かりやすい形に整えたです。","voiceIndex":21,"id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２点確認をさせてください。もう１点なのですけれども、南側なのですが、多分上が議会スペースだと思うのですけれども、南側だとオープンスペースのような場所が何か所か、南側の右側と左側にあるのですが、設計するに当たって、Ｎｅａｒｌｙ ＺＥＢを取得・認証するための構造体というか、躯体の考え方はどういうところなのかということを教えていただきたいと思います。","respondent":"大友新庁舎建設担当課長、黒田新庁舎整備担当部長","answer":"続きまして、２点目の公開スペースという形なのですけれども、こちらは、都市計画上必要な通路の場所のことかなと思うのですが、３階部分等々、デッキの部分には通路部分がありまして。１枚目の上段の配置図の、品川区新総合庁舎と書いてある左側に、少し茶色の部分があるのですが、ここは建物の屋上といいますか、低い部分と、りんかい線の部分に少し低層の階高がありまして、横が１４階建てとなっている中で。","voiceIndex":24,"id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。ありがとうございました。それと、あともう１点なのですけれども、計画概要で、高さが約６１.５ｍ、また別に、屋上設備など設置箇所は約７０ｍ超になるのですけれども、１０ｍ超というか、１０ｍ高くなるというのは、屋上設備はどういうものを設置するのか教えていただきたいです。","respondent":"大友新庁舎建設担当課長","answer":"こちらにつきましては、空調設備などの設備機器が屋上に設置される形になります。","voiceIndex":27,"id":"exchange-010"},{"speaker":"まつざわ委員","kind":"質問","question":"そこで、まず３７１件、その他１５７件、このご意見の数という部分で、区としてこの数が、多い意見なのか、少なかったのか。例えば、分析を見ますと、トイレに随分意見が集中しているというのがありましたけれども、その辺の手応えというか、感覚はどうお思いなのか教えてください。","respondent":"山下新庁舎整備課長","answer":"アクセシビリティ整備の手引き（素案）のオープンハウスの実施状況についてです。今回、１か月かけず、３週間ぐらいの取組の中で、区内６か所、それぞれの地域で実施をしてまいりました。","voiceIndex":31,"id":"exchange-011"},{"speaker":"えのした委員","kind":"質問","question":"今、まつざわ委員からもお話がありましたが、取りまとめもありがとうございました。なので、例えばトイレだけではないですけれども、そういったことが可能なのか。意見が多いところには、区としても見解を述べておられますけれども、逆にエスカレーターは２件しかないとか、緊急時対応とか、少ないものがあります。ご意見よろしいでしょうか。","respondent":"山下新庁舎整備課長","answer":"必ずしもその物を実物で作らなくても、例えばこういった広めの会議室等で、下にテープを貼るとかというのは、少しアナログな取組にはなりますけれども、実際の運用した広さはこれぐらいになるのではないかといった、実験的な取組というのはできようかと考えてございまして。","voiceIndex":35,"id":"exchange-012"},{"speaker":"えのした委員","kind":"質問・要望","question":"今後の設計・施工段階においても、様々なご意見、また見直し等があれば、その分、取り組んでいただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-013"},{"speaker":"塚本委員","kind":"意見","question":"暫定イメージ、１ページ目のところを見てですけれども、結構これはこれで斬新な形というか、よくあるオフィスビルとはまた違う、２ページ目の隣のビルのイメージとは全然違う形になっていて、これは、機能面からこういう形がある程度決まってくるといいますか、さっき言った３つのコンセプトというところなのか。","respondent":"大友新庁舎建設担当課長","answer":"そちらがファサードと言われる外観の建物の外のものになるのですけれども、そちらのひさしとかの形状が、環境性能上、一定寄与するという形で決まっているところがありますので、それをベースに、あとは建物の素材であったり、色であったり、また、そこの材質等々。","voiceIndex":38,"id":"exchange-014"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。それで、品川らしさのイメージというのは、今後またここに加えていくというお話があったのですけれども、一応、基本設計の期間が来年度までそんなにない中で、どれぐらい基本設計の中で進めていくのかと、議会への説明のタイミングとかというのはどんなスケジュール感があるかというところで、分かる範囲でお知らせいただければと思います。","respondent":"大友新庁舎建設担当課長","answer":"こちらのタイミングにつきましても、期間を空けずに、皆様にこのような場を通してご提示させていただきたいと考えておりますので、できるだけ最短のご提示ができるよう努めてまいりたいと考えております。","voiceIndex":40,"id":"exchange-015"},{"speaker":"松本委員","kind":"確認","question":"それで、新庁舎の外観イメージの屋上のところなのですが、ヘリポートは特にないという形で拝見いたしまして、基本計画を拝見すると、ヘリポートの関係、防災との関係でどこか記載があるのかといったら、しながわ中央公園にヘリポートがあるというところも記載があるので、新庁舎にはヘリポートは設けないけれども、災害が起こったときのヘリコプターでの対応というのは。","respondent":"大友新庁舎建設担当課長","answer":"大井消防署とも本協議をさせていただいてございまして、現時点では庁舎上には不要ではないかという状況で協議を進めているところです。","voiceIndex":43,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"そうすると、今のは新庁舎のほうの話ですけれども、今度、跡地の話との関係で、跡地の活用の検討の範囲というのは、中央公園も含まれているかと思うのです。ただ、これまで出されている説明用のスライドとかを見ると、検討範囲の中に、ヘリポートは所与であるという記載とかは特になかったような気がするので、ここのバランスはどうなっているのか伺えればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問・要望","question":"駐輪スペースについてなのですけれども、これも外観から読み取れないのですが、例えばきゅりあんのように、機械式に駐輪スペースを作られるのか、それとも、外側か駐車場のところに作られるのか、教えていただきたいというのがあります。最後に、喫煙スペースはどうされるのでしょうか。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"実際にエスカレーターを設置する段で、その設置位置等々によりまして、人の動線というのが見えてこようと思いますので。駐輪場についてなのですけれども、こちらは庁舎の周り、平面を使って駐輪場を整備していきたいと考えているところです。今回、新庁舎整備基本計画におきましても、保健所・保健センター機能の導入というところで考えましたときに。","voiceIndex":49,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問・要望","question":"エレベーターについては、先ほどのアンケートにもありましたように、モニターを設置していただいて、例えば品川区の広報にも活用できるのかなと思いますので、ぜひともお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それと、地上１４階ということも今回初めて出てきたと思うのですが、ごめんなさい、以前の議論の中で、明確ではないのですけれども、１４階から１６階建てとか、たしかそのような議論があったような気がするのですが、１４階に落ち着いたのだというところで、当然この中に、全ての今検討しているものが収まるということで、思ったよりも低かったというのが私の感想なのですけれども。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"２点目の１４階に落ち着いたというところになるのですけれども、こちらを過去、この委員会等々では、１５階から１９階程度になると想定して答弁をさせていただいて、ご説明をしています。１点だけ補足いたします。","voiceIndex":55,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問","question":"多分これから先、この暫定イメージと２枚目の外観イメージが独り歩きというか、これから出ていく話になると思います。そのときに我々も若干、説明をしなければいけないものですから、議会部分についてはお話を伺いました。免震構造についても伺いました。多分また、見ていればいろいろな疑問が出てくると思うので、それは個別にお伺いしたいと思います。","respondent":"泉広町事業調整担当課長","answer":"その後、４番といたしまして、ワークショップや検討委員会の結果を踏まえた活用の基本的な考え方の案を、また最後に５番として、今後実施予定の区民アンケートにつきましてご説明を行ったところです。続いて、２ページをご覧ください。","voiceIndex":58,"id":"exchange-021"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"でも体育館が、災害関連死と言われるぐらい、環境がなかなか厳しいというのが分かりながらも、やはり体育館という中において、宿泊施設というのが非常に私は興味を持っていまして、例えばそういうところに大きな宿泊施設ができれば、体育館で対応できない場合はそういうところで避難ができるとか、何かそういう考え方も一ついいのかなと思っていまして、その２つだけ教えてください。","respondent":"泉広町事業調整担当課長","answer":"今ありました宿泊施設、２次避難所ですと、能登半島のほうでやられていますけれども、そういったことがこちらの品川区内で可能なのかといったところは、防災の部局とも調整をしながら検討してまいるところだと思いますので、連携を図りながら進めてまいりたいです。","voiceIndex":62,"id":"exchange-022"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひ、初めは近くで、そして幅広くというのを努力していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-023"},{"speaker":"山本委員","kind":"質問・要望","question":"にぎわいの創出や地域の魅力発信など、特徴あるものを要望する声が大きいのかなという印象を持っております。そして、対話型市場調査の結果の中で、参画意向のところですけれども、参加した１６者で、参画に前向きな事業者が多いということも確認できたというところで、そういった事業者の皆様の参画意向をうまく引き出して、民間活用を前向きに進めていただきたいと。","respondent":"泉広町事業調整担当課長","answer":"先ほどご説明させていただいた第４回の検討委員会が３月２８日にございまして、また、それ以降も第５回の検討委員会ということで、まだ日程は決まってございませんけれども、本年の６月頃には開催ができるのかなというところで考えているところです。","voiceIndex":66,"id":"exchange-024"},{"speaker":"山本委員","kind":"質問・要望","question":"見通しについて、理解をいたしました。それからアンケートのところも、区外の皆様からの意見を聴取するタイミングで、併せて区内の方からも、意見を言える機会をつくっていただけるということでご検討を進めていただいているということで、非常にうれしく思います。ぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-025"},{"speaker":"えのした委員","kind":"質問・要望","question":"区民の方から幅広くご意見を聞いていただきたいと考えていますが、まず、関連する実績・知見を有する民間事業者との対話ということで、１６者（不動産事業者、建設事業者等）とありますが、こちらの実績の中で、既に、例えばどこかの跡地ですとか、敷地の活用ですとか、企業名は別としても、日本全国どの辺りでやっているとか、そういったことをもし教えていただければ、それをお聞かせ願いたいのと。","respondent":"泉広町事業調整担当課長","answer":"資料中にあります購入というところでは、民間事業者が跡地を活用するに当たっては、土地は購入が望ましいというご意見があったです。一方で、公有地ということで、その辺を鑑みまして、借地も考え得るというご回答が得られたというところのご説明です。","voiceIndex":70,"id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１４ページのところで、第２回ワークショップの実施結果、総括で、関連するものを集約して、右側の緑色の部分で、区民活動の活性化、チャレンジできる場の創出ということがあって、ワークショップの中でもチャレンジという言葉が結構出てきているのですが、チャレンジというのは幅が広くて、いわゆる企業のスタートアップもチャレンジでしょうし、何かスポーツ体験というのもチャレンジでしょうし。","respondent":"泉広町事業調整担当課長","answer":"参画を検討というところにございましては、今回の事業が大きいというところがありますので、１者だけではなくて複数者、ＪＶみたいなところを組みまして、参画をするというところもありますので、主要メンバーということで表現をさせていただいてございまして。","voiceIndex":74,"id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"前段のチャレンジの部分なのですけれども、そのとおりなのかなと思うのですが、これから区民アンケートを実施されるということで、聞く項目について、活用の方向性、１９ページに書いてありますが、活用のテーマ（案）として掲げている項目の重要度についてということで、重要度というものを多分、どこが皆さん関心が高いのかというところでの点数づけをしていくのだと思うのですが。","respondent":"泉広町事業調整担当課長","answer":"今回の対話型市場調査といったところは自由な形でご意見をお聴きしましたけれども、もう一つ、今回の検討の委員会の中で、一定の大きな活用のテーマなどが出てまいりますので、こういったところを踏まえて、またご意見をお聴きするようなところをつくりまして、引き続き。","voiceIndex":76,"id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問","question":"リンクを貼るということで、具体的なイメージはそこでしていただくというところなのかもしれないのですが、ざっと読んだ限りでも多種多様な、ある意味、これは着手をする区が、はっきり言えばフリーハンドで何とでもできるような、全てを網羅するようなテーマになっているわけであって、その中から区民の関心事とか、さっきの災害とか防災ということも入っていますけれども、今は多分。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは、活用検討委員会、またワークショップも開かれて、区民の様々なご意見を聴くと、こうした様々な意見が出てくると。区民といっても、人によって、生活様式だとか興味・関心によって、いろいろな意見が出てくるのだということは理解しました。おまとめどうもありがとうあります。そうしたこともしっかりと意識していただきたいとは思っているのですけれども、こうしたまとめが１８ページに出てきたと。","respondent":"泉広町事業調整担当課長","answer":"そちらのバランスにつきましては、２ページのところにも重なりますけれども、しっかり検討を進めていかなければいけない事項だというところで、委員の方からのご発言もあったというところで、委員の皆様も、財政負担の縮減といったところにつきましては。","voiceIndex":80,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"対話型市場調査のところで、事業者の方も様々、居住施設、商業施設、健康・医療施設、高齢者福祉施設と１６ページのところにありますけれども、複合化する意見が多かったということですが、検討委員会やワークショップとかのお声を聴いて、事業者もそれを受けてのことだと思うのですけれども、結局、区としては。","respondent":"泉広町事業調整担当課長","answer":"区といたしましては、例えば、複合化をしなければならないというところは考えてございませんで、今申し上げた区民ニーズの実現ですとか、財政負担の縮減、また、周辺との一体的なまちづくりといったところの視点が。","voiceIndex":82,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。結局、この調査を行って、金額のご提示がなかったということなのですけれども、最終的にはお金の問題というのは大事だと考えているのですが、大体いつぐらいの段階で、今後具体的にどのぐらいの費用がかかりますとか、経済面の話というのはどの段階でお聞きするとかは決まっているのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"今後、金額につきましては、事業手法の検証ですとか、そういったところを段階的に進める中で、お示しをしていくものということで、今はまだこの段階では、いつ頃といったところのお話ができないというところになってあります。","voiceIndex":84,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6162#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":32606,"voices":88}},{"id":"r06-20240124-19","meetingId":"r06-cm01","date":"2024年1月24日","dateIso":"2024-01-24","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ４時１０分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木副委員長","kind":"質問・要望","question":"本日は、お手元に配付しています審査・調査予定表のとおり、特定事件調査、報告事項およびその他を予定しております。そのため、副委員長の私が委員長に代わって進めさせていただきたいと考えていますので、どうぞよろしくお願いいたします。最後に、会議時間が長時間にならないよう、簡潔かつ効率的なご質疑にご協力をどうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":1,"id":"exchange-001"},{"speaker":"鈴木副委員長","kind":"意見","question":"本日は環境に関することに関連して、ＳＤＧｓに関連する内容について取り上げます。ＳＤＧｓの取組について理事者よりご説明いただき、その後、委員の皆様には活発なご議論をしていただければと考えております。理事者よりご説明をお願いいたします。","respondent":"河内環境課長","answer":"私からは環境に関することといたしまして、ＳＤＧｓなどに伴いまして、２点、連携協定によります区内事業者の再生可能エネルギー電力の導入支援およびマイボトル用給水機の利用促進に向けた今後の取組の２点につきまして、ご説明します。資料に入ります前に、まずＳＤＧｓです。","voiceIndex":2,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"資料のところから伺っていきたいのですが、再生可能エネルギー電力導入支援のところです。大企業などだと、自分で個別に契約できるのかと思うのですが、中小企業や個人事業主などといったところを想定されているのか、区の想定を伺いたいと思います。そのような面から考えると、再エネ事業者を広げていく、普及させていくということにつながるのかどうかということを伺いたいと思います。","respondent":"河内環境課長","answer":"現在はやはり太陽光パネルなどがメインになってくるとは思いますが、昨今報道機関では様々な環境技術が報道されておりますが、そのようなものも参加していただくことによりまして、より幅広い脱炭素電力の提供が可能になりますので、このような仕組みをしっかり活かしながら。","voiceIndex":5,"id":"exchange-003"},{"speaker":"のだて委員","kind":"確認","question":"その確認です。その中で、太陽光発電、バイオマス発電、水力発電などのようなものでいくと、事業者としてどのようなものが、どれだけあるのかというところも伺いたいと思います。事業者が続けていけるような契約ができる仕組みというものが、共同購入プロジェクトの中では何かあるのか、伺いたいと思います。","respondent":"河内環境課長","answer":"そのようなところに制約を求めないというところが、やはり持続可能性につながると考えているところです。","voiceIndex":7,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"もともとこの仕組みに２,０００を超える企業が登録をしておいてから、参加できるということではなくて、ある意味、全部の企業が参加対象、そのニーズに合ったところに呼びかけていくということなのかというところを確認させていただきたいと思います。","respondent":"河内環境課長","answer":"そのような４つの段階を踏んでまいりますので、１度に無条件で全てのところがどんとというものではございませんので、そこは自動的にスクリーンにかかりますので、そのような懸念はご無用かと考えているところです。","voiceIndex":9,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"なるほど。何となく分かりました。そのようなところでいくと、一番、今ある再エネ事業者は、太陽光パネルが多いということですね。今回のこれをやっていくことによって、導入する事業者のほうで安価な電力が調達できるということなのですが、これをどれだけ削減できるというところ、料金とＣＯ２のところで、区の見込みを伺います。","respondent":"河内環境課長","answer":"我が区については、今のところまだ非常に難しいのではないかと解釈しています。これは、いろいろあるかと思いますので、一概にではないのですが、現在、そのように経理課のほうでも判断しているという状況です。","voiceIndex":11,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"やはり広く知ってもらうためにも、内容を理解してもらうためにも説明会を開催すべきだと思うのですが、いかがでしょうか。そのときに、この事業の説明を聞きに来た企業にもこうしたことを説明していただけたら、より理解が深まっていくのかと思うのですが、いかがでしょうか。","respondent":"河内環境課長","answer":"この２つをもちまして、まずは進めてまいりたいと考えていますが、いろいろな声も上がってくるかと思いますので、そのような声やリアルに受けながら、説明会なども検討していければというところに考えております。","voiceIndex":13,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"説明会のところは、いろいろな声を聞きながらということでしたので、ぜひ声を聞きながら実施をしていっていただきたいと思います。そのようなところも環境をしっかり守っていくというところを、ぜひ理解を深めていただけたらと思います。再エネの利用の導入については、ぜひ広げていっていただきたいと思うのですが、今後の区の展開について伺いたいと思います。","respondent":"河内環境課長","answer":"皆の課題として共有しつつ進めることが、やはりこのようなものの大きな重要なポイントになるかと思いますので、そのような点を踏まえ、区有施設や民間を併せまして、しっかりと推進していきたいと考えているところです。","voiceIndex":15,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"区の施設のほうでも、今、箇所数では１６％ぐらいだということですので、ぜひさらに広げていっていただきたいと要望しておきたいと思います。今回このような共同購入プロジェクトも導入されるということですので、民間企業のほうでも、区として支援できることを、これだけではなく、ほかのところでも、ぜひ再エネ普及へ支援をしていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"私からは事業者への再生可能エネルギー電力導入支援から、１点お聞きしたいと思います。地域事業者、法人や各事業所のＲＥ１００に向けて、ぜひＰＲの仕組み、仕方や取組に全力を注いでいただきたいと思います。品川区でも今後の取組の工夫で考えられる工夫点など、もし紹介できるものがあれば、教えていただければと思います。","respondent":"河内環境課長","answer":"そのような中で、やはり長期的というか、持続可能性を持ってやっていきたいと思います。その大きなヒントをありがとうあります。そのようなものを含めまして、しっかり推進して、周知、ＰＲについて全力を尽くしたいと考えているところです。","voiceIndex":19,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"質問をします。ユーザーからすれば、やはり安い電力の供給を私はどうしても求めていくわけで、安くて安定した値段ということを考えると、そちらにシフトしていくことが大きいのではないかと思います。そうすると、電力料金がまた大幅に下がってくるということがありますと、民間で、このような事業をやるということはどうなのかと、なかなか難しいのではないかという気もするのですが、教えてください。","respondent":"河内環境課長","answer":"再生可能エネルギーにつきましては、極めて０.０００に近い排出係数でございまして、同じ電力であったとしても、環境に対するアプローチは全く異なるというところが、この進め方のメリットだと思っています。","voiceIndex":22,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほどから出ておりますけれども、やはり持続可能なそのような仕組み、経済状況、またはそれぞれのユーザーが何を求めているのかということも考えながら、これに取り組むことはいいと思うのですが、やはり、最後、そのような値段のところのせめぎ合いもあると思うので、その辺は慎重に進めていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。本日は、事業者への再生可能エネルギーの電力導入支援ということのお話でありました。中小企業といってもいろいろありますので、お一人、お二人でやっているような本当に小さい企業もあります。そのようなところも含めて、区としては、どのようなところを対象としていきたいと思っているのか、どれくらいの募集をしたいと思っているのか、お聞かせいただきたいと思います。","respondent":"河内環境課長","answer":"ご説明したとおり、個人事業主の方でも、本当にご参加いただける仕組みです。電力の使い方は人それぞれでありまして、人数が多ければ、それなりに電力を使いますが、１人当たりの単価や平米当たりの単価で考えますと、そんなに変わらないという統計もあります。","voiceIndex":26,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"このご案内をする企業によっては、まずはこのチラシ等、紙ベースで知っていくということかと思うのですが、紙ベースの案内が来たときに、どうやったらその企業に関心を持ってもらえるか。このチラシは区が作っていくと、ここでは読み取れるのですが、まずはここの案内が大事かと思ったのですが、どのように進めていくのか、もう少し詳しくお知らせいただきたいと思います。","respondent":"河内環境課長","answer":"そのようなところに響くように、しっかりやっていきたいと思います。具体的にはどのような伝え方かということは、なかなか今この場ではお答えできなくて申し訳ないのですが、そのような考えの下にしっかり進めてまいりたいと考えております。","voiceIndex":28,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問","question":"相談連絡先をしっかりと、当然どこかの問い合せ先は出されることと思うのですが、例えばこのようなことはどうなのですかという質問形式で載せていただくなり、また相談連絡先は、しっかりと分かりやすいように明記をしていただくなりの工夫をぜひお願いをしたいと思います。引き続き、環境に関する取組また強化もしっかりと進めていただきながらお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-015"},{"speaker":"吉田委員","kind":"確認","question":"それを評価しつつ、やはり次は事業者の取組を進めるべきではないかという方向で質問をした記憶があるのですけれども、この取組というのは、そのような流れを、まずは区がやり、大きな事業者がやり、その流れを、区が支援しながら小さな事業者まで進めていくということだと私は理解して、すごくいいと思ったのですけれども、その理解が間違っていないかどうか、１回確認させてください。","respondent":"河内環境課長","answer":"一方で、現在の電力の料金について、このままでいいと思われている方については、見直しは要らないとは思うのですが、サプライチェーンの中で、ぜひそのようなところで、例えば再エネ率の高さはいろいろあるかと思いますし、ＣＯ２の排出係数についても。","voiceIndex":32,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"５４か所となると、その後の契約書の確認が進んでいないのですけれども、せっかく区としてもこのような方向性なので、このような災害・環境対策特別委員会には、どのような契約をしているか、ここは再生可能エネルギーに直接だし、その再生可能エネルギーの生み出し方も環境破壊につながっていないということを確認できるような資料をぜひつけていただきたいと思うのですけれども。","respondent":"河内環境課長","answer":"そのような情報発信も含めて、区全体のＣＯ２の削減に向けて、しっかり進めてまいりたいという考えはもちろんありますので、よろしくお願いいたします。","voiceIndex":34,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、今、見た目、再生可能エネルギーが進んだからいいではなくて、やはりそれが本当にＳＤＧｓにつながっているのかという確認は、議員も全部含めて進めていくべきだと思います。それをみんなで確認するためにも、そのような資料は、ぜひ用意していただきたい。その辺のことも配慮して、私たちも一緒に確認しながら進めるというような資料の提供をぜひ進めていただきたいと思います。","respondent":"河内環境課長","answer":"それがＣＯ２の削減につながっているならば、是とするか、どうするか。大きな目標に向かって、そこを精査しつつ、そのような精査もまた大事かとは思いますが、バランスを取りながら、ぜひ進めて、やらせていただきたいと考えているところです。","voiceIndex":36,"id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"おっしゃるとおり、ＣＯ２削減が大きな目標で、だから、やはり品川区がいろいろ選択しながら、今、品川区としてのＣＯ２削減につながっていたとしても、そのＣＯ２削減のための再生可能エネルギーを生み出す段階で、別のＣＯ２を発生させていたらしようがないわけではないですか。そのようなことを避けていただきたいということです。私からはこれで終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問","question":"先ほどの質問に引き続きなのですけれども、ＰＲというところはとても重要だと思っていまして、この取組に品川区が参入するということ……。ごめんなさい。ほかに１０個の自治体はもう既にやられていると思うのですが、そのような自治体などで、実際にＰＲで、区のホームページ、広報以外で何かやられていることがあれば、また、もし品川区が検討していることがあれば、併せて教えてください。","respondent":"河内環境課長","answer":"利用者の声は、その方の立ち位置、立ち位置で変わってくるかと思いますので、万人の方にどう受け止めていただくかということはなかなか難しい課題とは思いますが、利用者の声も含めて、今後検討できればと思ったところです。","voiceIndex":40,"id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問","question":"事業者向けにそのような何かカリキュラムなどの説明会というか、この支援の事業のことではなくて、多分、再生可能エネルギーのところでの講演などをやられているということだと認識したのですが、そこの中で、もし今回このプロジェクトを提携してやっていくのであれば、併せてその説明も少し言えるといいのかと思うのですが、そのようなことは検討されているのでしょうか。","respondent":"河内環境課長","answer":"もちろん、その中でしっかりお伝えさせていただきたいと考えています。設備投資できる費用は限りがありますので、ここまでやらずとも貢献できるやり方があります。それはこれです。ぜひご利用くださいというところは、しっかり発信していきたいと考えております。","voiceIndex":42,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"マイボトル用給水機も質問していいですか。これから品川区でロゴマーク等をやって、どんどん普及啓発を図っていくのでしょうが、逆に民間のスーパーでやっているところのほうが、人の出入りも多いし、利用される方も、家の近くで利用しやすいと思うのですが、今、区でこのようにまた設置していこうということは、どのような意味合いでやっていくのかを教えてください。","respondent":"河内環境課長","answer":"一方で、ＳＤＧｓの中では水は大変大きなキーワードで、水を通じて、地球環境などを考えつつ、ほかの環境行為にいろいろなよい影響を与えるようにというところで、これをしっかり推進していきたいということが、こちらの大きな眼目になっておりますので。","voiceIndex":46,"id":"exchange-022"},{"speaker":"須貝委員","kind":"提案","question":"たしかスーパーマーケットのものは、飲料水としても使っていると思うのです。ですから、そのようなところに、逆にその環境課で何かシールを貼らせていただく。そのようなこともすごくいいのかと思って、一応提案だけします。お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-023"},{"speaker":"鈴木副委員長","kind":"質問","question":"ほかにはいかがでしょうか。よろしいですか。ほかにないようですので、以上で特定事件調査を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-024"},{"speaker":"鈴木副委員長","kind":"確認","question":"報告が終わりました。本件に関しまして、ご確認等がございましたら、ご発言をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-025"},{"speaker":"のだて委員","kind":"質問","question":"今回パブコメをやって、意見の件数が１３件ということで、この数について、区としての評価はどうされているのかというところを伺いたいと思います。やはり地域防災計画ということで、区内全体に関わる重要な変更になると思うのですけれども、そのところで、パブコメが１３件ということは少ないのかと思うのですが、伺いたいと思います。","respondent":"平原防災課長","answer":"その次のご質問にも続きますけれども、区としての受け止めとしましては、しっかりとした大事なご指摘を受けたと考えていますので、こちらについて、先ほどご説明させていただきましたとおり、地域防災計画に反映するものではないものもありますが。","voiceIndex":53,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"分かりました。ぜひ、この説明会をやっていただきたいと思うのですけれども、いかがでしょうか。実際、今の計画上、上水だと２０３０年度末で６１％と目標だということと、下水が、今、避難所などの主要部分しか計画がないと思うのですけれども、やはりそのようなところをしっかり耐震化１００％の早期実現をしていくということを東京都に要望していただきたいと思うのですが、いかがでしょうか。","respondent":"平原防災課長","answer":"説明会です。先ほども申し上げさせていただきましたとおり、まず地域防災計画そのものを説明しようとすると、何分いろいろ書き直してきましたので、１,０００ページを軽く超えるような内容になってしまいまして、ますます増えてしまいました。","voiceIndex":55,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区も東京都ですから、恐らく人が能登よりも相当多いということで、昼間人口も多くなると思います。実際、今回の地震では、様々、自宅が倒壊されている、あるいは傾いているというところでも、在宅避難されているという方もいらっしゃるというところで、在宅避難への支援がさらに求められてくるのかと思うのですが、いかがでしょうか。","respondent":"平原防災課長","answer":"ただ、そのようなところが継続して在宅避難が可能となるように、区のほうではそのような方々への対応を今後もしっかりと詰めてまいりたいと考えています。特に物資支援、情報支援というようなところで、そのようなものを確立してまいりたいと考えています。","voiceIndex":57,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"分析はこれからということですので、今回の教訓も踏まえて、震災関連死などもないように、未然に予防をしていくということも含めて、取り組んでいただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"パブリックコメント結果について、やはり区民の考え方が変わってきたのかということは、「在宅避難体制の充実強化・見直しについて」、「高層マンション対策について」で、備蓄について義務化してほしい。ローリングストックの件もそうです。こちらのほうの待遇を考えてほしい。そのときには、もう区としては、在宅をお願いしたい。今回は結果についてですから、意見だけで終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-030"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。今回のパブリックコメント１３件ということで、数としては多いか、少ないか、前回よりも多かったということでありましたが、お寄せくださったこの１３件のご要望が、皆さんこの計画をしっかり読んでいただいた上でのご意見だったのかと、やはり関心が高いと思いました。ここが非常に大事なのかと思っています。","respondent":"平原防災課長","answer":"続きまして、令和６年度に配布予定のハンドブックのところです。ハンドブックにつきましては、今回の見直しの一つの大きな考え方の中に、品川区ならではというような発想で考えてあります。","voiceIndex":61,"id":"exchange-031"},{"speaker":"澤田委員","kind":"質問","question":"私からは、No.１１の4)についての質問です。現在、施設には、エレベーターが１台しかない場合も多い印象があるのですけれども、福祉避難所の中で、非常用エレベーターが普通のエレベーター以外にもついているという施設はあるのでしょうかということが、まず１点。それからでお願いします。","respondent":"平原防災課長","answer":"大変申し訳ございません、そのようなところの整理をしている資料は持ち合わせておりませんので、事情をこちらのところでは把握できておりませんが、耐震性がより必要だというところは、私ども区役所内で共通認識として考えているところですので。","voiceIndex":65,"id":"exchange-032"},{"speaker":"澤田委員","kind":"質問・要望","question":"福祉避難所に指定されているシルバーセンターなどは、結構老朽化したものも多いのかと思います。印象でしかなくて申し訳ないのですが、なので、建て替えなどの際に、設計の段階から、福祉避難所ということを想定して、非常用エレベーターの設置などもぜひご検討いただければと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"ただ、一方、全てが全てそうではないので、支援員などの考えをしっかりとして、どのような状況でも、しっかりとその方を保護できるように対応を考えてまいりたいと考えています。施設のところで老朽化というようなお話がございましたけれども、防災に関わる施設です。","voiceIndex":67,"id":"exchange-033"},{"speaker":"こしば委員","kind":"確認","question":"私からは、パブコメの３ページ、１１番の3)「防災区民組織の育成・強化や防災広場の整備について」お伺いします。確認なのですけれども、この意見に対する区の考え方の中で、冒頭のほうに「防災区民組織の育成・強化を図っていきます」とありますけれども、これはあくまでも町会や自治会の中での防災区民組織の強化を意味しているのかどうかをお答えください。","respondent":"平原防災課長","answer":"私どもは、もともと防災区民組織は、東京都の震災対策条例という、区でいう防災区民組織ですけれども、町会・自治会を母体としたといったところは何ら変わりございませんので、従来どおりの考え方の下での育成です。","voiceIndex":71,"id":"exchange-034"},{"speaker":"こしば委員","kind":"質問","question":"やはり、なかなか、いざというときに、すぐ動けるか、どうか、当然、体力がある方もいらっしゃいますけれども、そうでない方も当然いらっしゃいます。確かに先ほど説明があったとおりではあるのですけれども、もう少し柔軟に組織・地域を今の状況に合わせて考えていくこともどうかと思うのですけれども、その辺りのお考えを教えてください。","respondent":"平原防災課長","answer":"今回の地域防災計画の一つの考え方の中に、地区防災計画を地域防災計画の枠組みの中でつくっていこうというような形のことを、前回の１１月９日の委員会で、ポイントの一つとしてご説明させていただきました。","voiceIndex":73,"id":"exchange-035"},{"speaker":"こしば委員","kind":"質問","question":"防災区民組織もあります。当然その前提にはその地域に暮らす区民の方々がいらっしゃるわけです。そのようなところで、この防災区民織もそうです。そのモデルケースというのは、もう区のほうでも、たしか好事例で周知されていると思いますけれども、そのようなことも是非お示しをいただければと思うのですけれども、それに対して、またお考えがありましたら教えていただければと思います。","respondent":"平原防災課長","answer":"よく自助、共助、公助といったときに、私ども役所側、公助のところが、地域に対して何かしていただくときには、共助の窓口です防災区民組織については、欠かすことができないというか、地域の中核であると考えているところは、全く変わりはございません。","voiceIndex":75,"id":"exchange-036"},{"speaker":"吉田委員","kind":"確認","question":"先ほどもご質問が出ていましたけれども、福祉避難所のことで、パブリックコメントというか、ご意見としては、福祉避難所の設置を急いでほしいということだけがシンプルに書かれています。庁内での福祉避難所が適切に機能するかどうかについての検討などということは、どのようにされているのかを確認させてください。","respondent":"平原防災課長","answer":"例えば施設整備課でありますとか、私ども防災課は、意見を求められた際など、あるいは協議対象としてという形で入っていくというような関係性で進めしています。","voiceIndex":78,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"福祉計画の策定のときには、防災課は参加されていないではないですか。施設設備課も参加されていないし、結局、福祉部の所管だけなのです。それは大分前なので、今はその協議が進んでいるのかと思うのですが、何か具体的に年に何回かは、そのようないろいろなところが連携した会議を持っているとか、そのようなことがあるのか伺いたいと思います。","respondent":"平原防災課長","answer":"実際に先ほどの福祉避難所の話でいきますと、社会福祉法人の福祉避難所でありますと、福祉部のところで、ある程度検討を進めて、それが相手方との一定の形になりましたら、私ども防災課に話が来まして。","voiceIndex":80,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"その後から、いやいや、避難用エレベーターとするためには別の条件があるのですということを消防署などにも確認をさせていただいた。既存の施設について、もし震災が起きたときのエレベーターの状況、それが非常用エレベーターとして使えるような責任者の人員配置がされているのかなど、防災課としてはその辺のことも把握されているのかを伺いたいと思います。","respondent":"平原防災課長","answer":"私ども防災課は、被害が発生したとき、例えばエレベーターに障害が起きたときに、エレベーター協会とのつなぎであるなどの対応でという形になりますので、一般的な施設の所管関係は、通常の部のほうで行わせていただくような形になってあります。","voiceIndex":82,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。それについては、今後の対応として、ここにこのように充実を図っていきますという、書きようとしたら、それぐらいしか書きようがないかと思いますけれども、具体的にどうなのかは、ぜひその障害者団体やいろいろな高齢者の団体には、今後、もう少し具体的な説明ができるように図っていっていただきたいのですけれども、その点についてお考えを伺いたいと思います。","respondent":"平原防災課長","answer":"様々な要素を考えながら、実際の災害時には対応していく形になろうかと思いますので、今、平常時にできることはしっかり対応しますけれども、災害時の対応はそのときはそのときで、柔軟に対応させていただこうと考えています。","voiceIndex":84,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"最後にします。戸開走行で、地震が起きたら当然その近くの階に止まっているようになっているということが、もう前提ではないですか。障害者各団体から、災害のときについては、それぞれの障害種別によっていろいろな配慮を求められることのご要望が、各会派へ来ているかと思います。これは要望でとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-041"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望です。これだけ公園などがたくさんあるので、それも、在宅避難とともに考えてほしい。は井戸水のことを言われたのです。それも考えてほしい。私はやってほしいと思うのですが、そうすると、１か所に集中することなく、分散して、地域ごとに避難が自立できるような仕組みがつくれるのではないかと思うので、その辺は検討していただきたいと思います。これは意見だけで結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-042"},{"speaker":"つる委員","kind":"質問・要望","question":"品川区は、ＪＰロジスティクスと連携して、備蓄品の管理、輸送体制まで提携しているわけですけれども、先日視察させていただいて、そのときも伺って、例えば道路が悪路になっても、違うルートを熟知しているドライバーが、軽ワゴンで必要な輸送先に行くのです。在宅避難に関連して、備蓄物資がしっかりとそのようなところに届くのかどうかということをまず教えていただきたい。","respondent":"平原防災課長","answer":"ただ一方で、届けるというようなことにつきましては、在宅避難者は単純に考えても３０万人弱ということが見込める中で、そこに届けるということは、率直に申し上げまして、現実的ではございません。","voiceIndex":90,"id":"exchange-043"},{"speaker":"つる委員","kind":"質問・要望","question":"結果として、発災時には届く。人海戦術も含めてなのでしょうけれども、それがすごく大事かと思うので、ここについては、あらゆる想定で、想定外がなくという話が最近あるのですけれども、そこは本当に飽くなき改善、充実策をぜひ取っていただきたいと思う。そのような訓練が、来年度などを含めて、現状、考えの中に訓練そのものがあるかどうかということを一つ教えてください。","respondent":"伊藤災害対策担当課長","answer":"ただ、どうしてもやる必要がある、昨年度、令和４年度に実施した東京都と品川区の総合防災訓練等々、大規模なものになれば、必然的に活用する状況になってくるのかと思いますが、今後そのような状況になりましたら、活用させいただければと考えています。","voiceIndex":92,"id":"exchange-044"},{"speaker":"つる委員","kind":"質問","question":"今、最後のところは孤立地域において活用するという答弁に聞こえました。救助だったり、消火だったり、いろいろある。所属するのが警視庁だったり、消防だったり、自衛隊によっては、その実地内容というのは、多分、いろいろ様々だと思います。品川区でそれを使える場所というのは、今、何か所あるのでしょうか。品川区が確保できているヘリポートと臨時救助スペースについて把握していれば教えてください。","respondent":"平原防災課長","answer":"ヘリポートを複数確保しているのですけれども、大変申し訳ございません、ただ、今、直ちには数字が手元にないもので、お答えは難しいのですけれども、複数は確保しています。たしか地域防災計画にその旨はしっかり記載しているかと思います。","voiceIndex":94,"id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"たしか臨時ヘリポートは７か所です。ＨとＲで多分違うと思うのですが、Ｒがホバークラフト状態で、救助員が降りて、人命を救助するところだと思うのですけれども、そのようなところがどうなのかということも、また別の機会に確認していきたいと思いますので、ヘリの活用空路というところで、あえて聞きました。夜間や悪天候のときに、よく見えるのかどうかというその確認です。","respondent":"平原防災課長","answer":"防災課ではございません。ヘリサインの基準というものがございまして、視認性のあるものを使うことという形ですので、施設によって若干違いがあると聞いてありますけれども、視認性に優れた素材を使うという形で聞いてあります。","voiceIndex":96,"id":"exchange-046"},{"speaker":"つる委員","kind":"質問・要望","question":"多分、やはり７都県の基準に基づいて、サインをつけていくと思うのですが、それの中にも、当然いろいろな業者が開発して、蛍光のものなど、いろいろあろうかと思います。逆に言うと、それは今言ったように教育委員会の所管で管理しているというところなので、そのような改善については、別の機会で求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-047"},{"speaker":"つる委員","kind":"質問・要望","question":"自衛隊のところです。この辺りについては、品川区は、いわゆるその管理職というか、理事者レベルではない、現場で本当に動いていただくような方々との顔の見える関係というのでしょうか。自治体によっては簡単な会食をやっているところもあるそうなのです。このような関係は品川区にあるのか。もしなければ、ぜひ今後検討していただきたいと、これは要望です。現状あるかどうかを教えてください。","respondent":"平原防災課長","answer":"そのような場で意見交換させていただいて、それぞれ顔を知って、お話をしてというような形で関係をつくらせていただいているところです。しっかりと連携を取らせていただいているつもりです。","voiceIndex":100,"id":"exchange-048"},{"speaker":"鈴木副委員長","kind":"質問","question":"よろしいですか。ほかにはいかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-049"},{"speaker":"鈴木副委員長","kind":"確認","question":"報告が終わりました。本件に関しまして、ご確認等がございましたら、ご発言をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-050"},{"speaker":"西村委員","kind":"提案","question":"何か詳細がお分かりでしたら、「５年生による学校防災設備の紹介ツアー」など、独自のいろいろな訓練を工夫されておりますので、教えていただきたいと思っています。積極的な町会、また消極的なエリア、それぞれある中で、訓練内容を共有する機会があれば伺いたいことと、また区役所のほうから、訓練内容をご提案するような、紹介するような機会はあるのかを伺いたいと思っています。よろしくお願いします。","respondent":"伊藤災害対策担当課長、平原防災課長","answer":"この訓練の実施日に併せまして、町会の方々に小学校５年生の皆さんが、学校にある設備、防災備蓄ですとか、防災関係装備を説明するというようないわゆるカリキュラムをつくっていただきまして。例えば隣の区であっても、基本は６キロメートルという考え方で、参集できるかできないかという発想があります。","voiceIndex":106,"id":"exchange-051"},{"speaker":"澤田委員","kind":"質問・要望","question":"やはり地域にお母さん、お父さんが参加している、おじいちゃん、おばあちゃんから住んでいて、そのままつながっているという方もいると思うのですけれども、そうでないと、全く知らない、そこに住んでいるおじいちゃん、おばあちゃんと話す機会はないという子もたくさんいると思うので、ぜひ全校でということは大変なのかもしれませんが、先生方やＰＴＡの方にご協力いただいて。","respondent":"伊藤災害対策担当課長","answer":"２点目ですが、視覚・聴覚障害者の関係です。今回の夏から秋にかけまして実施をしました地区の総合防災訓練につきましては、私が知る限りでは２名の聴覚障害者の方が参加をしてございまして、訓練場所には手話通訳ができる方を配置してございました。","voiceIndex":111,"id":"exchange-052"},{"speaker":"澤田委員","kind":"質問","question":"参加されていた方もあるということを聞いて、とてもうれしく思いました。そうしましたら、災害が本当にあったときに手話通訳の方はいらっしゃるとは限らないので、例えば指さしのプレートを用意するなどという工夫も今後ご検討していただければと思います。いかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"今回、手話通訳だけではなくて、外国の方も参加されていたりしまして、少し準備が足りないというところもございましたので、例えばボードで多言語ができるものなどといったところも併せて用意をさせていただければと考えています。","voiceIndex":113,"id":"exchange-053"},{"speaker":"ひがし委員","kind":"質問","question":"ただ行きたいと言っていらっしゃるので、実際にお声がけなどはされているのか。昨年から始めたということで、まだ１回目だから、なかなかというところもあるかもしれないのですけれども、今後実施するときには、せっかく準備するのだったら、ぜひ幅広く参加していただいたほうがいいのかと思うので、その点について何かお答えがあれば教えてください。","respondent":"伊藤災害対策担当課長","answer":"せんだってご意見をいただきまして、障害者支援課のほうとも連携をいたしまして、今回は、私のほうでは２名の方が参加されるということで対応をさせていただきました。","voiceIndex":117,"id":"exchange-054"},{"speaker":"ひがし委員","kind":"質問・要望","question":"この結果を見てみて驚いたのですけれども、５０歳未満の方々が９％ということで、１割にも満たないということ。今思い返すと、参加していたときに、確かに自分と同じ年ぐらいの方々はいなかったと思っていて、子どもは参加しているけれども、その中間の母親世代が参加していないというところで、そこについての課題や取組は何かされているところがぜひ教えていただきたいと思うのですが、いかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"訓練というものは、もしかしたら、そもそも少し厳しめのものなのかもしれませんが、少し人を集められるようなものをできるように、今後も検討してまいりたいと考えております。","voiceIndex":119,"id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"別紙２の表の参加者欄のところで、児童・生徒数が結構参加されているというところがあるのですけれども、一番多いところで豊葉の杜学園で１,０２４人ということで、このような多くの子どもたちが参加をするということになったことは、どのような経過があったのか、訓練内容などはどのような訓練されたのかというところも伺いたいと思います。","respondent":"伊藤災害対策担当課長、平原防災課長","answer":"私のほうから、まずアンケートをどのように区として取り入れていくか、また児童の訓練の参加者数が多かった理由についてご回答させていただきたいと思います。アンケートにつきましては、かなり個別具体的に書いてあるものもあります。今後もそのような取組を広めながら、顔合わせといったところを進めてまいりたいと考えています。","voiceIndex":123,"id":"exchange-056"},{"speaker":"新妻委員","kind":"質問・要望","question":"アンケートについてお聞きいたします。特に啓発品・非常食のところでも、乳幼児向けのものがあるといいのではないかとか、アレルギーがある方も安心して食べられるものなどというお声もありますので、このようなことを具体的に反映していただけるのかどうかお伺いをいたします。","respondent":"平原防災課長","answer":"もう１点、備蓄物資の件です。備蓄物資は年々拡充していますが、このようなお声は非常に重要ですので、どのようなものを拡充していくか、強化していくかといったところのしっかりと基礎資料とさせていただければと思ってあります。","voiceIndex":127,"id":"exchange-057"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。今回の能登半島の地震でも、ある地域では５分間で全ての地域の方が避難できた。本当に命を守るために避難ができる訓練をぜひ心がけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-058"},{"speaker":"吉田委員","kind":"提案","question":"今、様々ご意見が出ました。やはりこのような一斉の防災訓練は、基本、町会が参加されているわけですから、そのような中から、例えば訓練については、このようなメニューもありますということを冊子でお示ししながら、提案されるということは、有効かと思うのですけれども、実際そのようなことはされているのかを伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"一方で、区の職員からも提案できる機会でもあると思いますので、そのようなところを活用して、訓練の内容につきましては決定をして、よりよい訓練ができるように進めてまいりたいと考えています。","voiceIndex":131,"id":"exchange-059"},{"speaker":"吉田委員","kind":"質問・要望","question":"ああいうゲームはやってみたらいいかと。やはり町会が主体的に進めるべきなので、このようなものはどうですかといっても、そのまま実現するかどうか分かりませんけれども、私は力作だと思っていて、せっかくそのようなものがあるのであればぜひ活用していただきたいし、これからも『しながわ防災訓練ガイド』については更新をしていただきたいと思いますが、もし何かお考えがあったら伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"『しながわ防災訓練ガイド』につきましては、非常にいいところもあれば、もしかしたら古いところもあります。見直しのほうは、検討させていただければと考えております。","voiceIndex":133,"id":"exchange-060"},{"speaker":"吉田委員","kind":"提案","question":"ぜひ、改定を進めながら、提案の強さはどの程度、可能なのか分かりませんけれども、せっかくそのようなものが用意されているし、職員もそのようなところには、もし提案があれば参加するという心積もりになっているのであれば、今後ぜひ有効に活かしていただきたいと思います。これは要望でとどめます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-061"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"何点か端的にお伺いします。ただ、それ以外の地域の方に対しての啓発は、そもそもどのような方をどれぐらい集めようという目標を立てていらっしゃるのかを教えていただきたい。そうすると、強制はできないとは思うのですけれども、ほかの学校では、このように子どもたちを集めてくれたのですけれども、駄目なのですかというような圧というとあれですけれども、ここの濃淡を埋めたほうがいいと思うのです。","respondent":"伊藤災害対策担当課長","answer":"ただ、生徒にとっては、正直に言えば、２年に一遍しか参加できない訓練ですので、そのようなところは、しっかりと地域の町会の皆様と連携をして、訓練をしていただいて、未来の品川区を支えていただく。","voiceIndex":137,"id":"exchange-062"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"ありがとうございました。そうすると。１８０という単位は、やはり足りないのではないかと思うので、当然、全部の町会・自治会がしっかりと参加をしていくというところはマストにしないといけないのだろうと思います。その上で、町会・自治会の参加者数はどんどん伸ばしていかないといけないと思うので、これは要望します。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-063","title":"町会・自治会支援"},{"speaker":"須貝委員","kind":"質問","question":"大半の人は、防災訓練をやっていると知らないのです。町会には掲示板があって、回覧板があるのですが、やはり見ない人が多数で、一時、町会のほうでも、町会の中にいて、個別にポスティングしたことがあって、そのときには、それが原因かどうかは分からないのですが、かなり来てくださったことが、事例としてありました。ですから、そのような方たちに何とか来ていただくような手法を取る。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-064"},{"speaker":"鈴木副委員長","kind":"質問","question":"ほかにはご意見いかがでしょうか。よろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-065"},{"speaker":"鈴木副委員長","kind":"意見","question":"最後に、１点ご案内を申し上げます。次回２月２９日の委員会における特定事件調査は、防災に関することとして、災害廃棄物処理計画を取り上げることで調整をしていますことをお伝えいたします。以上でその他を終了いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":144,"id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6648#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":65641,"voices":144}},{"id":"r06-20240125-10","meetingId":"r06-cm01","date":"2024年1月25日","dateIso":"2024-01-25","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"前回、議員辞職勧告決議案を共産党から出さないのかというような質疑をいただきまして、持ち帰って検討みたいな形になったのですけれども、今、継続して検討中で、まだ結論が出ていないです。やはり前回も申し上げたように、二次被害を防ぐという観点からどうなのかというところで今継続して検討中で、まだ結論が出ていないので申し訳ないのですが、今の時点ではそんな状況です。","respondent":"渡辺議長","answer":"もちろん、前回公式にそのような発言があったので、あるいはマスコミ報道もあった関連から、議会としての対応の質疑もありましたので、動きがありましたら、引き続き情報をいただければという思いであります。それとは別に、前回は共産党からそういうご発言がありました。","voiceIndex":20,"id":"exchange-001"},{"speaker":"須貝委員","kind":"意見","question":"ただ、今、議長からもお話のあったとおり、中塚議員の真意というのはどうなのだということ。いろいろ公表している事実は、書面はあるのですが、もしできるなら、議長のほうから本人に真意を尋ねていただいて、議会としては放置するわけにはいかないので、やはりそれなりの対応は取らせていただきますと明確にお話ししたほうがいいのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-002"},{"speaker":"塚本委員","kind":"提案","question":"議長のご提案である中塚氏からお話を聞くというのは、なされるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-003"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"今おおむねお話しいただいたとおりでありますが、共産党のほうでの処分といいますか、処遇というのは、それはそれで党の中でされていらっしゃるのだと思いますが、品川区議会としてという話をこれからしていくというところであれば、やはり一方から聞いて、一方から聞かないというのは問題になりかねませんので、しっかり聞いていただきたいというのがまず１点。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-004"},{"speaker":"松永委員","kind":"意見","question":"今後についても、先ほど共産党からありましたように、お相手のこともありますので、進め方というものを、議会は議会で進めていただいて、共産党は共産党で進めていただくほうがいいのかと思っておりまして、そこに関しては、正副議長と正副委員長にお任せしたいと思います。","respondent":"渡辺議長","answer":"今全ての会派からのご意見を賜ったと思っています。先ほど、須貝委員もおっしゃっていたように、やはり放置するのではなく、議会としての速やかな対応をまず第一に意識しながら進めたいと思います。","voiceIndex":29,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"本当に重ね重ね、あってはならないことで、こんな事態になってしまったということは申し訳ないと思うのですけれども、辞職すべきだし、私たちも辞職を求めてきたという前提では、前回の見解と何ら変わりがないです。","respondent":"あくつ副議長","answer":"先ほど渡辺議長のほうから安藤委員のほうに、１２月２６日の議会運営委員会での安藤委員の発言を基に、冒頭、今どのようにお考えですかというところで、二次被害というところを考慮してご検討中だというお話がありましたが、このご発言があってから１か月が経過をしました。","voiceIndex":31,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"辞職しないということは、結局、辞職するべきようなことではないということになって、反省していないということになりますので、当然それは許されないと被害者の方も思っているです。思っていることだろうと思いますといいますか、繰り返しますが、これ以上は、見解以上のことは述べないという立場ですので、控えさせていただきたいと思います。","respondent":"渡辺議長","answer":"確認なのですが、まず、前提のところは変わりないという安藤委員の発言がありましたので、共産党の見解、会派の見解、ならびに、発言を受けて、私たちの立場、議会、皆さんも含めてなのですが、まず看過できない内容であるということで。対応の内容、どんな場がふさわしいかとか、あと、どんな配慮が必要かも含めてご一任いただければと思うのですが、よろしいでしょうか。","voiceIndex":35,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、第三者という発言もありましたが、第三者の方に、この人だとかどうだとかというのではなくて、共産党が出している声明で、こういうことがありましたと。これに対して共産党は議員辞職を求めたということで、第三者にあまり関わらないような方向で、我々はその事態、その事象に対してどうあるべきかということでいいのではないですか。","respondent":"渡辺議長","answer":"今のご指摘も踏まえて、まず、議会の範囲内というのが、これは私も限界だと思います。いろいろな意味で限界もありますが、まず責任を持てる議会の範囲内で、第一歩、対応をしていきたいと考えています。","voiceIndex":38,"id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"ペットボトルとなると、結構、国の審議会とかでも、ペットボトルが並んでいるところを見て、それが環境審議会とかをやっていると、何をやっているのだみたいな意見も結構いただいて、若い人がやはり環境にすごく敏感なので、そういう意味では、お茶というのはすごくある意味、環境に優しいというか、リターナブルという面もあるのかということで、でも、それだけで全体を決めるわけにいかないのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-009"},{"speaker":"須貝委員","kind":"提案","question":"議長の提案は、私はすばらしい提案だと考えています。入れていただくこととか、手間を考えるならば、やはりマイボトルか、私は一時的にペットボトルにして、将来的にマイボトルに持っていくとか、何かそういう方向でやっていったらどうかと思います。私は議長の提案はすばらしいと思うので、ぜひ、いい方向に進んでいただければいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-010"},{"speaker":"こんの委員","kind":"提案","question":"ほかの委員のご発言と同じで、よい提案だと思います。細かいことで大変恐縮なのですが、確認です。湯飲み茶わんを廃止する、マイボトルを持ってくる。このマイボトルを委員会のテーブルの上に各自置くというような、そんなところが、今後、予算特別委員会から実施されたらどうかというご提案なので、その予算特別委員会の中での理事で決めていくのか、その辺のイメージを確認させてください。","respondent":"渡辺議長","answer":"取扱いなのですが、各委員会単位だと混乱するおそれがあるので、まず、議会運営委員会でお諮りして、議会運営全般の共通認識をもって進められたらと思います。","voiceIndex":49,"id":"exchange-011"},{"speaker":"山本委員","kind":"提案","question":"当会派としても、いい提案だと思っておりまして、基本方針としては進めていただきたいと考えています。お茶の提供廃止、マイボトルの利用。先ほど議長からもご説明がありましたマイボトルの運用等、または、マイボトルがどのようなものがいいのかとか、そういう細かなところについては適切な形で進めていただきたいと思っているところで、進めることについて賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-012"},{"speaker":"せりざわ委員","kind":"提案","question":"ご提案いただいたところは全て賛成ですので、ぜひ進めていただきたいというところと、会派でも少しお話しして、意見が出て、なるほどと思ったのは、議員だけではなくて、理事者、行政側も今、お茶が出ていて、飲んでいる方もよくいらっしゃるのですが、これも多分同様に廃止になるのだろうと思うので、そこのマイボトルの持込みの推奨というところでいうと、なるべく議会が全体でどんどん進めて。","respondent":"渡辺議長","answer":"進め方のところだけ、安藤委員からもありましたように、今日拙速に結論を出すのではなく、一回持ち帰る形にしたいと思います。持ち帰った後、副議長と相談をして、正副議長案として、次回の議会運営委員会前に原案はお示ししたいと思います。","voiceIndex":53,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5534#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":14611,"voices":65}},{"id":"r06-20240219-10","meetingId":"r06-cm02","date":"2024年2月19日","dateIso":"2024-02-19","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時２３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和６年第１回定例会","agenda":"令和６年第１回定例会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"新庁舎について１点だけお伺いしますけれども、先日の議員対象の説明会でも実際の工事の着手時期は来年、２０２５年の半ばくらいと示されていたと思うのですが、この位置条例をなぜ今回の第１回定例会に提出するのかという理由だけ伺いたいと思います。","respondent":"桑村副区長","answer":"もう一つは、令和６年度は実施設計に入るという、非常に細かい中身の設計に入ってまいりますので、この時点でご議決をいただいて、その意味では、私ども行政とすれば、安心して設計に入りたいというのがありますので、ぜひお願いを申し上げるものです。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"お願いというか、一つは、意見表明の原稿提出の締切なのですけれども、３月２１日ではないですか。この日は、総括質疑、意見表明の日なのですが、その日のうちに提出というのはかなり厳しいのではないかと思って、日程の改善が必要なのではないかと思っているのです。何かあればぜひご見解をいただきたいです。今日は頭出しといいますか、そういったことになります。","respondent":"大澤区議会事務局長","answer":"原稿提出につきましては、事務局と正副委員長とでまた検討させていただければと存じます。","voiceIndex":21,"id":"exchange-002"}]},{"id":"topic-03","title":"品川区議会委員会条例","agenda":"品川区議会委員会条例","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"賛否の態度は別の機会になると思うのですけれども、私たちとしては、組織改正条例に反対した立場上、提案者になるかどうかということも含めて、また検討させていただきたいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-003"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"どうしたのだ、その後どうなったのだということで、いや、今、議会のほうでいろいろ本人に確認したりして対応を進めていますということで話をしたら、逆に嫌な言い方をされてしまうのですが、隠蔽しているのではないかということまで言われたので、いや、そういうことはこの品川区議会についてはありませんと明確にはお話ししたのですが、どうもそういうようなことで、遅らせれば遅らせるほど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-004"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"当事者からの聴取といいますか、意見を聞く場もあったということで、それは非常によかったなと思うのですが、一方で、事実関係はいろいろ確認できたとはいえども、やはり当然被害者の意向であったりとかという話も我々はなかなか感知できるところではないので、そういったこれからの進め方というところ、当時からいろいろお話をいただいてはおりますが、やはり当事者に一番近い共産党から。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"いろいろご意見ありがとうあります。そうである以上、議会として何もしないというわけにはいかないと思うのです。その場でも私は表明させていただいたのですが、共産党としては、ぜひ議会全体で議員辞職勧告を行うということで検討を進めていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"やはり辞職勧告ということを会派としてとか、あるいは議会として出すというような結論に至るというのは、なかなか難しい、確認しなければいけない分からないことというのが多過ぎるというところがあるので、ここはやはり共産党から出していただくということが、そしてその内容について我々でどう判断するかという進め方が自然ではないのかなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-007"},{"speaker":"松永委員","kind":"質問","question":"私たちの会派も、幹事長の出席の下、中塚議員のご説明をいろいろお聞きした中で、先ほども意見があったように、私たちの会派でも、当事者と中塚議員の関係性というのがまだ全然見えていない状況で、この間行われたヒアリングの中でそれははっきりと見えてきませんでしたので、議会全体で辞職勧告を出すというのは、私たちの会派はちょっと難しいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-008"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"先ほど公明党からもお話しいただいたところに非常に近いところがあるのですが、共産党としては、議会全体で決議を出していただきたいというお話だったと思います。とはいえ、やはり提出者、これは一番最初に出す方が誰なのかというところで、第三者である我々が出して、それに共産党が乗るという形は、スタートとして、手続き論としておかしいのかなと思うのです。これは要望として、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"議会で出す決議案とか意見書などは、やはり全会一致で出せるように努力をした上で出すと思うのですけれども、当然私たちとしても、私たちが単独で出して、乗るか乗らないか、どうだということよりも、事前にぜひ議会の皆さんで一致できるような内容で出せるような努力はしていきたいと思うので、その過程で、これは議会として一緒に出そうということになれば、ぜひ出していただきたいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"今、共産党とか議会が出すとかいう話ではなくて、品川区議会議員、品川区議会が何をやっているのだということを区民の皆さんが、あちこちとは言いませんけれども、そういう話で来ているのです。これを延ばせば、いろいろ共産党はこう考えて、議会はこう考えて、延ばせば延ばすほど、我々はそのことに対して何も対応していないのではないかと見られるのが、これはやはり区民の感情ではないですか。","respondent":"渡辺議長","answer":"オール議会という形で進める案件だと思っています。その中で、やはり実務のところで、今ご発言いただいたように議長・副議長も努力はしていますが、実務のところでお力を借りたいと思います。共産党を中心にというご発言も先ほどありましたので、努力をされると。","voiceIndex":51,"id":"exchange-011"},{"speaker":"須貝委員","kind":"意見","question":"ひな形とかがあれば、それはそれで別に共産党と一緒にやることはやぶさかでないですが、そういうふうにしていいものならば、それなりに動きます。ただ、すみません、私はそういう文面をつくる云々ということに関しては疎いので、ひな形があればぜひ共産党と協力して、つくっていいということを議会運営委員の皆さんが承認されるなら、そういうふうにさせていただければありがたいと思います。","respondent":"渡辺議長","answer":"あくまでも案文ですから、それを皆さんにまたご意見を伺うということで、それが大きな一歩になると思いますので、ぜひともお願いいたします。","voiceIndex":53,"id":"exchange-012"},{"speaker":"須貝委員","kind":"提案","question":"議長から、飲料の持込みについて実にいいご提案がありました。それはすごくいいことなのかなと思う反面、費用の面もあるので、設備とか、その辺についてご検討くださるかどうか、提案します。","respondent":"渡辺議長","answer":"とても前向きなご提案なので、大事に受け止めまして、相手のある話ですが、ぜひ交渉したいと思います。","voiceIndex":56,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5536#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":17314,"voices":70}},{"id":"r06-20240220-10","meetingId":"r06-cm02","date":"2024年2月20日","dateIso":"2024-02-20","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5538#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":1518,"voices":12}},{"id":"r06-20240222-3","meetingId":"r06-c-budget","date":"2024年2月22日","dateIso":"2024-02-22","committee":"予算特別委員会","time":"午前１１時５２分～午前１１時５９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6683#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":1950,"voices":17}}]);
